window.__D("text/zohar-chadash/c004",{"p":[[9514012958,"<p>לֹא תִשָּׂא, בְּרָזָא דְת\"ת, דְּאִקְּרֵי אֱמֶת, דְּאָחִיד בָּהּ יַעֲקֹב שְׁלֵימָא, וְיָנֵיק תְּרֵי חוּלָקִין, מִצְוֹת עֲשֵׂה וּמִצְוַת לֹא תַּעֲשֶׂה. דִּכְתִיב, (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם יוֹשֵׁב אֹהֳלִים. וְעַל דְּאִיהוּ אַשְׁלֵים לְכָל סִטְרִין, לְרַחֲמֵי וּלְדִינָא, לְמִצְוֹת עֲשֵׂה וּלְמִצְוֹת לֹא תַּעֲשֶׂה, אִיקְּרֵי שְׁלִים. וּלְקִבְלֵיהּ לֹא תִשָּׂא, בְּגִין דִּשְׁבוּעָתָא לִשְׁלָמָא אָתֵי. וְעַל דָּא אִיהוּ בְּרָזָא דַּעֲשֵׂה וְלֹא תַעֲשֶׂה. דִּכְמָא דְּאִיהִי לֹא תַּעֲשֶׂה כַּד אִיהִי לְשִׁקְרָא, דִּכְתִיב (שמות כ) לֹא תִשָּׂא. הָכֵי אִיהִי מִצְוֹת עֲשֵׂה, כַּד אִיהִי בֶּאֱמֶת, דִּכְתִיב (ירמיהו ד׳:ב׳) וְנִשְׁבַּעְתָּ חַי ה' בֶּאֱמֶת. וּכְתִיב (דברים ו) וּבִשְׁמוֹ תִּשָּׁבֵעַ.</p>"],[9514012959,"<p>(שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַּׁבָּת, בְּרָזָא דִּבְרִית, דְּאִיהוּ יְסוֹד, דְּאָחֵיד בֵּיהּ יוֹסֵף. וְעַל דָּא אִקְּרֵי שַׁבָּת. דְּהָא יוֹסֵף כָּל אִקְּרֵי, וְשַׁבָּת נָמֵי אִיקְּרֵי כֹּל. בְּגִין דְּכָל עִינּוּגָא וְתַפְנוּקָא נָפֵיק מִנֵּיהּ, לְקַיָּימָא לְעָלְמִין כָּלְהוֹ. וְעַל דָּא שַׁבָּת כְּלִילָא מֵעֲשֵׂה וְלֹא תַעֲשֶׂה. בְּגִין דְּיוֹסֵף נָמֵי בּוּכְרָא, דְּנָטֵיל תְּרֵין חוּלָקִין.</p>"],[9514012960,"<p>תָּא חֲזֵי, כְּתִיב בַּדִּבְּרוֹת בְּמִשְׁנֶה תּוֹרָה, (דברים ה׳:ט״ו) וְזָכַרְתָּ כִּי עֶבֶד הָיִיתָ בְּאֶרֶץ מִצְרָיִם וַיִּפְדְּךָ ה' אֱלֹהֶיךָ מִשָּׁם בְּיָד חֲזָקָה וּבִזְרֹעַ נְטוּיָה עַל כֵּן צִוְּךָ ה' אֱלֹהֶיךָ לַעֲשׂוֹת אֶת יוֹם הַשַּׁבָּת. הָכָא אוֹלִיף לָן אוֹרַיְיתָא רָזָא עִילָּאָה, דְּהָא הַהוּא צַדִּיקָא דְּאִזְדַּבַּן לְעַבְדָּא בְּמִצְרַיִם, וַאֲחִילוּ לֵיהּ. לְקִבְלֵיהּ אִיהוּ זָכוֹר אֶת יוֹם הַשַּׁבָּת. וּבְגִין כָּךְ אֲמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, בְּבָעוֹ מִנְכוֹן הֲווֹ דְּכִירִין הַהוּא צַדִּיקָא דְּאִזְדַּבַּן עַל יְדַיְכוּ, וַהֲוָה לְעַבְדָּא בְּמִצְרַיִם, וּבְהַהוּא חוֹבָא אִתְגְּזַר עֲלַיְיכוּ לְאִשְׁתַּעְבְּדָא בְּמִצְרַיִם, וּלְכַפָּרָא הַהוּא חוֹבָה דְּזַבִּינְתּוּן לֵיהּ. נְטָרוּ יוֹמָא דְּשַׁבַּתָּא, וְיִשְׁתְּבֵיק לְכוֹן, דְּהָא יוֹמָא דְּשַׁבַּתָּא לְקִבְלֵיהּ אִיהוּ.</p>"],[9514012961,"<p>כִהְאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא. יוֹמָא קַדְמָאָה, לְקִבְלֵיהּ דְּאַבְרָהָם. הֲדָא הוּא דִכְתִיב, (תהילים נ״ב:ג׳) חֶסֶד אֵל כָּל הַיּוֹם. יוֹמָא תִּנְיָינָא, לְקִבְלֵיהּ דְּיִצְחָק. וּבְגִין כָּךְ בֵּיהּ יְתֵיב קוּדְשָׁא בְּרִיךְ הוּא לְמֵידַן עָלְמָא. יוֹמָא תְּלִיתָאָה לְקִבְלֵיהּ דְּיַעֲקֹב, דְּאִיהוּ קַו הָאֶמְצָעִי, וּבְגִין כָּךְ כְּתִיב בֵּיהּ בְּעוֹבָדָא דִּבְרֵאשִׁית, (בראשית א) יִקָּווּ הַמַּיִם.</p>"],[9514012962,"<p>יוֹמָא רְבִיעָאָה, לְקִבְלֵיהּ דְּדָוִד. דִּכְתִיב בֵּיהּ, (שם) יְהִי מְאוֹרוֹת. מְאֹרֹת חָסֵר, דְּהָא כְּנֶסֶת יִשְׂרָאֵל לֵית לָהּ נְהוֹרָא מִדִּילָהּ, אֶלָּא מַה דְּאִיתְיְיהֵב לָהּ עַל יְדָא דְּצַדִּיקָא. הָכֵי נָמֵי דָּוִד, דִּכְתִיב בֵּיהּ (תהילים פ״ו:א׳) עָנִי וְאֶבְיוֹן אָנִי, וְלֵית לֵיהּ חַיִּים, אֶלָּא מַה דְּאִתְיְהֵיב לֵיהּ מִיּוֹמֵי דְּאָדָם קַדְמָאָה, ע' שְׁנִין.</p>"],[9514012963,"<p>יוֹמָא חֲמִישָׁאָה, לְקִבְלֵיהּ דְּמשֶׁה. יוֹמָא שְׁתִיתָאָה, לְקִבְלֵיהּ דְּאַהֲרֹן. וְאִינוּן שֵׁשֶׁת יְמֵי בְרֵאשִׁית לְתַתָּא, לָקֳבֵיל שֵׁשֶׁת יְמֵי בְרֵאשִׁית דִּלְעֵילָא. וּמַאן אִינוּן שֵׁשֶׁת יְמֵי בְרֵאשִׁית לְעֵילָא. אִינוּן דִּרְמִיזוּ בִּקְרָא, (דברי הימים א כ״ט:י״א) לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוֹד כִּי כֹל וְגו' לְךָ ה' הַמַּמְלָכָה. וְאִינוּן חוּלָקֵיהוֹן דְּצַדִּיקַיָא בְּרָזָא דָּא, הַגְּדֻלָּה: דָּא אַבְרָהָם. הַגְּבוּרָה: יִצְחָק. הַתִּפְאֶרֶת: יַעֲקֹב. הַנֵּצַח: חוּלָקָא דְּמשֶׁה. הַהוֹד: חוּלָקָא דְאַהֲרֹן. כִּי כֹל: לָקֳבֵיל חוּלָקָא דְּיוֹסֵף. הַמַּמְלָכָה: חוּלָקָא דְּדָוִד. וְיוֹסֵף שַׁבָּת אִקְּרֵי לְתַתָּא, לָקֳבֵיל צַדִּיק חֵי הָעוֹלָמִים, וְאִקְּרֵי שַׁבָּת לְעֵילָא. וּבְגִין כָּךְ כְּתִיב, (דברים ה׳:ט״ו) עַל כֵּן צִוְּךָ ה' אֱלֹהֶיךָ לַעֲשׂוֹת אֶת יוֹם הַשַּׁבָּת.</p>"],[9514012964,"<p>תָּא חֲזֵי, כַּד בְּעוֹ יִשְׂרָאֵל לְמִכְבַּשׁ לְאַרְעָא דִכְנָעַן, אֲקִיפוּ לָהּ שִׁיתָּא יוֹמִין, זִמְנָא חָדָא בְּכָל יוֹמָא, לָקֳבֵיל אִינוּן שִׁית זַכָּאֵי קְשׁוֹט דַּעֲלֵיהוֹן מִתְקַיֵּים עָלְמָא. וּבְיוֹמָא שְׁבִיעָאָה שֶׁבַע זִמְנִין, לָקֳבֵיל יוֹמָא דְּשַׁבַּתָּא, דְּאִיהוּ לָקֳבֵיל צַדִּיק, דְּאִיהוּ זָן לְכוּלְהוֹ, וּמְקַיִּים לְהוֹן, דִּכְתִיב (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. וּכְתִיב (שם י) וְצַדִּיק יְסוֹד עוֹלָם. אִיהוּ יְסוֹדָא וְעִיקָּרָא דְּכָל אִינוּן זַכָּאִין, וְאִי לָא זְכוּתְהוֹן דְּצַדִּיקַיָּא, לָא הֲווֹ יָכְלִין לְמִכְבְּשָׁהּ. הֲדָא הוּא דִכְתִיב, (דברים ט׳:ה׳) לֹא בְצִדְקָתְךָ וּבְישֶׁר לְבָבְךָ אַתָּה בָא לָרֶשֶׁת כו', וּלְמַעַן הָקִים אֶת הַדָּבָר אֲשֶׁר נִשְׁבַּע ה' לַאֲבֹתֶיךָ לְאַבְרָהָם כו'.</p>"],[9514012965,"<p>(שמות כ׳:י״ב) כַּבֵּד אֶת אָבִיךָ, בְּרָזָא דְנֶצַּח, דְּאָחִיד בָּהּ משֶׁה, וְיַנִּיק לָהּ, דְּהָא משֶׁה הֲוָה אוֹקִיר לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְיתָא. תָּא חֲזֵי, אִי לָאו אוֹרַיְיתָא דְּאִתְיַיהֲבַת עַל יְדוֹי דְמשֶׁה נְבִיאָה רַבָּא, לָא הֲווֹ יָדְעִין בְּנֵי נָשָׁא לְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא הֲווֹ מוֹקְרִין לֵיהּ, דְּהָא עַל יְדָא דְאוֹרַיְיתָא אוֹלֵיף בַּר נָשׁ פּוּלְחָנָא דְמָארֵיהּ, וְאוֹקִיר לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ כַּבֵד אֶת אָבִיךָ וְאֶת אִמֶּךָ, לָקֳבֵיל דְּמשֶׁה אִיהוּ.</p>"],[9514012966,"<p>דָּבָר אַחֵר, כַּבֵּד אֶת אָבִיךָ, זוֹ תּוֹרָה שֶׁבִּכְתָב. וְאֶת אִמֶּךָ, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. דִּכְמָא דְאַבָּא יָהֵיב שֶׁפַע לְאִימָּא, הָכִי נָמֵי יָהֵיב שֶׁפַע תּוֹרָה שֶׁבִּכְתַב לְתוֹרָה שֶׁבְּעַל פֶּה.</p>"],[9514012967,"<p>(שם) לֹא תִרְצָח, לָקֳבֵיל דַּרְגָּא דְהוֹד, דְּאָחִיד בָּהּ אַהֲרֹן. וּבְגִין כָּךְ לֹא תִרְצָח. בְּגִין דְּכַד קָטְלִין לֵיהּ לְבַּר נָשׁ, הַהוּא זִיוָא וְהוֹד עִילָּאָה דַּעֲלֵיהּ, נָטְלִין מִנֵּיהּ. הֲדָא הוּא דִכְתִיב, (דניאל י׳:ח׳) וְהוֹדִי נֶהְפַּךְ עָלַי לְמַשְׁחִית. וּבְגִין כָּךְ אַזְהֵיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִבְנֵי נָשָׁא, דְּהַהוּא שׁוּפְרָא עִילָּאָה דִּיהַב לוֹן, דְּלָא יִטְלוּן לֵיהּ מִנְּהוֹן. וְאִית נָמֵי רָזָא דִּשְׁלָמָא, וּבְגִין כָּךְ קָאִים אַהֲרֹן לְכַפָּרָא, לְנִכְסָא נִכְסַת קוּדְשִׁין. וְעַל פּוּמֵיהּ כַּפֵּר לְעַמְּךָ יִשְׂרָאֵל אֲשֶׁר פָּדִיתָ.</p>"],[9514012968,"<p>(שמות כ) לֹא תִנְאָף, בְּרָזָא דְמַלְכוּת. דְּאָחִיד בָּהּ מַאן דְּאָחִיד. וְאִיהוּ רָזָא דְּחָכְמְתָא, דְּהָא כְּנֶסֶת יִשְׂרָאֵל לָא אִתְחַבְּרַת אֶלָּא בְּהַהוּא דְּחָזֵי לָהּ, דְּאִיהוּ צַדִּיק יְסוֹד עוֹלָם. דָּבָר אַחֵר, הָכֵי אוֹלִיפְנָא בְּרָזָא דִמְהֵימְנוּתָא. כַּבֵּד, לָקֳבֵל כְּנֶסֶת יִשְׂרָאֵל. לֹא תִרְצָח, לָקֳבֵל דַּרְגָּא דְּנֶצַח. לֹא תִנְאָף, לָקֳבֵל דַּרְגָּא דְּהוֹד.</p>"],[9514012969,"<p>דָּבָר אַחֵר, כַּבֵּד, לָקֳבֵיל יְהִי מְאוֹרוֹת, דְּעוֹבָדָא דִּבְרֵאשִׁית. לֹא תִרְצָח, לָקֳבֵל (בראשית א׳:כ׳) יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה. בְּגִין כָּךְ נֶפֶשׁ חַיָּה לָא תִקְטוֹל. לֹא תִנְאָף, לָקֳבֵיל (שם) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. בְּגִין כָּךְ, לֹא תִנְאָף בְּאִיתְּתָא דְּלָאו מִינָךְ, דְּלָאו אִיהִי בַּת זוּגָךְ.</p>"],[9514012970,"<p>לֹא תִגְנֹב, לֹא תַעֲנֶה, לֹא תַחְמֹד. דָּא הוּא סִיּוּמָא דְּעֶשֶׂר אֲמִירָן דְּאוֹרַיְיתָא, לָקֳבֵל עַתִּיקָא דְּעַתִּיקִין, רֵאשִׁיתָא דְּכֹלָּא לְאַחֲדָא סוֹפָא בְּרֵישָׁא, וְלִמְהֱוֵי כֹּלָּא חַד. וְהַאי דְּלָא שָׁארֵי בְּהוּ בְּקַדְמִיתָא. לְאוֹלָפָא רָזָא עִילָּאָה, עַד אָן אֲתַר אִתְיְיהֵיב רְשׁוּתָא לְמשֶׁה לְאִסְתַּכָּלָא, וּמֵאָן אֲתַר קַבֵּיל אוֹרַיְיתָא, דְּהוּא מִזְּעֵיר אַנְפִּין.</p>"],[9514012971,"<p>וּבְגִין כָּךְ אֲמַר שֶׁבַע אֲמִירָן, לָקֳבֵל שֶׁבַע דַּרְגִּין עִילָּאִין, דִּרְמִיזִין בִּקְּרָא (דברי הימים א כט) דִּלְּךָ ה' הַגְּדֻלָּה וכו'. וְעַד הַהוּא אֲתַר אִסְתַּכַּל משֶׁה, הֲדָא הוּא דִכְתִיב, (דברים ה׳:ד׳) פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם. פָּנִים, דָּא בְּרָא קַדִּישָׁא, בְּפָנִים, דָּא בְּרַתָּא.</p>"],[9514012972,"<p>פָּנִים, דָּא בְּרִית. בְּפָנִים, דָּא אָרוֹן. וְכֵיוָן דְּאִתְחַבָּרוּ, דִּבֶּר ה'. וּמַאי נִיהוּ. שֶׁבַע אֲמִירָן, בְּאִינוּן תְּלָתָא דַּרְגִּין עִילָּאִין דְּעַתִּיקָא קַדִּישָׁא, אִתְאֲמָרוֹ לְקִבְלֵיהוֹן תְּלָתָא אֲמִירָן בַּתְרָאִין, וּסְלִיקוּ מִתַּתָּא לְעֵילָא.</p>"],[9514012973,"<p>וְאָמַר לֹא תִגְנֹב, לָקֳבֵל אִימָּא עִילָּאָה, בִּינָה, דְּיָנְקָא מֵחָכְמָה. וּמַאן דְּאִית בֵּיהּ בִּינָה, אִיקְּרֵי מֵבִין דָּבָר מִתּוֹךְ דָּבָר. כְּמַאן דְּגָנִיב וּנְסִיב מַה דְּאִית בְּלִבָּא דְּחָכָם, דְּאוֹלִיף לֵיהּ חָכְמְתָא, וְאוֹלִיף לֵיהּ אוֹרַיְיתָא. וְאַף עַל גַּב דְּאִשְׁתְּרֵי לְגַבֵּיהּ בִּינָה לְיָנְקָא מֵחָכְמְתָא. גְּנִיבָא אִית מִסִּטְרָא אָחֳרָא דְּאָסִיר, וַאֲמַר לֹא תִגְנֹב סְתָם.</p>"],[9514012974,"<p>(שמות כ׳:י״ג) לֹא תַעֲנֶה, לָקֳבֵיל דַּרְגָּא עִילָּאָה דְּחָכְמְתָא. דְּהָא בַּר נָשׁ לָא יָכֵיל לַאֲתָבָא פִּתְגָם, אֶלָּא בְּגִין דַּרְגָא דְּרוּחָא עִילָּאָה דְּחָכְמְתָא דְּאִית בֵּיהּ. דִּכְתִיב, (איוב ט״ו:ב׳) הֶחָכָם יַעֲנֶה דַּעַת רוּחַ. וְאַף עַל גַּב דְּהַאי עֲנִיָּיה דְּאִיהוּ עָנִי, אִית בֵּיהּ קִיּוּמָא דְעָלְמָא, וְאִית לֵיהּ בָּהּ סִיּוּעַ עִילָּאָה, לְמִנְדַע לְמָארֵיהּ, וְאִיהִי בְּרָזָא דִּמְהֵימְנוּתָא. אִית עֲנִיָּיה מִסִּטְרָא אָחֳרָא דְּאָסִיר, דִּכְתִיב (שמות כ) לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר.</p>"],[9514012975,"<p>(שם) לֹא תַחְמֹד, לָקֳבֵל דַּרְגָּא סְתִימָאָה עִילָּאָה, דְּכָל מַחְשַׁבְתָּן בֵּיהּ תַּלְיָין, וְלֵית בְּעָלְמָא דְּיִנְדַע הַהוּא דַרְגָּא, בְּגִין דְּאִיהוּ סְתִימָאָה דִסְתִימִין. וְכַד סָלֵיק בְּמַחֲשָׁבָה עִילָּאָה, לְמִיבְרָא, עָלְמָא עִילָּאָה וְעָלְמָא תַּתָּאָה, כּוֹלָּא הֲווֹ בְּרִגְעָא חָדָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ח:י״ג) יַעַמְדוּ יַחְדָּו. וְהַהוּא מַחֲשָׁבָה סְתִימָא.</p>"],[9514012976,"<p>וּבַּר נָשׁ לְתַתָּא, אִית לֵיהּ מַחֲשָׁבָה סְתִימָאָה, דְּלֵית דְּיָדַע בָּהּ, בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וְיַהֲבָהּ לֵיהּ לְבַּר נָשׁ, לְמֶחְשַׁב מִלִּין דְּאוֹרַיְיתָא, מִלִּין דְּמִצְוָה. בְּגִין דְּהַהִיא מַחֲשָׁבָה עִילָּאָה, נַגְדָא מַבּוּעִין דִּילָהּ, לְאַתְרָא דְּחָכְמְתָא, וְלָא אִתְפְּרַשׁ כְּלָל. וּמֵהַהִיא חָכְמְתָא עִילָּאָה נָפְקָא תּוֹרָה. וְנָגִיד שַׁקְיוּתָא עַד הַהוּא אֲתַר דְחָכְמָה תַּתָּאָה, דְּאִיקְּרֵי מִצְוָה.</p>"],[9514012977,"<p>וְעַל דָּא מַאן דְּחָשִׁיב לְמֶעְבַּד מִצְוָה, כְּאִלּוּ עֲשָׂאָהּ. בְּגִין דְּגָרֵים לְמֵיתֵי סִיפּוּקָא דְּבִרְכָאן, מֵהַהוּא מַחֲשָׁבָה עִילָּאָה, לַאֲתַר דְּאִקְרֵי מִצְוָה. וּכְאִלּוּ עֲשָׂאָהּ. כְּמָה דְאַתְּ אָמֵר וַעֲשִׂיתֶם אֹתָם. מַחֲשָׁבָה וַדַּאי רֵישָׁא דְּכוֹלָּא. וְאַף עַל גַּב דִּבְסִטְרָא דְּמַחֲשָׁבָה עִילָּאָה אִתְיְיהַב לֵיהּ רְשׁוּתָא לְמֶחְשַׁב. מִלִּין דְּמִצְוָה מוּתָּר, מִלִּין דְּלָאו מִצְוָה, אֲסִירָן, דִּכְתִיב לֹא תַחְמֹד.</p>"],[9514012978,"<p>וְתָּא חֲזֵי, מַאי טַעְמָא כָּלְהוֹ אֲמִירָאן, לָקֳבֵל כָּל כִּתְרָא, מִצְוֹת עֲשֵׂה בְּאַתְרָא דְּחָזֵי לֵיהּ, מִצְוַת לֹא תַּעֲשֶׂה בְּאַתְרָא דְּחָזֵי לֵיהּ. וְאִינוּן תְּלָתָא בַּתְרָאי, אִינוּן לֹא תַעֲשֶׂה, מִכְּלַל דַּעֲשֵׂה, כִּדְאוֹקִימְנָא בְּכוֹלָּא, אַף עַל גַּב דְּהַאי שָׁרֵי, הַאי אָסוּר. דִּבְגִין דְּאִינוּן לָקֳבֵל עַתִּיקָא דְּעַתִּיקִין, דְּחֶסֶד וְרַחֲמִים גְּדוֹלִים בֵּיהּ שָׁרְיָין, וְלָא אִתְחֲזֵי אֶלָּא לְמִצְוַת עֲשֵׂה. בְּגִינֵי כָּךְ דַּיֵּיק מִנַיְיהוּ, דְּלָא יִתְפְּנֵי בַּר נָשׁ לְסִטְרָא אָחֳרָא, וְרָשִׁים לְהוֹ בְּמִצְוַת לֹא תַעֲשֶׂה.</p>"],[9514012979,"<p>וְאַזְהֵיר לוֹן לִבְנֵי נָשָׁא בְּלָאו, עַל הַאי אֲמִירָה בַּתְרָאָה, דְּאִיהוּ כְּלָלָא בַּתְרָאָה דְּאוֹרַיְיתָא, וּמַאן דְּעָבַר עַל הַאי, כְּאִלּוּ עָבַר עַל כָּל אוֹרַיְיתָא. בְּגִין דְּאִיהוּ לְעֵילָא, רֵאשִׁיתָא דְּכֹלָּא, כְּלָלָא דְּכֹלָּא. וְאִי בַּר נָשׁ עָבַר עַל הַאי, וְאַסְטֵי מַחְשַׁבְתֵּיהּ מִן אוֹרְחִין דְּאוֹרַיְיתָא, כְּדֵין אִתְדַּבַּק בְּסִטְרָא אָחֳרָא, בְּסִטְרָא דְשֶׁקֶר, וּכְדֵין אָתֵי לִידֵי לֹא תַעֲנֶה בְרֵעֲךָ עֵד שָׁקֶר. כִּדְאַשְׁכַּחְנָא בְּאַחְאָב, דְּחָמִיד כַּרְמָא דְּנָבוֹת הַיִּזְרְעֵאלִי, וּכְדֵין אַסְהִידוּ עֲלֵיהּ שִׁקְרָא, וּמֵהַאי אָתֵי בַּר נָשׁ לְמֶעֱבַר עַל כָּלְהוֹ אֲמִירָן.</p>"],[9514012980,"<p>אֲבָל כַּד אִיהוּ אָזֵיל בְּאוֹרְחִין דְּאוֹרַיְיתָא, וְחָשִׁיב בְּפִקּוּדוֹי, כְּדֵין אִתְפַּשְּׁטָא הַהִיא מַחֲשָׁבָה בְּכָלְהוֹ דַּרְגִּין, מִסִּטְרָא דֶאֱמֶת, סִטְרָא דִמְהֵימְנוּתָא עִילָּאָה.</p>"],[9514012981,"<p>וְתָּא חֲזֵי, דְּהָא נְעִיצִין כָּלְהוֹ אֲמִירָן, סוֹפָא בְּרֵישָׁא, וְרֵישָׁא בְּסוֹפָא. רֵישָׁא לְמִנְדַע לְקוּדְשָׁא בְּרִיךְ הוּא בְּמַחֲשַׁבְתֵּיהּ. סוֹפָא דְּלָא לְאַסְטָאָה מַחֲשַׁבְתֵּיהּ וּרְעוּתֵיהּ לְסִטְרָא אָחֳרָא. וְכַד בַּר נָשׁ מִתְדַּבֵּק בְּהַאי, כְּדֵין כָּלְהוֹ עָלְמִין מִתְמַלָּאן בִּרְכָאן עִילָּאִין דְּנָגְדִין מִן עַתִּיקָא סְתִימָא דְּכֹלָּא.</p>"],[9514012982,"<p>וְכַד נָחֲתוּ, כָּלְהוֹ אִתְקַּשְׁרוּ בַּיּוֹם הַשְּׁלִישִׁי, וְדָא יַעֲקֹב. בְּגִין כָּךְ שְׁבִיעָאָה לְקִבְלֵיהּ, דְּכָלְהוֹ שִׁבְעָה אִתְקַשְּׁרָן בֵּיהּ. וּכְדֵין דְּאָתֵי אֶרֶץ, בִּנְהִירוּ עִם בְּנָהָא, דְּכָלְהוֹ שִׁבְעָה אִתְקַשְּׁרָן לְאַנְהָרָא, וּכְדֵין אַרְבָּעָה כּוֹסוֹת, אַרְבָּעָה גְּאוּלּוֹת.</p>"],[9514012983,"<p>קִידּוּשׁ עַל הַיַּיִן, לְקִבְלֵיהּ דְּדָוִד. הַגָּדָה, לְקִבְלֵיהּ דְּיַעֲקֹב. בִּרְכַּת הַמָּזוֹן, לְקִבְלֵיהּ דְּיִצְחָק. הַלֵּל הַגָּדוֹל, לְקִבְלֵיהּ דְּאַבְרָהָם.</p>"],[9514012984,"<p>מִתַּתָּא לְעֵילָא סָלֵיק כְּגַוְונָא דָא, מַצָּה, לְקִבְלֵיהּ דְּדָוִד. שָׁבוּעוֹת, לְקִבְלֵיהּ דְּיַעֲקֹב. רֹאשׁ הַשָּׁנָה, לְקִבְלֵיהּ דְּיִצְחָק. סוּכּוֹת, לְקִבְלֵיהּ דְּאַבְרָהָם. וְאַף עַל גַּב דְּאוֹקִימְנָא לְקִבְלֵיהּ דְּאַהֲרֹן, כֹּלָּא חַד. וְכֵיוָן דְמָטוֹ לְאַתְרָא שְׁלֵימָא דְּיַעֲקֹב, אָמְרוּ הַלֵּל הַגָּדוֹל.</p>"],[9514012985,"<p>דָּבָר אַחֵר (שמות ל) זֶה יִתְּנוּ, כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא בְּאוֹרְחַיְיהוּ, דְּכַד הַהוּא זַכָּאָה אִזְדַּבַּן, כָּלְהוֹ עֶשֶׂר דַּרְגִּין אַסְתִּימוּ נְהוֹרַיְיהוּ, דְּהָא לָא נָגֵיד נְהִירוּ דְּעַתִּיקָא, אֶלָּא בְּגִינֵיהּ לְתוֹעַלְתָּא עַל אַרְעָא. וּמַאן דְּעָבַר עַל דָּא, עָבַר עַל כָּל פִּיקּוּדַיָיא. וְקוּדְשָׁא בְּרִיךְ הוּא בִּרְחִימוּ סַגְיָא, יְהַב שַׁבָּת לְנַטְרָא לְקִבְלֵיהּ, דְּשָׁקֵיל כְּכָל פִּיקּוּדַיָּיא. וְעַל דָּא עֶשֶׂר גֵּרָה, דְּאַהֲדַר לְאַתְרֵיהּ, אִיהוּ כּוֹפֶר נֶפֶשׁ, וְנָהֲרִין לְאַתְרָא דְּאִיקְּרֵי נֶפֶשׁ, מֵאַתְרָא דְּיִשְׂרָאֵ\"ל. וְשָׁמַיִם נְהִירִין לְהַאי אֶרֶץ, וְיָהֲבִין לָהּ כָּל תִּקּוּנָהָא לְאִתְחַבְּרָא לְעֵילָא.</p>"],[9514012986,"<p>תָּא חֲזֵי, כְּתִיב (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל. מַאן שָׁמַיִם. שְׁמַיָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מְסַפְּרִים לְאַתְרָא דְּאִיקְּרֵי כְּבוֹד אֵל. מַאן כְּבוֹד אֵל. בְּרַתֵּיהּ דְּאַבְרָהָם, דְּאִיקְּרֵי אֵל. אֵל, דָּא אַבְרָהָם. מַאי מְסַפְּרִים. כְּמָה דְאַתְּ אָמֵר (איוב כ״ח:ו׳) אָז רָאָהּ וַיְסַפְּרָהּ. מַאי וַיְסַפְּרָהּ. כְּמָה דְאַתְּ אָמֵר (שם) מְקוֹם סַפִּיר אֲבָנֶיהָ. וְאִינוּן שְׁמַיָא, מְתַקְּנִין לָהּ בְּכָל תִּיקּוּנָהָא, לְהַאי כְּבוֹד אֵל.</p>"],[9514012987,"<p>וְעַל דָּא יִשְׂרָאֵל לְתַתָּא, מַיְיתִין לָהּ נְהִירוּ בִּלְחִישׁוּ, מִמַּבּוּעָא דִלְעֵילָא, וְאוֹמְרִין בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</p>"],[9514012988,"<p>וַאֲתַר דְּאִיקְּרֵי שָׁמַיִם אַסְהֵיד בְּהוֹן. וְעַל דָּא עַיִ\"ן וְדָלֵי\"ת אִינוּן רַבְרְבִין, לְמֶהֱוֵי סַהֲדִין. שָׁמַיִם, דִּכְתִיב (דברים ל׳:י״ט) הַעִדֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם, דָּא יַעֲקֹב, אַתְרָא דְשָׁמָיִם. וּמְנָא לָן דְּאִיהִי אַסְהֵידַת. דִּכְתִיב וְאֶת הָאָרֶץ. וּכְתִיב (תהלים פט) כְּיָרֵחַ יִכּוֹן עוֹלָם וְעֵד בַּשַּׁחַק נֶאֱמָן.</p>"],[9514012989,"<p>וְכַד יִשְׂרָאֵל בִּשְׁלִימוּ כִּדְחָזֵי, סַהֲדִין שְׁלֵימִין סַהֲדִין בְּהוּ, קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל, וּבְהַהוּא זִמְנָא נָגֵיד טַלָּא דִּלְעֵילָא, מֵאַתְרָא דְּעַתִּיקָא. אֵימָתַי, כַּד אִינוּן בְּיִחוּדָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:ב׳) שֶׁרֹאשִׁי נִמְלָא טָל. חֶשְׁבּוֹן טָ\"ל: יהו\"ה אֶחָ\"ד. קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. דִּבְהַהוּא שַׁעֲתָא אִתְחַזּוּן יִשְׂרָאֵל לְטַלָּא.</p>"],[9514012990,"<p>וְיִשְׂרָאֵל דְּיָדְעִין בְּהוֹן, אִינוּן מְיַחֲדוּן לוֹן תְּרֵי זִמְנֵי בְּיוֹמָא. חַד בְּסִטְרָא דִּימָמָא, וְחַד בְּסִטְרָא דְּלֵילְיָא.</p>"],[9514012991,"<p>וּמֵהַהוּא טַלָּא, זְמִינִין מֵיתַיָיא לְאַחְיָא לְעָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ. מִיְּשֵׁנֵי, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ה׳:ב׳) אֲנִי יְשֵׁנָה וְלִבִּי עֵר כו', אַתְרָא דְּלִבִּי. קוֹל דּוֹדִי, אַתְרָא דְּאִיקְּרֵי קוֹל, וְדָא יַעֲקֹב. שֶׁרֹאשִׁי נִמְלָא טָל, הַיְינוּ בִּרְכוֹת שָׁמַיִם, דְּאַתְיָין לְהַאי אַתְרָא דְּאִיקְּרֵי שָׁמַיִם, כַּד אִיהוּ בְּיִיחוּדָא עִם נוּקְבָא, וְתֵיקוּם מֵעַפְרָא.</p>"],[9514012992,"<p>וְיִצְחָק כַּד בָּרֵיךְ לֵיהּ לְיַעֲקֹב, אֲמַר, (בראשית כ״ז:כ״ח) וְיִתֶּן לְךָ הָאֱלֹהִים מִטַל הַשָּׁמַיִם. בְּגִין דְּחָזָא דְּיַעֲקֹב יָרֵית הַהוּא אַתְרָא. הָאֱלֹהִים, דָּא אִימָּא עִילָּאָה. דְּעַטְרָא לֵיהּ בְּעִיטְרִין עִילָּאִין, לְאִזְדַּוְּוגָא בְּמַטְרוֹנִיתָא.</p>"],[9514012993,"<p>וְכַד מָטֵי הַאי טַלֵּא לִזְעֵירָא, מִסִּטְרָא דְּצָפוֹן אִגְלִיד. וּמִסִּטְרָא דְּדָרוֹם נָגִיד. עַד דְּמָטֵי לְכִסֵּא הַכָּבוֹד. וְכַד מָטֵי לְכִסֵּא הַכָּבוֹד, אַתְרָא דְּאִיקְּרֵי אֶרֶץ, כְּדֵין סִטְרָא דְּצָפוֹן דְּאָחִיד בֵּיהּ, אִגְלִיד וְיִתְעֲבֵיד שֶׁלֶג, וּבֵיהּ אִתְבְּרֵי עָלְמָא. וְעַל דָּא אִיתְעָרוּ קַמָּאי, עוֹלָם מֵהֵיכָן אִתְבְּרֵי, מִשֶּׁלֶג שֶׁתַּחַת כִּסֵּא הַכָּבוֹד.</p>"],[9514012994,"<p>וְעַל דָּא בְּדִינָא לָא קָאִים עָלְמָא, עַד דְּאִתְעָרוֹ רַחֲמֵי. הֲדָא הוּא דִכְתִיב, (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וּמַעֲשֵׂה יָדָיו מַגִּיד הָרָקִיעַ. דָּא רָקִיעַ, דְּבֵיהּ תַּלְיָין כָּל נְהוֹרִין וְכוֹכְבַיָיא. וְדָא צַדִּיק, דְּאַנְגֵיד לוֹן לְהַאי אֲתַר דְּכָבוֹד.</p>"],[9514012995,"<p>(שם) יוֹם לְיוֹם יַבִּיעַ אֹמֶר, מַאן יוֹם לְיוֹם, דָּא שְׁמַיָא וְרָקִיעַ. וְלַיְלָה לְלַיְלָה יְחַוֶּה דָעַת, הַאי אַתְרָא דְּאִיקְּרֵי לַיְלָה אַנְגֵיד לְגַבְרִיאֵל דְּאִיקְּרֵי לַיְלָה. מַאי דְּקַבֵּיל מֵאַתְרָא דְּאִיקְּרֵי דַעַת. וְהוּא הוֹן יָקָר וְנָעִים, דְּגָנִיז דַּעְתֵּיהּ, בְּהַאי אַתְרָא דְּלַיְלָה. וְגַבְרִיאֵל קַבֵּיל מִתַּמָּן, וְהוּא דְּאִקְּרֵי לַיְלָה, וְאַנְגֵיד לְתַתָּאי רוּחַ דַּעַת וְיִרְאַת ה'.</p>"],[9514012996,"<p>(שם) אֵין אֹמֶר וְאֵין דְּבָרִים, בְּגִין דְּכֹלָּא בִּלְחִישׁוּ. בְּכָל הָאָרֶץ יָצָא קַוָּם, דָּא קַו הָאֶמְצָעִי, דְּאַנְגֵיד לְהַאי אֶרֶץ. הָדַר פָּרֵישׁ מַאן שָׁמַיִם, דָּא שָׁמֶשׁ. (שם) וְהוּא כְּחָתָן יוֹצֵא מְחֻפָּתוֹ, דָּא (שיר השירים ג׳:י״א) עֲטָרָה שֶׁעִטְרָה לוֹ אִמּוֹ.</p>"],[9514012997,"<p>יָשִׂישׂ כְּגִבּוֹר לָרוּץ אוֹרַח, לְאַנְהָרָא לְסִיהֲרָא, מַהוּ יָשִׂישׂ כְּגִבּוֹר. בְּגִין דְּסִטְרָא דִּגְבוּרָה אִיתְעַר בְּהַהוּא זִמְנָא. (תהילים י״ט:ז׳) מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ, דָּא רֵישָׁא דְּכוֹלָּא. וּתְקוּפָתוֹ עַל קְצוֹתָם, בְּגִין דְּהוּא מַקִּיף לְכוֹלָּא, מַבְרִיחַ מִן הַקָּצֶה אֶל הַקָּצֶה.</p>"],[9514012998,"<p>וְאֵין נִסְתָּר מֵחַמָּתוֹ, הַיְינוּ דִּכְתִיב (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים. תּוֹרַת ה' תְּמִימָה, כְּמָה דְאַתְּ אָמֵר (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. מְשִׁיבַת נָפֶשׁ, כְּמָה דְאַתְּ אָמֵר (ירמיהו נ״א:י״ד) נִשְׁבַּע ה' צְבָאוֹת בְּנַפְשׁוֹ. בְּגִין דְּהוּא אַתְקֵין לָהּ עַל תִּיקּוּנָהָא, וִיתֵיב בְּבֵיתָא דִילָהּ, וְזָן לָהּ בְּכָל מַה דְּאִצְטְרִיכָא, וְעַל דָּא מְשִׁיבַת נָפֶשׁ.</p>"],[9514012999,"<p>(תהילים י״ט:ח׳) עֵדוּת ה' נֶאֱמָנָה, דָּא אַתְרָא דְיוֹסֵף, דְּאִקְּרֵי עֵדוּת. אַמַּאי נֶאֱמָנָה. בְּגִין דְּהוּא אַתְרָא דְּנַהֲרָא, דְּלָא יְכַזְבוּן מֵימוֹי. מַחְכִּימַת פֶּתִי, אַתְרָא דְּלֵית לֵיהּ דַּעְתָּא הוּא מַחְכִּים לָהּ, בְּהַהוּא חָכְמָה זְעֵירָא דְּקַבֵּילִית מִנֵּיהּ וְאוֹקְמוּהָ, וּמַנֵּי לָהּ לְפַרְנְסָא עָלְמָא. וְיַהֲבָא לְמַאן דְּלֵית לֵיהּ זְכוּתָא מִדִּילֵיהּ.</p>"],[9514013000,"<p>(שם) פִּקּוּדֵי ה', אִינוּן דְתַלְיָין מֵהַהִיא דְּאִתְפַּקְּדָן בְּיָדָהּ כָּל גְּנִיזִין דְּמַלְכָּא, וְעַל דָּא יְשָׁרִים, כְּמָה דְאַתְּ אָמֵר (דברים ל״ב:ד׳) צַדִּיק וְיָשָׁר הוּא, וְצֶדֶק אִיקְּרֵי הָכֵי. מְשַׂמְחֵי לֵב, שִׂמְחָה, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְאֵימָתַי הִיא בְּחֶדְוָה. בְּזִמְנָא דְּאִתְחַבְּרַת בְּלֵב הַשָּׁמַיִם.</p>"],[9514013001,"<p>מִצְוַת ה' בָּרָה, כְּדֵין אִתְעֲבֵידַת מִצְוָה בָּרָה. בְּקַדְמִיתָא אִקְּרֵי מִצְוָה, הַשְׁתָּא דְּשַׁרְיָא עֲלָהּ תּוֹרָה שֶׁבִּכְתַב, אִקְּרֵי מִצְוָה בָּרָה. כְּמָה דְאַתְּ אָמֵר (שיר השירים ו׳:י׳) בָּרָה כַּחַמָּה. וְצַדִּיק וְצֶדֶק בְּשִׁיקּוּלָא חָדָא.</p>"],[9514013002,"<p>מְאִירַת עֵינָיִם. (זכריה ד׳:י׳) עֵינֵי ה' הֵמָּה מְשׁוֹטְטִים. מַאי טַעְמָא מְאִירַת. בְּקַדְמִיתָא מְאֹרֹת, דִּכְתִיב (בראשית א׳:י״ד) יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם, וְכַד הַאי רְקִיעַ הַשָּׁמַיִם אַנְהֵיר לָהּ, אִיהִי מְאִירַת, דְּיוּ\"ד אִיתּוֹסַף בָּהּ נְהִירוּ דְּצַדִּיק, וּפְרִישׂוּ דִּשְׁלָמָא דִּילֵיהּ, כְּדֵין הוּא בִּרְבוּ סַגְיָיא. וְאֵימָתַי הִיא בָּרָה, כַּד אִתְכְּלֵילַת דְּכַר וְנוּקְבָא.</p>"],[9514013003,"<p>יִרְאַת ה' טְהוֹרָה, שִׁבְחָא דִּכְנֶסֶת יִשְׂרָאֵל, דְּאִיהִי בְּדַכְיוּ. כַּד אִיהוּ אַנְהִירוּ לָהּ אַנְפִּין. עוֹמֶדֶת לָעַד, דְּקָיְימָא תָּדִיר שׁוּר רָם וְתַקִּיף עַל בְּנָהָא. אֵימָתַי, כַּד מִשְׁפְּטֵי ה' מֵאֲתַר דֶּאֱמֶת נָהֲרִין בָהּ. וְהַאי דִכְתִיב, צָדְקוּ יַחְדָּו, כַּד אִינוּן כַּחֲדָא בְּהַאי צֶדֶק, וְנָטְלִין שְׁמָא דִילָהּ, הֲדָא הוּא דִכְתִיב, (תהילים י״ט:י׳) צָדְקוּ יַחְדָּו. וְאִיהִי שְׁמָא דִילֵיהּ, מִשְׁפְּטֵי ה'.</p>"],[9514013004,"<p>דָּבָר אַחֵר פִּקּוּדֵי ה', נֶצַח וָהוֹד, דְּאִינוּן לִמּוּדֵי ה', מְשַׂמְּחֵי לֵב, דָּא אֶתְרוֹג, דְּדַמְיָא לַלֵּב. מִצְוַת ה', דָּא אֶתְרוֹג. יִרְאַת ה', כְּמָה דְאַתְּ אָמֵר (משלי ל״א:ל׳) אִשָּׁה יִרְאַת ה' הִיא תִתְהַלָּל. מַאי טַעְמָא, בְּגִין דְּאִיהִי טְהוֹרָה. מִשְׁפְּטֵי ה' אֱמֶת, אִלֵּין שִׁית בְּנִין, דִּכְלִילָן בְּיַעֲקֹב, דְּאִקְּרֵי מִשְׁפָּט, וְהוּא אֱמֶת. צָדְקוּ יַחְדָּו, בְּיִחוּדָא שְׁלֵימָא בְּיִרְאַת ה', דְּהִיא טְהוֹרָה.</p>"],[9514013005,"<p>(תהילים י״ט:י׳-י״א) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רַב, מִסִּטְרָא דְזָהָב, דָּא שִׁבְחָא דְיִצְחָק, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ח׳:ג׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וּמִפָּז, דָּא אַבְרָהָם, וְדָא יְמִינוֹ תְּחַבְּקֵנִי. רַב, דָּא יַעֲקֹב. וּמְתוּקִים מִדְּבַשׁ, דְּבַשׁ דָּא תָּמָר, דְּכָלֵיל דְּכַר וְנוּקְבָא. בְּגִין כָּךְ אֵימָתַי אֵינוּן מְתוּקִים. כַּד אִתְחַבָּרוֹ, וּנְפֵיק מִנַּיְיהוּ דְבַשׁ.</p>"],[9514013006,"<p>וְנוֹפֶת צוּפִים, כְּמָה דְאַתְּ אָמֵר (שם ד) נוֹפֶת תִּטוֹפְנָה שִׂפְתוֹתַיִךְ כַּלָּה. צוּפִים, בְּגִין דְּכָל מַאן דְּבָעֵי לְמִצְפֵּי וּלְאִסְתַּכְּלָא בְּהַאי מַרְאָה, מִסְתַּכֵּל. כְּמָה דְאַתְּ אָמֵר (יחזקאל ל״ג:ז׳) צוֹפֶה נְתַתִּיךָ לְבֵית יִשְׂרָאֵל וְשָׁמַעְתָּ מִפִּי דָּבָר. וַדַּאי הַאי אַתְרָא, אִקְּרֵי פִּתְחָא דִמְהֵימְנוּתָא. וּכְתִיב, (שם) וָאֶרְאֶה מַרְאוֹת אֱלֹהִים. מִכָּאן וּלְעֵילָא לֵית רְשׁוּ לְאִסְתַּכָּלָא. וְעַל דָּא מִינָהּ יַנְקִין אִינוּן לִמּוּדֵי ה', דְּאִיקְּרוּן צוֹפִים, כְּמָה דְאַתְּ אָמֵר וְנוֹפֶת צוּפִים.</p>"],[9514013007,"<p>דָּבָר אַחֵר צוּפִים, אִלֵּין לִמּוּדֵי ה', דְּנָהֲרִין בָהּ, וּמִתַּמָּן יַנְקִין נְבִיאִין. בַּר מִמּשֶׁה דְּאִסְתַּלַּק לְעֵילָא. וּבְהַהוּא זִמְנָא דִּכְלִילָן כָּלְהוֹ בְּחַד, אִינוּן נֶחְמָדִים.</p>"],[9514013008,"<p>דָּבָר אַחֵר (תהילים י״ט:י׳) יִרְאַת ה' טְהוֹרָה עוֹמֶדֶת לָעַד. תָּא חֲזֵי, אִי בַּר נָשׁ אִשְׁתַּדַּל בְּקַדְמִיתָא בְּהַאי אַתְרָא דְּאִיקְּרֵי יִרְאַת ה', כְּדֵין אוֹרַיְיתֵיהּ עוֹמֶדֶת לָעַד. מַאי טַעְמָא, בְּגִין דְּיֵעוֹל מִכָּאן לִמְהֵימְנוּתָא, מֵהַאי פִּתְחָא דְּכוֹלָּא. וְכַד דָּחֵיל מֵהַאי אַתְרָא, אִתְרַבְרְבָא הַאי אַתְרָא, וְיָתְבָא בִּנְהִירוּ עִם מַלְכָּא, בְּגִין דַּאֲפֵיקַת בְּרָא טָבָא לְעָלְמָא.</p>"],[9514013009,"<p>וְעַל דָּא אֲמַר שְׁלֹמֹה, (קהלת י״ב:י״ג) סוֹף דָּבָר הַכֹּל נִשְׁמָע אֶת הָאֱלֹהִים יְרָא. הַאי סוֹף, סוֹף דְּדַרְגִּין. סַמַ\"ךְ רַבָּתָא, דְּהַאי אֲתַר סַמַ\"ךְ אִקְּרֵי. מִדְּאָתַת אִתְּתָא, אָתָא סַמַ\"ךְ, דִּכְתִיב (בראשית ב׳:כ״א) וַיִּסְגֹּ\"ר בָּשָׂר תַּחְתֶּנָּה. וְאֵימָתַי הִיא בִּשְׁלִימוּ וּבִרְבוּ סַגֵּי. כַּד בַּר נָשׁ דָּחִיל מִינָּהּ בְּקַדְמִיתָא, וּלְבָתַר עָבִיד פִּקּוּדֵי אֲבוּי.</p>"],[9514013010,"<p>הֲדָא הוּא דִכְתִיב, (קהלת י״ב:י״ג) אֶת הָאֱלֹהִים יְרָא וְאֶת מִצְוֹתָיו שְׁמוֹר. וְעַל דָּא כְּתִיב, (ויקרא י״ט:ג׳) אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ. אַקְדִּים אִימָּא בְּיִרְאָה בְּקַדְמִיתָא. וְאֶת מִצְוֹתָיו שְׁמוֹר, מִצְוַת ה'. מַאן עָבִיד שְׁמָא קַדִּישָׁא לְעֵילָא. מַאן דְּעָבִיד דָּא. הֲדָא הוּא דִכְתִיב כִּי זֶה כָּל הָאָדָם, וּכְדֵין אִשְׁתְּלֵים הָאָדָם לְעֵילָא.</p>"],[9514013011,"<p>פְּתַח וַאֲמַר, (משלי כ״ד:כ״א) יְרָא אֶת ה' בְּנִי וָמֶלֶךְ. יְרָא אֶת ה', לְחַבְּרָא יִרְאָה בְּקוּדְשָׁא בְּרִיךְ הוּא. בְּנִי וָמֶלֶךְ, לְאַמְשָׁכָא נְהִירוּ מֵאִימָּא עִילָּאָה, דְּאִיקְּרֵי מֶלֶךְ. לְהַאי בְּרָא בּוּכְרָא, לְמֵיעַל מִתַּתָּא לְעֵילָא. דָּבָר אַחֵר בְּנִי וָמֶלֶךְ, תַּמְשִׁיךְ נְהִירוּ מִבְּרָא לִבְרַתָּא, דְּאִיקַּרְיָא מֶלֶךְ.</p>"],[9514013012,"<p>וְעִם שׁוֹנִים אַל תִּתְעָרָב, דְּלָא יְשַׁנֶּה מִסִּדְּרָא דִמְהֵימְנוּתָא. דְּהָא בְּקַדְמִיתָא בָּעֵי לְאִשְׁתַּדְּלָא בְּהַאי יִרְאָה, דְּאִיהִי פִּתְחָא דְּכוֹלָּא. וּלְבָתַר בְּתוֹרָה דְּבִכְתָב, דְּאִיהִי לְעֵילָא. בְּגִין דְּכָל בַּר נָשׁ דְּלָא דָּחִיל חַטָאָה, לֵית לֵיהּ רְשׁוּ לְמֵיעַל לְהַאי פִּתְחָא דִּמְהֵימְנוּתָא. כֵּיוָן דִּמְהַאי פִּתְחָא דַּחְיָין לֵיהּ, מִכֹּלָּא דַּחְיָין לֵיהּ, דְּלֵית לֵיהּ בְּמַאי דְּיֵעוֹל לְכוֹלָּא, הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַה'.</p>"],[9514013013,"<p>וְעַל דָּא אִיתְעָרוֹ קַדְּמָאֵי, כָּל שֶׁיִּרְאַת חֶטְאוֹ קוֹדֶמֶת לְחָכְמָתוֹ חָכְמָתוֹ מִתְקַיֶּימֶת. דְּיָתְבָא חָכְמָה עַל כַּנָּה אֲשֶׁר נָטְעָה יְמִינְךָ, דְּאִקְּרֵי כְּבוֹד אֵל.</p>"],[9514013014,"<p>וְאִם בַּר נָשׁ לָא דָּחִיל מִינָהּ, אִיהִי מְיַסֶּרֶת לֵיהּ, דְּאִתְמַנַּת לְיַיסְרָא בְּנֵי נְשָׁא. הֲדָא הוּא דִכְתִיב, (משלי ו׳:כ״ג) וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. מַאן הוּא דֶּרֶךְ לְאִילָנָא דְּחַיָּיא. הַהוּא דְּאִתְמַנָּא עַל עָלְמָא, לְיַיסְרָא בְּנֵי נְשָׁא דְּלָא יִטְעַיָּין מֵאוֹרְחֵיהּ.</p>"],[9514013015,"<p>וְעִם כָּל דָּא, בָּעֵי לְקָשְׁרָא לָהּ לְעֵילָא, בְּגִין דְּאִתְקַרְיָא גוּפָא, וּבָעְיָיא נִשְׁמָתָא. וְנָדָב וַאֲבִיהוּ, עַל דְּלָא קְשִׁירוּ לָהּ, וּנְטָלוּ מִינָהּ נִשְׁמָתָא, נְטָלַת נִשְׁמַתְהוֹן, וְגוּפָא דִּילְּהוֹן קַיָּים, כְּגַוְונָא דַּעֲבָדוּ. וַיָּשִׂימוּ עָלֶיהָ קְטֹרֶת.</p>"],[9514013016,"<p>בְּגִין דְּלֵית לָהּ מִדִּילָהּ חַיִּים כְּלוּם. וְעֵץ הַחַיִּים יָהֵיב בָּהּ חַיִּים. בְּגִין כָּךְ אִיהִי גּוּפָא. יַעֲקֹב, נִשְׁמָתָא. עַתִּיקָא, נִשְׁמָתָא לְנִשְׁמָתָא.</p>"],[9514013017,"<p>וּפִנְחָס דִּיהַב שָׁלוֹם בָּאָרֶץ. חַיִּים בָּאָרֶץ. אִיתּוֹסַף לֵיהּ נִשְׁמָתָא, וְנָהֲרָא לֵיהּ אַנְפָּהָא, בְּגִין דְּאִתְעַר חַיִּים לְקִבְלָהּ, וְעַל דָּא בְּאוֹר פְּנֵי מֶלֶךְ. כַּד הַאי מֶלֶךְ דִּלְתַתָּא, נְהִירָא אַנְפָּהָא, חַיִּים אִתְדַּבְּקוּ בָּהּ.</p>"],[9514013018,"<p>דָּבָר אַחֵר (שם טז) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים, דָּא יַעֲקֹב, חַיִּים, דְּאַתְיָין לֵיהּ מֵאִימָּא. וּבְגִין פִּינְחָס אִתְקַיַּים עָלְמָא, דְּחִיבֵּר בְּרִית בַּלַּיְלָה. הֲדָא הוּא דִכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה. מַאי טַעְמָא יוֹמָם. דְּאִתְחַבְּרַת מ\"ם סְתוּמָה בַּיּוֹם, וְנָהֵיר בַּלַּיְּלָּהּ. וְאִלְמָלֵא הַאי. חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי, אִלֵּין חוּקּוֹת דִּקְבִיעִין בְּהַאי חוּקּוֹת הַתּוֹרָה לֹא יִתְקַיְּימוּ. וְאֵימָתַי יִתְקַיְּימוּ, כַּד צָדְקוּ יַחְדָּו.</p>"],[9514013019,"<p>גַּם עַבְדְּךָ נִזְהָר בָּהֶם, מִלְּמִיטְעֵי בְּתִיקּוּנֵי דְמַלְכָּא. דְּהָא בְּכָל לֵילֵי אִשְׁתַּדַּל בְּהוּ, לְחַבְּרָא לוֹן כַּחֲדָא. הֲדָא הוּא דִכְתִיב, (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לְךָ. עַל מִשְׁפְּטֵי צִדְקֶךָ, דְּמִשְׁפָּטִים דְּאִינוּן נֶחְמָדִים, וּכְלִילָן מִכּוּלָּם, יִתְחַבְּרוּן בְּהַאי צֶדֶק.</p>"],[9514013020,"<p>וּכְדֵין כַּד מִזְדַּוְּוגִין, אִינוּן נָטְרִין דְּלָא יִתְקְרַב לַמִּקְדָּשׁ עָרֵל וְטָמֵא. וְכַד אִינוּן נָטְרִין לָהּ שְׁמִירָה לְהַאי סוֹפָא דְדַרְגִּין דְּאִיהוּ עָקֵב, כְּדֵין אִיהִי רַב אִתְחַבְּרַת לְעֵילָא. וְעַל דָּא כְּתִיב, (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת ה'. עֵקֶב עֲנָוָה, יָהֲבָה יִרְאַת ה'. עֲנָוָה: כְּמָא דְּאִתְּמָר (במדבר י״ב:ג׳) וְהָאִישׁ משֶׁה עָנָו מְאֹד. וְאִיקְּרֵי (דברים ל״ג:א׳) אִישׁ הָאֱלֹהִים. וּכְתִיב (תהלים יח) וְעַנְוָתְךָ תַרְבֵּנִי.</p>"],[9514013021,"<p>וּכְתִיב, (שם קיא) רֵאשִׁית חָכְמָה יִרְאַת ה'. בְּגִין דִּבְרֵישָׁא בָּעֵי לְמִדְחַל מִינָהּ, וּלְבָתַר לְסַלְקָא בְּחָכְמָה. דָּבָר אַחֵר רֵאשִׁית חָכְמָה יִרְאַת ה', דָּא יִרְאָה עִילָּאָה. וּבְגִין דְּהִיא רֵישָׁא לְתַתָּאי נָקְטָא שְׁמָא דְּעִילָּאָה. וְעַל דָּא אִקְּרֵי עֲטֶרֶת, בִּשְׁמָא דְכִתְרָא עִילָּאָה, טְמִירָא דְּכוֹלָּא, לְיַחֲדָא רֵישָׁא בְּסוֹפָא, וּבְחַד שְׁמָא אִתְכְּלִילַת.</p>"],[9514013022,"<p>דָּבָר אַחֵר (תהלים יט) בְּשָׁמְרָם עֵקֶב רָב, אִינוּן מִשְׁפָּטִים נָטְרִין לְהַאי עֵקֶב רָב, דְּהָא יַעֲקֹב, מָארֵיהּ דְּבֵיתָא, נָטֵיר בֵּיתֵיהּ. וְהָא אִיתְעָרוֹ בְּהַהוּא דְּנָסִיב אוּמָנוּתָא דְּיַעֲקֹב, דְּכָרַע שֶׁבַע כְּרִיעָן, לְבַטָלָא שֶׁבַע רֵישֵׁי דְּחִוְיָא, דְּלָא יִקְרַב לְמַקְדְּשָׁא.</p>"],[9514013023,"<p>גַּם מִזֵּדִים חֲשׂוֹךְ עַבְדְּךָ, זֵדִים: דָּא נָחָשׁ דְּרָכֵיב עֲלֵיהּ סמא\"ל. חֲשׂוֹךְ עַבְדְּךָ, כְּגוֹן הַהוּא עַבְדָּא דְּכָל מַפְתְּחָן דְּמָארֵיהּ בִּידֵיהּ, אֲמַר דְּהִיא בַּחֲשׁוֹכָא וְטָלֵימוּתָא, בְּגִין אִינוּן זֵדִים דְּשָׁלְטוֹ בְּעָלְמָא, וְגָרְמוֹ מִיתָה. וְזִמְנִין פְּגִימָא סִיהֲרָא, וְשַׁלִּיט חִוְיָא.</p>"],[9514013024,"<p>וְהָוִה הֲוָה בָּעֵי רַחֲמִין עַל דָּא, וְאָמַר אַל יִמְשְׁלוּ בֵי אָז אֵיתָם, דְּלָא יִשְׁלוֹט בְּאַתְרֵיהּ. לְנָטְרָא הַהוּא עֵקֶב, עַל יְדָא דְיַעֲקֹב, דְּאִקְרֵי רַב, בְּרָא בּוּכְרָא. דְּלֵית לָךְ בְּעָלְמָא דְּאִתְגַּבַּר לְקִבְלֵיהּ דְּהַאי נָחָשׁ, כַּוָּותֵיהּ דְּיַעֲקֹב, וְאַעֲדֵי יָתֵיהּ מֵאַחְסַנְתֵּיהּ, בְּגִין דְּהוּא מָארֵיהּ דְּבֵיתָא, דְּלָא יִסְאַב בֵּיתֵיהּ.</p>"],[9514013025,"<p>כֵיוָן דְּלָא יִשְׁלוֹט, כְּדֵין, אָז אֵיתָם. אָז: אל\"ף, נְהִירוּ דְּעַתִּיקָא. זי\"ן, שֶׁבַע דַּרְגִּין דִּכְלִילָן בְּיַעֲקֹב. כֵּיוָן דְּכָל הַאי אִתְחַבַּר, כְּדֵין אֶהְיֶה תָּם. דְּהָכֵי אִקְּרֵי מִכְתָם, מָךְ וְתָם. מָךְ: בְּגִין דְּלֵית לָהּ נְהוֹרָא מִדִּילָה. תָּם: כַּד סִיהֲרָא בְּאַשְׁלָמוּתָא, וְנָהֲרָא בִּנְהִירִין עִילָּאִין, כְּדֵין תָּם. וְעַל דָּא מִכְתָּם לְדָוִד.</p>"],[9514013026,"<p>אֵימָתַי. כַּד אִתְנְטִירַת סִיהֲרָא. הֲדָא הוּא דִכְתִיב, (שם טז) שָׁמְרֵנִי אֵל כִּי חָסִיתִי בָּךְ. מַאי חָסִיתִי, כְּמָא דְאַתְּ אָמֵר (שם נז) חָסָיָה נַפְשִׁ\"י.</p>"],[9514013027,"<p>מַאי טַעְמָא שָׁמְרֵנִי אֵל. סִטְרָא דְאַבְרָהָם בָּעָא לְאִתְעָרָא, דְּיַנְהֵיר חֶסֶד עִילָּאָה, לְחַסְדֵּי דָּוִד הַנֶּאֱמָנִים. הֲדָא הוּא דִכְתִיב, (שם קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם. חֶסֶד: דָּא אַבְרָהָם. דְּנָקִיט מֵעוֹלָם עִילָּאָה נְהִירוּ וְחַיִּים, וְיָהֵיב לְעוֹלָם בַּתְרָאָה, הֲדָא הוּא דִכְתִיב, וְעַד עוֹלָם עַל יְרֵאָיו. הוּא עוֹלָם בַּתְרָאָה דְּתַלְיָיא בֵּיהּ יִרְאָה.</p>"],[9514013028,"<p>וּכְדֵין, וְצִדְקָתוֹ דָּא עוֹלָם בַּתְרָאָה, דְּאִקְּרֵי צֶדֶק. לִבְנֵי בָנִים, דְּיָנְקָא לְמַשְׁרִיתָא דְּאִיקְּרוּן בְּנֵי בָנִים. דְּהָא שִׁית עִילָּאִין דְּנָהֲרִין לָהּ, אִיקְּרוּן בָּנִים. כְּמָה דְאַתְּ אָמֵר (שיר השירים א׳:ו׳) בְּנֵי אִמִּי נִחֲרוּ בִי. וּכְתִיב (תהילים קי״ג:ט׳) אֵם הַבָּנִים שְׂמֵחָה. וְאִלֵּין דְּסָחֲרֵי הַאי עוֹלָם בַּתְרָאָה, אִיקְּרוּן בְּנֵי בָנִים. אֵימָתַי, כַּד נָטְרֵי קִיּוּמֵיהּ. הֲדָא הוּא דִכְתִיב, (שם קג) לְשׁוֹמְרֵי בְרִיתוֹ. תָּא חֲזֵי, בְּגִין דְּהַנֵּי בְּנֵי בָנִים, לָא נָטְרוֹ קִיּוּמֵיהּ כְּקַדְמֵיתָא, וְזַבִּינוּ לֵיהּ לְאַרְעָא נוּכְרָאָה, אִתְגְּזַר עֲלֵיהוֹן עוֹנָשָׁא.</p>"],[9514013029,"<p>וְהָא בָּעָא משֶׁה, כַּד חָמָא דְּיִתְעֲבֵיד דִּינָא בְּאִינוּן עֲשָׂרָה הֲרוּגֵי מַלְכוּת. וְאָן הוּא אוֹרַיְיתָא דִּילְּהוֹן. אָמַר לֵיהּ, חֲזוֹר לַאֲחוֹרֶךָ, לְאִינוּן דְּשָׁרְאָן אֲחוֹרֵי מַשְׁכְּנָא, דְּזַבִּינוּ לְהַאי צַדִּיק. אֲמַר לֵיהּ, וּמַאי שְׁנָא בְּאִלֵּין גּוּפִין. אָמַר לֵיהּ, כָּךְ עָלָה בַּמַּחֲשָׁבָה, וְלֵית דְּיָכוֹל לְאַדְּבְּקָא.</p>"],[9514013030,"<p>וְעַל דָּא אִשְׁתַּדַּל דָּוִד, לְבָרְכָא לְהַאי אַתְרָא, דְּאָתֵי מִנֵּיהּ נְהִירוּ. וַאֲמַר (תהלים קטו) ה' זְכָרָנוּ יְבָרֵךְ, דָּא צַדִּיק. יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל, הַאי צַדִּיק יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל. יְבָרֵךְ אֶת בֵּית אַהֲרֹן, סִטְרָא דְּחֶסֶד דְּאִית בָּהּ, דְּאִקְּרֵי בֵּית אַהֲרֹן, כַּד אִתְחַבְּרַת לְחֶסֶד. הֲדָא הוּא דִכְתִיב, (שמות ו) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַ\"ע בַּת עֲמִינָדָב, דְּאִתְחַבְּרַת לְאֵל.</p>"],[9514013031,"<p>יְבָרֵךָ יִרְאֵי ה', אִלֵּין יַתְבֵי מַשְׁכְּנָא, דְּשָׁארָן בְּהַאי יִרְאָה. הַקְּטַנִּים עִם הַגְּדוֹלִים, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:כ״ה) חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. חַיּוֹת קְטַנּוֹת, כָּל אִינוּן רַבְרְבָן דְּנָפְקוֹ מֵאִינוּן בְּנֵי בָנִים, כְּמָה דְאַתְּ אָמֵר (במדבר ב׳:ט׳) כָּל הַפְּקֻדִים לְמַחֲנֵה יְהוּדָה. עִם גְּדוֹלוֹת, אִינוּן שְׁבָטִין.</p>"],[9514013032,"<p>וְעַל דָּא, כָּל דַּעֲבַר עַל פִּקּוּדַיָיא, יָהֵיב אַגְרָא בֶּקַע לַגֻּלְגּוֹלֶת, לְמֶהֱוֵי כּוֹפֶר לְהַהוּא נַפְשׁוֹ, וְיִתְפַּשַׁט מִנָּהּ נְהִירוּ, כַּד אִתְחַבַּר יָמִינָא כֶּסֶף לְגַבָּהּ. וְעַל דָּא יְבָרֵךְ אֶת בֵּית אַהֲרֹן, כַּד אִתּוֹסַף בָּהּ בִּרְכָתָא, וְאִתְעַר יָמִינָא לְגַבָּהּ, בְּהַהוּא כֶּסֶף, כְּדֵין בִּרְכָתָא דִּילָהּ נָגֵיד בְּאִינוּן דְּדָחֲלִין מִינָהּ.</p>"],[9514013033,"<p>תָּא חֲזֵי, כָּל בַּר נָשׁ דְּתָב בִּתְיוּבְתָּא קַמֵי מָארֵיהּ, וְדָחִיל כָּל יוֹמָא מֵהַהוּא חוֹבָה דְּעָבַד. קוּדְשָׁא בְּרִיךְ הוּא מָחִיל לֵיהּ, וְלָא גָבֵי מִנֵּיהּ. דְּהָא אֲחוֹי דְּיוֹסֵף, דְּחִילוּ סַגֵּי נְפַל עֲלַיְהוּ, כַּד חֲזוֹ דְּאִסְתַּלַּק אֲבוּהוֹן לְעֵילָא, וַחֲזוֹ גַּרְמַיְיהוּ בְּגָלוּתָא עַל הַהוּא חוֹבָא, עַד דַּאֲמַר לְהוֹ יוֹסֵף, (בראשית נ׳:י״ט) אַל תִּירָאוּ. לָא תִדְחֲלוּ וַדַּאי מֵעוֹנָשָׁא בְּהַאי זִמְנָא, כִּי הֲתַחַת אֱלֹהִים אָנִי. וַדַּאי אִסְתַּלַּקְנָא לְעֵילָא מֵהַהוּא אַתְרָא. וְדַרְגָּא דִּילִי יַנְהֵיר, לִסְטַר בֵּי דִינָא, לְאַנְהָרָא לְכוֹ, דְּאַתּוּן תְּחוֹת הַהוּא אַתְרָא.</p>"],[9514013034,"<p>כַד חָמָא דָוִד לְמָארֵיהּ דְּבֵיתָא דַּאֲמַר כָךְ. אֲמַר (תהילים קט״ו:י״ב) ה' זְכָרָנ\"וּ יְבָרֵךְ, הַהוּא דְּיָתֵיב בְּעָלְמָא דִדְכוּרָא. ה', לְעֵילָא לְעֵילָא, יְבָרֵךְ יָתֵיהּ בְּעִטְרִין עִילָּאִין. דְּהָא כָּלְהוֹ שְׁבָטִין בַּר מִיּוֹסֵף, בְּעָלְמָא דְּנוּקְבָא יָתְבִין, וּמִתְבָּרְכִין מִנֵּיהּ.</p>"],[9514013035,"<p>הַהוּא אַתְרָא, יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל וַדַּאי, בֵּיתוֹ דְּדָוִד. יְבָרֵךְ אֶת בֵּית אַהֲרֹן, דְּיִתְעַר סִטְרָא דְחֶסֶד דִּילָהּ. יְבָרֵךְ יִרְאֵי ה' הַקְּטַנִּים. בְּגִין כָּךְ יוֹסֵף ה' עֲלֵיכֶם, מִסִּטְרָא דְיוֹסֵף, דְּהוּא עֲלֵיכֶם, אִיתְעַר בְּרַחֲמֵי עֲלֵיכוֹן. דְּהָא הַהוּא חוֹבָא יוֹסֵף מָחִיל לְתַתָּא, וַאֲמַר (בראשית נ׳:כ״א) אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם. בְּגִין כָּךְ עֲלֵיכֶם וְעַל בְּנֵיכֶם, וְיָגֵין זְכוּתֵיהּ עֲלֵיכוֹן, וְעַל בְּנֵיכוֹן, דְּלָא יִתָּפְשׂוּן בְּחוֹבֵיכוֹן, וְלָא יִשְׁלוֹט עֲלֵיכוֹן הַהוּא חִוְיָא.</p>"],[9514013036,"<p>בְּגִין כַּךְ אַל יִמְשְׁלוּ בִי אָז אֵיתָם, וְאִתְעַטַר הַהוּא אַתְרָא בְּעִטְרוֹי, כְּגַוְונָא דְּאִתְעַטַר כַּד עָבְרוּ יִשְׂרָאֵל יַמָּא, וְאָמְרוּ אָז יָשִׁיר, כַּד חָמוּ דְּאִשְׁתְּלֵימַת סִיהֲרָא. (תהילים י״ט:י״ד) וְנִקֵּיתִי מִפֶּשַׁע רָב, דָּא חוֹבָא דִּשְׁבָטִין, דְּהֲוָה רָב.</p>"],[9514013037,"<p>וְעַל כּוֹלָּא בָּעָא רַחֲמִין, (שם) יִהְיוּ לְרָצוֹן קַמֵּי עַתִּיקָא קַדִּישָׁא. אִמְרֵי פִי, דָּא פֶּה דִילֵיהּ. וְהֶגְיוֹן לִבִּי, דָּא לֵב הַשָּׁמַיִם. לְפָנֶיךָ, אִלֵּין פָּנִים עִילָאִין, דִּמְטַמְּרִין וְאִתְגַּלְּיָין בְּעֵת רָצוֹן. ה', דָּא יָמִינָא. צוּרִי, דָּא שְׂמָאלָא. וְגוֹאֲלִי, דָּא אֶמְצָעִיתָא.</p>"],[9514013038,"<p>דָּבָר אַחֵר, ה', דָּא אֶמְצָעִיתָא, דָּא יַעֲקֹב. צוּרִי, דָּא שְׂמָאלָא. וְגוֹאֲלִי, דָּא דְּיָמִינָא, דְּאִקְּרֵי גוֹאֵל, קָרוֹב, וַדַּאי. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲרָמָא יְמִינָא דִילֵיהּ, וּלְמִיפְדֵי לִבְנוֹי, הֲדָא הוּא דִכְתִיב, (שם קיח) יְמִין ה' רוֹמֵמָה יְמִין ה' עוֹשָׂה חָיִל.</p>"],[9514013039,"<p>[חָסֵר תְּחִלַּת הָעִנְיָן]. וּבִסְטַר שְׂמָאלָא, קָיְימָא דַּרְגָּא אָחֳרָא, דְּבִסְטַר מְסָאֲבָא, דְּאִקְּרֵי אוּף הָכֵי מַחֲשָׁבָה, וְאִקְּרֵי מַחֲשָׁבָה רָעָה. בְּגִין דְּדַרְגָּא דַּעֲלָהּ אִיהוּ רַע, וּבְגִין כָּךְ אִיקְּרֵי מַחֲשָׁבָה רָעָה.</p>"],[9514013040,"<p>הָכָא קָיְימָא כָּל רְעוּתִין בִּישִׁין, וְכָל הִרְהוּרִין בִּישִׁין, וְכָל בִּישִׁין דְּעָלְמָא. וְאִיהִי קְיָימָא לְכָל רְעוּתִין אִלֵּין, דְּיִסְתְּאַב בַּר נָשׁ בְּהוּ. בְּהַאי מַחֲשָׁבָה רָעָה קַיְימָא כַּמָּה דַּרְגִּין מְסָאֲבִין, וְכָלְהוֹ קָיְימִין לְסָאֲבָא לְבַּר נָשׁ, בְּאִינוּן רְעוּתִין וְהִרְהוּרִין דְּמַחֲשָׁבָה רָעָה, וּכְדֵין אִסְתְּאַב בַּר נָשׁ בְּהוּ, וְאִתְדַּבַּק בְּהַהוּא סִטְרָא.</p>"],[9514013041,"<p>וְעַל דָּא בָּעֵי לְקָרָבָא עוֹלָה לְאִתְדָּכָּאָה, וְכַד קָרִיב לָהּ, בָּעֵי לְאַסְטָאָה רְעוּתֵיהּ לְגַבֵּי מַחֲשָׁבָה קַדִּישָׁא. וְכַד סָלֵיק תְּנָנָא מֵאִינוּן חֲלָבִין וְאֵמוּרִין, וּמֵאִינוּן אֵיבָרִין, לְהַהִיא מַחֲשָׁבָה רָעָה סָלְקָא בְּקַדְמִיתָא, וְכָלְהוֹ נְטִילַת לָהּ, וּמִתְּזְנָא מִינַּיְיהוּ.</p>"],[9514013042,"<p>וּלְבָתַר סָלִיק תְּנָנָא אָחֳרָא דַּקִּיק. וְכָל אִינוּן עִילָּאִין, מִינַּיְיהוּ מָארֵיהוֹן דְּדִינָא, מִתְכַּנְּשֵׁי וְעַיְילוּ לְגוֹ לְגוֹ, עַד דְּאִתְכְּנַשׁ דָּא לְגוֹ דָּא, וְדָא לְגוֹ דָא, עַד דְּאִסְתַּלִּיקוּ כּוּלְהוֹ לְאִתְכְּלָלָא כֹּלָּא דָּא עִם דָּא, וּלְאַשְׁלָמָא דָּא עִם דָּא, וְגוּפָא אִתְקַּשַּׁר בְּגוּפָא.</p>"],[9514013043,"<p>כְדֵין אַעֲטַר הַהוּא בַּר נָשׁ רְעוּתֵיהּ, בִּרְעוּתֵיהּ דְּהַהִיא מַחֲשָׁבָה טְהוֹרָה. וּכְדֵין כַּהֲנָא מִסִּטְרָא דְּיָמִינָא, וְלֵיוָאֵי מִסִּטְרָא דִּשְׂמָאלָא, מְקַשְׁרֵי שַׁיְיפִין בְּשַׁיְיפִין, עַד דְּאִסְתַּלְּקָא הַאי מַחֲשָׁבָה טְהוֹרָה בֵּין יָמִינָא לִשְׂמָאלָא, וְאִתְחַבָּרוּ דָּא עִם דָּא, וְאִתְקַשָּׁרוּ דָּא עִם דָּא, וַהֲווּ חַד. וּכְדֵין אִקְּרֵי נִיחוֹחַ, נַיְחָא וּרְעוּתָא, לְאִתְחַבָּרָא וּלְאַעֲלָא דָּא בְּדָא.</p>"],[9514013044,"<p>וְכַד כֹּלָּא אִתְקַשְּׁרוּ דָּא בְּדָא, עָלְמָא דְאָתֵי אַפֵּיק כָּל נְהִירוּ, לְאִתְנַהֲרָא כּוּלְהוֹ כַּחֲדָא. וְכָל חֵידוּ אִשְׁתְּכַח, וְכָל אַנְפִּין נְהִירִין, וְכֹלָּא אִיהוּ בִּבְסִימוּ. וְאִתְפְּרַשׁ בַּר נָשׁ מִגּוֹ מַחֲשָׁבָה רָעָה, וְאִתְדַּבַּק בְּמַחֲשָׁבָה טְהוֹרָה, עַד דְּאִתְדַּבַּק כֹּלָּא בְּגוֹ מַחֲשָׁבָה סְתִימָאָה עִילָּאָה דְּכֹלָּא, וַהֲוֵי כֹּלָּא חַד.</p>"],[9514013045,"<p>וּמַאי דְּאִשְׁתָּאַר מִן קָרְבָּנָא, בָּעְיָא לְאִתּוֹקְדָא וּלְאִתְאַכָּלָא בְּלֵילָא, דְּלָא יִתְהַנֵּי מִינֵּיהּ בַּר נָשׁ. מַאי טַעְמָא דְּהַאי עוֹלָה, קָרְבָּנָא דְּעִלָּוָון, לֵית רְשׁוּ לִבַּר נָשׁ בְּעָלְמָא לְאִתְהֲנָאָה מִינֵּיהּ. בְּגִין דְּהַהוּא קָרְבָּנָא לָא אִתְקְרֵיב, אֶלָּא מִגּוֹ דְּאִתְמַשְּׁכָא בְּמַחֲשָׁבָה רָעָה, סִטְרָא דִּמְסָאֲבָא. וּדְלָא יִתְפַּשַׁט וְלָא יִסְטֵי הַאי סִטְרָא, כֹּלָּא אִתְהַדַּר לְגוֹ אֶשָׁא לְאִתְאַכָּלָא, וְלָא יִתְהַנֵּי מֵהַהוּא קָרְבָּנָא בַּר נָשׁ בְּעָלְמָא.</p>"],[9514013046,"<p>בְּלֵילְיָא אִתְאַכָּל כָּל מַאי דְּאִשְׁתָּאַר, כְּמָה דְאַתְּ אָמֵר (ויקרא ו׳:ב׳) עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה. דְּכַד עָאל לֵילְיָא, כָּל אִינוּן גַּרְדִּינֵי נִימוּסִין מִשְׁתַּכְּחִין, וְאָזְלִין וְשָׁלְטִין בְּכָל אִינוּן אֵמוּרִין וּפְדָרִין, וְכָלְהוֹ מִתְאַכְּלֵי, וּמִנְהוֹן אִתְּזְנוּן כָּל אִינוּן גַּרְדִּינֵי נִמוּסִין, וְאִינוּן חוּלָקָא דִּילְּהוֹן לְאִיתְּזְנָא, בְּגִין דְּלָא יִשְׁלְטוּן, וְלָא יִתְקַרְבוּן לְגוֹ קוּדְשָׁא. וְיִתְפְּרַשׁ בַּר נָשׁ מֵהַהוּא סִטְרָא, וְיִתְדַּבַּק בִּרְעוּתָא עִילָּאָה, וּכְדֵין שָׁבֵיק לֵיהּ מָארֵיהּ לְהַהוּא בַּר נָשׁ, וְכַהֲנָא מְכַפֵּר עֲלֵיהּ, דִּכְתִיב (שם ד) וְכִפֶּר עָלָיו הַכֹּהֵן מֵחַטָאתוֹ.</p>"],[9514013047,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְבְּרִיאוּ אִתְלַבָּשׁוּ בִּדְיוּקְנָא קַדִּישָׁא עִילָאָה דִּנְהוֹרָא, בְּגִנְתָּא דְעֵדֶן דִּלְעֵילָא. וּבִדְיוּקְנָא קַדִּישָׁא אָחֳרָא, בְּגִנְתָּא דְעֵדֶן דִּלְתַתָּא. וְיָהֲבִין לוֹן אַחְסַנְתָּא עִילָּאָה. וְיָהֲבוּ לְהוֹן חוּלָקָא עִילָּאָה. וּבָתַר דְּיָהֲבִין לְהוֹן דָּא, אֲמַר לְהוֹן מַלְאָכָא, אָתָא זִימְנָא דְּתִיפְקוּ, דְּקוּדְשָׁא בְּרִיךְ הוּא אֲמַר דִי תִפְקוּן מִכָּאן.</p>"],[9514013048,"<p>תְּוַוהוּ, וַאֲמָרוּ לְאָן. אָמַר לֵיהּ תְּרֵין מַלְאָכִין, קוּדְשָׁא בְּרִיךְ הוּא אֲמַר (בראשית י״ב:א׳) לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָֹּ. מֵאַרְצְךָ: דָּא גִּנְתָא דְעֵדֶן דִּלְתַתָּא. וּמִבֵּית אָבִיךָ: דָּא גִּנְתָא דְּעֵדֶן דִּלְעֵילָא. אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָֹּ: דָּא אַרְעָא חֲשׁוֹכָא שְׁפָלָה.</p>"],[9514013049,"<p>וְאַחֲזִיאוּ לֵיהּ כָּל גִּנְתָא דְעֵדֶן. וְאַחֲזִיאוּ לֵיהּ הֵיכָלִין וּבֵיתִין, מָדוֹרִין עִילָּאִין וְכַמָּה הֵיכָלִין דִּכְסִיפִין, וְכַמָּה בֵּיתִין, וְכַמָּה מָדוֹרִין, וְכַמָּה דַּרְגִּין, וְכָל חֵלֶק וְחֵלֶק שֶׁיֵּשׁ לוֹ לַצַּדִּיק בִּפְנֵי עַצְמוֹ.</p>"],[9514013050,"<p>אֲמַר מָה אִינוּן הֵיכָלִין, אֲמָרוּ לֵיהּ תְּרֵין מַלְאָכִין, אַרְבָּעִין וּתְרֵין הֵיכָלִין אִינוּן מְרַקְּמָן מִכַּמָּה גְּוָונִין נָאִים, וְכָל אֵינַשׁ דְּקָרֵי קְרִיאַת שְׁמַע שְׁמָא דְּמ\"ב שְׁמָהָן כִּדְקָא יָאוֹת, יִירַת לוֹן. עָאל לֵיהּ לְשִׁבְעִין דַּרְגִּין, וּבְהוֹן ע\"ב חַלּוֹנוֹת, וּמְרַקְּמָן בְּכַמָּה גְּוָונִין. אֲמַר לְמָאן אִינוּן. אֲמָרוּ לֵיהּ, כָּל אֵינַשׁ דְּקָרֵי קְרִיאַת שְׁמַע שְׁמָא דְּע\"ב תֵּיבִין כִּדְקָא יָאוֹת, יִירַת דָּא.</p>"],[9514013051,"<p>עָאל לֵיהּ לְהַלָּן, וְאַחְזֵי לֵיהּ חַמְשִׁין מְדוֹרִין אָחֳרָנִין, מְרַקְּמָן בְּכַמָּה גְּוָונִין. אֲמַר לְמָאן אִינוּן. אֲמָרֵי לֵיהּ, לְכָל בַּר נָשׁ דְּקָרֵי קְרִיאַת שְׁמַע שְׁמָא דְּחַמְשִׁין תֵּיבִין כִּדְקָא יָאוֹת, יִירַת דָּא.</p>"],[9514013052,"<p>עָאל לֵיהּ לְהַלָּן, אַחֲזֵי לֵיהּ שִׁבְעִין וּתְרֵין מְדוֹרִין אָחֳרָנִין מְרַקְּמָן בְּכַמָּה גְּוָונִין. אֲמַר לְמָאן אִינוּן, אָמַר לֵיהּ, לְכָל בַּר נָשׁ דְּקָרֵי קְרִיאַת שְׁמַע שְׁמָא דְּע\"ב תֵּיבִין דְּאִית בְּפָרָשָׁתָא רְבִיעָאָה.</p>"],[9514013053,"<p>אֲמַר לְהוֹן, וּבַמֶּה אֲנָא אַרְוַוח דָּא. אֲמָרוּ לֵיהּ, (בראשית ג׳:י״ז) בְּעִצָּבוֹן תֹּאכֲלֶנָּה. אֲמַר לְהוֹן וּמַהוּ הָעִצָּבוֹן. אֲמָרוּ לֵיהּ נַעֲשֶׂה וְנִשְׁמָע. עֲשִׂיָּיה, בְּעוֹבָדִין טָבִין. וּשְׁמִיעָה, בְּאוֹרַיְיתָא.</p>"],[9514013054,"<p>אֲפִיקוּ לֵיהּ מִגִּנְתָא דְּעֵדֶן, וַאֲזָלוּ עִמֵּיהּ לַגֵּיהִנֹּם, וְעַמּוּדָא דַּעֲנָנָא לְמֵהַךְ בְּהוּ בִּימָמָא עַל רֵישֵׁיהּ, וְעַמּוּדָא דְּאֶשְׁתָּא לְמֵיהַךְ בְּהוּ בְּלֵילָא. אֲמָרוּ לֵיהּ, תָּא חֲזֵי, אַתְרָא דָא אִיהוּ חֲשׁוֹכָא בִּימָמָא וּבְלֵילָא. אַחֲזִיאוּ לֵיהּ כָּל מָדוֹרִין דְּגֵיהִנֹּם וְאַחֲזִיאוּ לֵיהּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. וְאַחֲזִיאוּ לֵיהּ (ישעיהו נ״ו:י״א) הַכְּלָבִים עַזִּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה.</p>"],[9514013055,"<p>אֲמַר לוֹן, מָאן אִינוּן. אֲמָרוּ לֵיהּ, אִינוּן אַרְבְּעִין וּתְרֵין הֵיכָלִין חֲשׁוּכִין. וְכַמָּה גּוּבְרִין בְּשַׁלְשְׁלִין בְּצַוָּארֵיהוֹן, וַאֲסוּרִין מִן יְדֵיהוֹן וּמִן רַגְלֵיהוֹן, וְאִינוּן צָוְוחִין וְאָמְרִין וַוי וַוי. וַוי לָנָא דַּאֲזֵילְנָא בְּהַבְלֵי עָלְמָא, וְלָא אֲזֵילְנָא לְבָתֵּי כְנֵסִיּוֹת, וְלָא קָרֵינָא שְׁמָא דְּאַרְבְּעִין וּתְרֵין שְׁמָהָן, דְּלָא אוֹלִיפְנָא לֵיהּ. וַוי לָנָא, וַוי לְנַפְשָׁנָא, וּבַעַל הָאִסּוּרִין מְמוּנֶּה עֲלֵיהֶם.</p>"],[9514013056,"<p>עָאלוּ לֵיהּ לְהַלָּן, אַחֲזִיאוּ לֵיהּ ע\"ב חַלּוֹנִין חֲשׁוֹכִין, וּבְהוֹן הֲווֹ עָאלִין הַשַּׁלְשְׁלָאִין מִן צַוָּארֵיהוֹן. עָאלוּ לֵיהּ לְהַלָּן, וְאַחֲזִיאוּ לֵיהּ חַמְשִׁין שְׁעָרִין, וְכָלְהוֹ נוּקְבִין, וְרַגְלֵיהוֹן מִן חַיָּיבַיָא הֲווֹ עָאלִין בְּאִינוּן נוּקְבִין, וְאִינוּן צָוְוחִין וְאָמְרִין, וַוי לְרַגְלָנָא דַּאֲזִילוּ בְּהַבְלֵי הָעוֹלָם, וְלָא אֲזֵילְנָא לְבֵית הַכְּנֶסֶת. וְלָא לָמַדְנָא שְׁמָא דְּחַמְשִׁין תֵּיבִין מִן קְרִיאַת שְׁמַע.</p>"],[9514013057,"<p>עָאלוּ לֵיהּ לְהַלָּן, ע\"ב מָדוֹרִין, וִידֵיהוֹן אֲסִירִין בְּנוּקְבִין מִן מְזוּזְיָין דְּמִן בֵּיתָא, וְאִינוּן אָמְרִין וַוי לָנָא, וַוי לִידָנָא, דְּלָא אַקְשְׁרוּ תְּפִילִּין בְּרֵישָׁא וּבִידָנָא.</p>"],[9514013058,"<p>עָאלוּ לֵיהּ לְהַלָּן, וְאַחֲזִיאוּ לֵיהּ כָּל מְדוֹרִין דְּגֵיהִנֹּם, אֲמָרוּ, כָּל בַּר נָשׁ דְּעָלְמָא, יֵיעוֹל בְּאַתְרָא דֵין. וַאֲפִילּוּ מַאן דְּאִיהוּ חָפְשִׁי. הֲדָא הוּא דִכְתִיב, (איוב ג׳:י״ט) קָטֹן וְגָדוֹל שָׁם הוּא וְעֶבֶד חָפְשִׁי מֵאֲדֹנָיו, וְלֵית חָפְשִׁי אֶלָּא כָּל גְּבַר דְּיָדַע שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא כִּדְקָא יָאוֹת. הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י״ד-ט״ו) אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי יִקְרָאֵנִי וְאֶעֱנֵהוּ.</p>"],[9514013059,"<p>תָּא חֲזֵי, כָּל גַּבְרָא דַּעֲבֵיד עוֹבָדִין טָבִין, דְּאִינוּן מִצְוֹת עֲשֵׂה. כָּל מִצְוָה וּמִצְוָה דְּיַעֲבֵיד, אִסְתַּלַּק לְעֵילָא, וְקָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וַאֲמַר אֲנָא מִפְּלַנְיָיא דַּעֲבֵד לִי, וִיהַב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מַלְאָךְ אֶחָד, דְּיַעַזְרוּנֵיהּ בַּאֲתַר חֲשׁוֹכָא דְּגֵיהִנֹּם דְּאִתְקְרֵי לֵילְיָא דְּאִיהוּ בְּאַתְרָא הָדֵין.</p>"],[9514013060,"<p>וְכָל פִּתְגָּמָא דְּאוֹרַיְיתָא דְּשָׁמַע, עַל כָּל מִלָּה וּמִלָּה, יְהַב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מַלְאָךְ אֶחָד, לְכָל מִלָּה וּמִלָּה דְּיַעַזְרוּנֵיהּ. וְעַל דָּא (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה לְמַעַן תִּשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ כִּי אָז תַּצְלִיחַ אֶת דְּרָכֶיךָ וְאָז תַּשְׂכִּיל. וְאִם אַתְּ תַּעֲבֵיד דָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא פַּקְּדָךְ דְּתִתְעַסֵּק בְּאוֹרַיְיתָא בִּימָמָא וְלֵילֵי, וְתִיטַר וְתַעֲבֵיד כָּל מַה דְּאִית בָּהּ, לָא תִדְחַל מֵאַתְרָא דָּא. הֲדָא הוּא דִכְתִיב, (שם) הֲלֹא צִוִּיתִיךָ חֲזַק וֶאֱמָץ אַל תַּעֲרֹץ וְאַל תֵּחָת וְגו'. קוּדְשָׁא בְּרִיךְ הוּא יְהֵא עִמָּךְ בְּשַׁעֲתָא דְּתִתְעַסֵּק בְּאוֹרַיְיתָא בִּימָמָא וּבְלֵילְיָא. וְקוּדְשָׁא בְּרִיךְ הוּא יְהֵא עִמָּךְ בְּשַׁעֲתָא דְּתִשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ, קוּדְשָׁא בְּרִיךְ הוּא יְהֵא עִמָּךְ בְּשַׁעֲתָא דְּתִתְפַּטְרָא מֵעָלְמָא, וְתֵיעוֹל הָכָא.</p>"],[9514013061,"<p>וְאִי לָא תַעֲסוֹק בְּאוֹרַיְיתָא, וְלָא תִיטַר וְלָא תַעֲבֵיד פִּקּוּדֵי אוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא יִסְתַּלַּק מִנָּךְ. וּמַלְאָכָיו לָא יְצַוֶּה לָךְ לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ. הֲדָא הוּא דִכְתִיב, (ויקרא כ״ו:כ״ג-כ״ד) וְאִם תֵּלְכוּ עִמִּי קֶרִי וְגו' וְהָלַכְתִּי אַף אֲנִי עִמָּכֶם בְּקֶרִי.</p>"],[9514013062,"<p>בָּתַר דְּיַחֲזֵי לֵיהּ כָּל דָּא, וְיֵימָא לֵיהּ כָּל דָּא, אֲמַר לֵיהּ מַלְאָכָא חַד מִן הַתְּרֵין, דְּאִיהוּ יֵצֶר הַטוֹב, קוּדְשָׁא בְּרִיךְ הוּא אֲמַר לִי דַּאֲזֵילְנָא עִמָּךְ, אֲנָא וְיֵצֶר הָרָע. אוֹמֵי לִי דִּתְקַיִּים אוֹרַיְיתָא כֹּלָּא, לִלְמוֹד וּלְלַמֵּד לִשְׁמֹר וְלַעֲשׂוֹת. אוֹמֵי לֵיהּ. וּבָתַר כֵּן אֲמַר, לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ, לְגוּף שָׁפֵל, כְּמָא דַּאֲמַרְנָא.</p>"],[9514013063,"<p>וּבְשַׁעֲתָא דְּיִפּוֹק מִבֶּטֶן אִימֵּיהּ, יַתְקִיף מַלְאָךְ בִּידֵיהּ בְּצַוָּארֵיהּ, וְיַשְׁכַּח לֵיהּ אוֹרַיְיתָא, וְרָשִׁים לֵיהּ בְּאֶצְבָּעֵיהּ עַל פּוּמֵיהּ, לָא תִשְׁכַּח הַשְּׁבוּעָה דְּנִשְׁבַּעְתָּ לִי. וְאִם גַּבְרָא יַעֲבֵיד, וְאִתְקַיִּים הַשְּׁבוּעָה, יַהֲבוּ לֵיהּ כָּל מַה דְּאַחֲזִיאוּ לֵיהּ. וְאִם יוֹתֵר יַרְוִיחַ, יוֹתֵר יִתְּנוּ. הֲדָא הוּא דִּתְנַן, לְמוֹד תּוֹרָה הַרְבֵּה וְיִתְּנוּ לְךָ שָׂכָר הַרְבֵּה.</p>"],[9514013064,"<p>וְאִם לָאו, תָּא חֲזֵי, בְּבַּר נָשׁ אִית בֵּיהּ שֵׁם יהו\"ה. י\"ה, הָעוֹלָם הַבָּא. ו\"ה, הָעוֹלָם הַזֶּה. י\"ה אִתְלַבַּשׁ בִּדְיוּקְנָא עִילָּאָה, מִן גִּינְתָא דְעֵדֶן דִּלְעֵילָא. ו\"ה אִתְלַבַּשׁ בִּדְיוּקְנָא דְּעֵדֶן דִּלְתַתָּא. וְאִינוּן כְּדוּגְמָא דָא, י', אֱלִימֶלֶךְ. ה', נָעֳמִי. ו', מַחְלוֹן. ה', רוּת.</p>"],[9514013065,"<p>וְאִם הַהוּא גַּבְרָא אָזֵיל בְּאָרְחִין טָבִין, וִיקַיַּים הָאוֹמָאָה דְּאוֹמֵי, יַהֲבוּ לֵיהּ כָּל טִיבוּ דְּאַחֲזִיאוּ לֵיהּ, וְכָל מַה דְּרָוַוח בְּעָלְמָא דֵין. וְאִם לָאו, מָה אָמְרַת נִשְׁמָתָא קַדִּישָׁא, (איוב א׳:כ״א) עָרֹם יָצָאתִי מִבֶּטֶן אִמִּי וְעָרֹם אָשׁוּב שָׁמָּה. וּמַאי אִיהוּ עָרֹם, מִשְּׁמָא קַדִּישָׁא יהו\"ה דַּאֲמִינָא.</p>"],[9514013066,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְעָלְמָא, יְהַב בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא שְׁמֵיהּ בְּבַּר נָשׁ. וּשְׁמָא אָחֳרָא מִן שֵׁד יְהוּדָאי, דְּאִיתְקְרֵי חוֹל. וּשְׁמָא אָחֳרָא, דְּאִתְקְרֵי חשֶׁךְ.</p>"],[9514013067,"<p>הֲדָא הוּא דִכְתִיב, (דברים ל׳:ט״ו) רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטוֹב וְאֶת הַמָּוֶת וְאֶת הָרָע. הַחַיִּים: דָּא שֵׁם יהו\"ה דְּקוּדְשָׁא בְּרִיךְ הוּא. וְאֶת הַטוֹב: זֶה הַשֵּׁד יְהוּדָאי, דִּיהַב לֵיהּ עוֹשֶׁר בְּעָלְמָא דֵין. וְאֶת הַמָּוֶת וְאֶת הָרָע: אִלֵּין תְּרֵין מְקַטְרְגִין רְשָׁעִים טְמֵאִים, מִסִּטְרָא דִּסמא\"ל וְנָחָשׁ, מִן שָׂרוֹ שֶׁל יִשְׁמָעֵאל וְעֵשָׂו.</p>"],[9514013068,"<p>אִם בַּר נָשׁ יְקַיֵּים הָאוֹמָאָה דְּאוֹמֵי, טוֹב. וְאִם לָאו, יִסְתַּלַּק מִנֵּיהּ י\"ו, אִשְׁתְּאָרַת ה' ה'. וּבְהַאי שַׁעֲתָא, ה' עִילָּאָה מָה אָמְרַת. (יחזקאל ל״ג:י״א) שׁוּבוּ שׁוּבוּ מִדַּרְכֵּיכֶם הָרָעִים, שֶׁהֵם הָרְשָׁעִים שֶׁאָמַרְנוּ.</p>"],[9514013069,"<p>וְאִם תָּבוּ הֲרֵי טַב. וְאִם לָאו, יִסְתַּלַּק ה' עִילָּאָה עִם ו\"י, וְאִתְעֲבֵיד הו\"י. וּמַה הִיא אוֹמֶרֶת. (ישעיהו א׳:ד׳) הוֹי גוֹי חוֹטֵא וְגו'. וְאִם תָּבוּ מִדְּאִשְׁתְּאָרַת בֵּיהּ ה' תַּתָּאָה, הֲרֵי טַב. וְאִם לָאו, יִתְעֲבֵיד הוי\"ה. הֲדָא הוּא דִכְתִיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵּב. וְיִתְעֲבִידוּ הָרְשָׁעִים שַׂר עֲלֵיהֶם.</p>"],[9514013070,"<p>וּבְהַהוּא זִמְנָא, יִתְעֲבִידוּ הָרְשָׁעִים אֲדוֹנִים לְהוֹן, וּמִתְעַלֶּה הַטָמֵא דְּאִיהוּ מִסִּטְרָא דְּשָׂרוֹ שֶׁל עֵשָׂו, עַל אֱלִימֶלֶךְ וְנָעֳמִי. וְשָׂרוֹ שֶׁל יִשְׁמָעֵאל, עַל מַחְלוֹן וְרוּת. וּבְהַהִיא שַׁעֲתָא אֲמָרוּ, (ישעיהו כ״ו:י״ג) ה' אֱלֹהֵינוּ בְּעָלוּנוּ אֲדוֹנִים זוּלָתֶךָ.</p>"],[9514013071,"<p>וּבְהַהִיא שַׁעֲתָא, וַיְהִי רָעָב בָּאָרֶץ. הָאָרֶץ, דָּא גּוּפָא. וּבְהַהִיא שַׁעֲתָא, אִם יִתְעַסֵּק בַּתּוֹרָה הֲרֵי טַב. וְאִם לָאו, יֵיתֵי סמאָמַר לֵיהּ רָכִיב עַל נָחָשׁ, לֶאֱלִימֶלֶךְ. (בראשית ל״ב:כ״ו) וַיַּרְא כִּי לֹא יָכוֹל לוֹ וַיִּגַּע בְּכַף יְרֵכוֹ. אָזִיל לְאִתְּתָא נָעֳמִי, יַהֲפֹךְ לָהּ, וְיַעֲבֵיד לָהּ דְּתֵיחוֹב, וּתְהֵא בִּישָׁא.</p>"],[9514013072,"<p>אִם אָדָם אִתְפְּרַשׁ מִינָהּ, הֲרֵי טַב. כְּמָא דַּאֲמַר אִיּוֹב, (איוב ב׳:י׳) כְּדַבֵּר אַחַת הַנְּבָלוֹת תְּדַבֵּרִי גַּם אֶת הַטוֹב נְקַבֵּל מֵאֵת הָאֱלֹהִים וְהָרָע לֹא נְקַבֵּל. הָעֵצָה דִּיהַב לָךְ הַטָמֵא, לֹא נְקַבֵּל. וְאִם יָקוּם עֲצַת הַחֵטְא כְּמוֹ שֶׁאָמְרָה הִיא, וְיִגְנוֹב אוֹ יַעֲשֶׂה כָּל הָעֲבֵירוֹת שֶׁבָּעוֹלָם, אַחַר כַּךְ יִתְלוּהוּ עַל הָעֵץ וְיָמוּת. הֲדָא הוּא דִכְתִיב, (רות א׳:ה׳) וַיָּמוּתוּ גַּם שְׁנֵיהֶם מַחְלוֹן וְכִלְיוֹן. וְנִשְׁאֲרוּ ה\"ה אַלְמָנוֹת.</p>"],[9514013073,"<p>וַתֹּאמֶר נָעֳמִי, וּמַה הִיא אוֹמֶרֶת. וַ\"י וַ\"י וַ\"ה. וְעִם כָּל זֶה נָעֳמִי אוֹמֶרֶת, (שם) שֹׁבְנָה בְנוֹתַי, שׁוּבוּ שׁוּבוּ בִּתְשׁוּבָה, הַעוֹד לִי בָנִים בְּמֵעַי וְהָיוּ לָכֶם לַאֲנָשִׁים, י\"ו דְּאִסְתַּלָּקוּ. עָרְפָּה מִסִּטְרָא דִּמְסָאֲבוּ, תָּשׁוּב אֶל עַמָּהּ וְאֶל אֱלֹהֶיהָ. וְרוּת דָּבְקָה עִם נָעֳמִי, הֲדָא הוּא דִכְתִיב, (שם) אֶל אֲשֶׁר תֵּלְכִי אֵלֵךְ.</p>"],[9514013074,"<p>וְאִם תָּבוּ בִּתְיוּבְתָּא, יֵיתֵי אֱלִימֶלֶךְ, וְיֵיתֵי מַחְלוֹן. וְאִם תָּבוּ כּוּלְהוֹ, יֵיתֵי שְׁמָא קַדִּישָׁא עִילָּאָה. וְאִם לָא, יָמוּתוּ. הֲדָא הוּא דִכְתִיב, (שם) וַתֵּצֵא מִן הַמָּקוֹם אֲשֶׁר הָיְתָה שָׁמָּה וּשְׁתֵּי כַלּוֹתֶיהָ עִמָּהּ, נְפָקוּ מִגּוּפָא.</p>"],[9514013075,"<p>בְּהַהִיא שַׁעֲתָא אִיהִי אָזְלַת לְנָטְרֵי גַּן עֵדֶן, לְמֵיעַל בְּגִנְתָא דְעֵדֶן, דְּחַיִּין לָהּ לְבַר, וְאָזְלַת בַּאֲתַר דַּחֲשׁוֹכָא. (שם) וַתֵּהֹם כָּל הָעִיר עֲלֵיהֶן וַתֹּאמַרְנָה הֲזֹאת נָעֳמִי. בְּהַהִיא שַׁעֲתָא אֲמָרַת, אֲנִי מְלֵאָה הָלַכְתִּי וְרֵיקָם הֱשִׁיבַנִי ה', שְׁמָא קַדִּישָׁא דְּהֲוָה בִּי. הֲדָא הוּא דִכְתִיב, (שם) וַה' עָנָה בִי, שְׁמָא קַדִּישָׁא דְּיהו\"ה, אַסְהֵיד בִּי כָּל חוֹבִין דַּעֲבִידְנָא.</p>"],[9514013076,"<p>בְּהַהִיא שַׁעֲתָא יֵיתֵי נָחָשׁ וְנָסֵיב לָהּ לְשִׁפְחָה. בְּהַהִיא שַׁעֲתָא אֲמָרַת, (ישעיהו א׳:כ״א) אֵיכָה הָיְתָה לְזוֹנָה קִרְיָה נֶאֱמָנָה מְלֵאֲתִי מִשְׁפָּט צֶדֶק יָלִין בָּהּ וְעַתָּה מְרַצְּחִים.</p>"],[9514013077,"<p>י\"ו נִשְׁאֲרוּ עָנִי וְדָל, (זכריה ט׳:ט׳) עָנִי וְרוֹכֵב עַל חֲמוֹר. דַּל, עֲלֵיהּ אִתְּמָר (תהילים מ״א:ב׳-ג׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. אִם יִשָּׁאֵר לוֹ בֵּן דְּאָזֵיל בְּאָרְחוֹהִי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעַסַּק בְּאוֹרַיְיתָא, אַפֵּיק לוֹ מִן רָעָה. שֶׁהֵם מִתְפָּרְדִּים בְּד' פִּנּוֹת הָעוֹלָם.</p>"],[9514013078,"<p>כְתִיב (ישעיהו כ״ט:כ״ב) כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם. יַעֲקֹב לָא הֲוָה בְּעָלְמָא, וְאַתְּ אָמֵר אֲשֶׁר פָּדָה אֶת אַבְרָהָם.</p>"],[9514013079,"<p>אֶלָּא תָּא חֲזֵי, בְּשַׁעֲתָא דְּאַפִּילוּ לְאַבְרָהָם בְּנוּרָא יָקֵידְתָּא, בְּקַדְמִיתָא הֲווֹ דַּיְינִין לֵיהּ לְעֵילָא, אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, כָּרְסְיָא דִילִי, זִילִי וְשֵׁזֵיבִי לְאַבְרָהָם מִן אוּר כַּשְׂדִּים, שֶׁבִּשְׁבִיל כְּבוֹדִי עָבִיד מַה דְּעָבִיד.</p>"],[9514013080,"<p>אֲמָרוּ לֵיהּ מַלְאֲכֵי הַשָּׁרֵת, רִבּוֹנוֹ שֶׁל עוֹלָם, גַּבְרָא דְּיִפּוֹק מִינֵיהּ יִשְׁמָעֵאל, דְּיַעַבְדִין לְהוֹ לְיִשְׂרָאֵל מַה דְּיַעַבְדִין. אֲמַר לְהוֹ כֵּן יִפּוֹק מִינֵיהּ יִצְחָק, דְּיוֹשִׁיט קַדְלֵיהּ עַל גַּבֵּי מַדְבְּחָא. אֲמָרוּ לֵיהּ, הָא עֵשָׂו דְּנָפֵיק מִינֵיהּ דְּיַחֲרִיב בֵּי מַקְדְּשָׁא. אֲמַר, הָא נָפֵיק מִינֵיהּ יַעֲקֹב, דְּאִיהוּ כּוּרְסְיָא שְׁלֵימָא. אֲמָרוּ, הָא וַדַּאי בִּזְכוּתָא דְּיַעֲקֹב יִשְׁתְּזֵיב. הֲדָא הוּא דִכְתִיב, כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם.</p>"],[9514013081,"<p>וּבְשַׁעֲתָא דִּכְפִיתוּ לַחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, לְמִרְמֵי לְגוֹ אַתּוּן נוּרָא יָקֵידְתָּא, פְּתַח חֲנַנְיָה וַאֲמַר, ה' לִי (תהלים קיח) לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם. ה' לִי בְּעוֹזְרָי וַאֲנִי אֶרְאֶה בְשׂוֹנְאָי. פְּתַח מִישָׁאֵל וַאֲמַר, כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ כִּי בִרְאוֹתוֹ יְלָדָיו מַעֲשֵׂה יָדַי וְגו'.</p>"],[9514013082,"<p>וּבְהַהִיא שַׁעֲתָא דָּנוּ דִינֵיהּ לְעֵילָא, אֲמַר הַקָדוֹשׁ בָּרוּךְ הוּא, (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַה' אָנִי, זֶה חֲנַנְיָה, שֶׁאָמַר ה' לִי בְּעוֹזְרָי וַאֲנִי אֶרְאֶה בְשׂוֹנְאָי. וְזֶה יִקְרָא בְּשֵׁם יַעֲקֹב, זֶה מִישָׁאֵל, שֶׁאָמַר כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב וְגו'. וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה, זֶה עֲזַרְיָה, שֶׁאָמַר שְׁמַע יִשְׂרָאֵל.</p>"],[9514013083,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דַּאֲמַר מִישָׁאֵל, כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם, עֲבָדוּ לֵיצָנוּת בְּלִישָׁנֵיהוֹן. אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, כּוּרְסְיָיא דִילִי, הַהוּא לֵיצָנוּתָא דַּעֲבָדוּ, שֵׁזִיב לוֹן בְּדַרְגָּא דָא, כְּמָה דְּשֵׁזִיבַת לְאַבְרָהָם. וְלֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ. בְּהַהִיא שַׁעֲתָא, כָּל אִינוּן דִּכְפִיתוּ לוֹן, קָטַל לוֹן שְׁבִיבָא דְּנוּרָא.</p>"],[9514013084,"<p>דָּנִיֵּאל אַמַּאי לָא הֲוָה עִמְּהוֹן. אֲמַר בְּלִבֵּיהּ, הָא עֲבָדוּ מִינֵיהּ צַלְמָא. וּמַלְכָּא אֲמַר, שְׁמֵיהּ כְּשֵׁם אֱלוֹהַּ דִּילֵיהּ, הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ה׳) דִּי שְׁמֵיהּ בֵּלְטְשַׁאצַר כְּשֵׁם אֱלֹהָי. וּכְתִיב (דברים ז׳:כ״ה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ, וְעַל דָּא אִתְכַּסֵּי מִינַּיְיהוּ. וְכִי אָדָם יִבְרַח מִן הַמַּלְכוּת, אֶלָּא מַלְאָכִין הֲווֹ מְכַסִין לֵיהּ.</p>"],[9514013085,"<p>מַה רָאוּ חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה דְּיַהֲבוּ גַּרְמַיְיהוּ לְנוּרָא. אֶלָּא תָּא חֲזֵי, יוֹמָא חַד הֲוָה דָּוִד נָחֵית לְהַנּוֹת גּוּפוֹ לִפְנֵי הַנָּהָר. וַהֲוָה אֲמַר, (תהילים פ״ו:ב׳) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. אֲמָרוּ לֵיהּ, וְאַתָּה חָסִיד. אֲמַר לְהוֹ, וְלֹא חָסִיד אֲנִי, שֶׁיָּדַי מְלוּכְלָכוֹת בִּשְׁפִיר וּבְשִׁלְיָא, וּמְטַהֵר אֶת הַטָהוֹר, וּמְטַמֵּא אֶת הַטָמֵא. וַאֲנִי קָם בְּחֶדְוָה בְּג' מִשְׁמָרוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. וַאֲנָא נָאִים כְּסוּסְיָא בְּהֶבֶל א'.</p>"],[9514013086,"<p>וּבַחֲצוֹת לַיְלָה אָקוּם לְהִתְעַסֵּק בַּתּוֹרָה. וּבְמִשְׁמָרָה שְׁלִישִׁית, אֲנִי מְנַגֵּן עִם הַמַּלְאָכִים לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (איוב לח) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מָאן אִינוּן, מַלְאָכִין קַדִּישִׁין דַּאֲמָרָן שִׁירָה עִמִּי בַּלַּיְלָה. הֲדָא הוּא דִכְתִיב, (תהלים מב) וּבַלַּיְלָה שִׁירֹה עִמִּי תְּפִלָּה לְאֵל חַיָּי.</p>"],[9514013087,"<p>אֲמָרוּ הַצְּפַרְדְּעִים, אֲנַחְנָא עֲבִידְנָא יַתִּיר מִינָּךְ בְּדִיל קוּדְשָׁא בְּרִיךְ הוּא, אֲמַר לוֹן דָּוִד, וּמָה עֲבַדְתּוּן אַתּוּן יַתִּיר מִינִּי. אֲמָרוּ לֵיהּ, דַּהֲוֵינָן מוֹקְדִין גּוּפָנָא בְּנוּרָא בְּתַנּוּרָא בְּמִצְרַיִם. וּבְשַׁעֲתָא דַּהֲווֹ מְכַפְתִּין חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה, אֲמָרוּ בְּלִבַּיְיהוּ דְּנַעֲבֵיד כַּצְּפַרְדְּעִים.</p>"],[9514013088,"<p>תַּנְיָא, שָׁלשׁ מִשְׁמָרוֹת הֲוֵי הַלַּיְלָה, וְעַל כָּל מִשְׁמָר וּמִשְׁמָר יוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹאֵג כָּאֲרִי. תָּא חֲזֵי, שָׁלשׁ מִשְׁמָרוֹת אִינוּן י\"ב שַׁעֲתֵי, וְאִתְפַּלְגּוּן ד' לְכָל מִשְׁמָר. וּבְכָל מִשְׁמָר יוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹאֵג כָּאֲרִי, וְאוֹמֵר אוֹי שֶׁהֶחֱרַבְתִּי אֶת בֵּיתִי וכו'.</p>"],[9514013089,"<p>תָּא חֲזֵי, כְּדוּגְמָא דְּאִית מִשְׁמָרוֹת בִּרְקִיעָא, כָּךְ אִית מִשְׁמָרוֹת בְּאַרְעָא. וּמָאן אִינוּן. מִשְׁמָרָה שְׁנִיָה, כְּלָבִים צוֹעֲקִים. הֲדָא הוּא דִכְתִיב, (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. (ישעיה נו) וְהַכְּלָבִים עַזִּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה. רִאשׁוֹנָה, חֲמוֹר נוֹעֵר. הֲדָא הוּא דִכְתִיב, (דברים כב) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו.</p>"],[9514013090,"<p>וְעַל דָּא בִּלְעָם בָּזֶה הַחֲמוֹר וּבְאִשְׁתּוֹ, הָיָה מִתְנַבֵּא. הֲדָא הוּא דִכְתִיב, (שם לד) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמשֶׁה. אֲבָל בְּאוּמוֹת הָעוֹלָם קָם. וְכִי מְטוּנָּף מִן הַטִנּוֹפֶת, אַתָּה מַזְכִּיר עִם הַטָהוֹר. אֶלָּא משֶׁה בַּטָהֳרָה. וּבִלְעָם בַּטוּמְאָה. וְעֲבוֹדָה זָרָה הָיָה עוֹשֶׂה מַעֲשֶׂה אִישׁוּת עִם הָאָתוֹן.</p>"],[9514013091,"<p>כְתִיב (שם) כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךָ וְגו', תָּא חֲזֵי, קַן: דָּא הוּא גּוּפָא. בַּדֶּרֶךְ: דְּאָזֵיל בְּאוֹרְחִין טָבִין. בְּכָל עֵץ: דָּא תּוֹרָה, כְּמָה דְאַתְּ אָמֵר (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. אוֹ עַל הָאָרֶץ: אִלֵּין אִינוּן יִשְׂרָאֵל, דְּאִתְקְרוּן אֶרֶץ, דִּמְלַמֵּד לְהוֹן אוֹרַיְיתָא. אֶפְרוֹחִים: אִלֵּין אִינוּן נְעָרִים גְּדוֹלִים, דְּיִתְעַסְּקוּן בְּאוֹרַיְיתָא. אוֹ בֵּיצִים: אִלֵּין זְעִירִין, דְּיוֹלִיף לוֹן אל\"ף בי\"ת.</p>"],[9514013092,"<p>וְהָאֵם רוֹבֶצֶת, אֵין אֵם אֶלָּא תּוֹרָה, הֲדָא הוּא דִכְתִיב, (שם א) וְאַל תִּטוֹשׁ תּוֹרַת אִמֶּךָ. אִם תִּרְצֶה שֶׁתִּקַּח הַבָּנִים, (דברים כב) שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם, וְאַחַר כַּךְ וְאֶת הַבָּנִים תִּקַּח לָךְ וְהַאֲרַכְתָּ יָמִים.</p>"],[9514013093,"<p>דָּבָר אַחֵר כִּי יִקָּרֵא, כְּמָה דְאַתְּ אָמֵר וְאִם תֵּלְכוּ עִמִּי קֶרִי, וְהָלַכְתִּי אַף אֲנִי עִמָּכֶם בְּקֶרִי. וְיָסַפְתִּי לְיַסְּרָה אֶתְכֶם שֶׁבַע עַל חַטֹאתֵיכֶם. מַאן אִיהִי שֶׁבַע, דָּא שְׁכִינְתָּא.</p>"],[9514013094,"<p>בַּדֶּרֶךָ: דָּא קְבוּרַת רָחֵל, דְּאִיהִי קָיְימָא בְּפָרָשַׁת דְּרָכִים, וִיבַשֶּׂר לָהּ וִינַחֵם לָהּ וְלָא צְבִיאַת לְקַבְּלָא תַּנְחוּמִין, הֲדָא הוּא דִכְתִיב, (ירמיה לא) מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ. וּבִשְׁבִיל דַּאֲזָלוּ עִמּוֹ בְּקֶרִי, גָּלָה לְהוֹן, וּשְׁכִינְתָּא גָּלְתָה עִמְּהוֹן.</p>"],[9514013095,"<p>בְּכָל עֵץ: דָּא יְרִיחוֹ. אוֹ עַל הָאָרֶץ: דָּא יְרוּשָׁלַ ם. אֶפְרוֹחִים: אִלֵּין כְּרוּבִים דִּלְעֵילָא. אוֹ בֵיצִים: אִלֵּין כְּרוּבִים דִּלְתַתָּא. אַנְפֵּי רַבְרְבֵי, וְאַנְפֵּי זוּטְרֵי.</p>"],[9514013096,"<p>וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים אוֹ עַל הַבֵּיצִים לֹא תִקַּח הָאֵם עַל הַבָּנִים שַׁלֵּחַ תְּשַׁלַּח אֶת הָאֵם. הֲדָא הוּא דִכְתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאֶת הַבָּנִים תִּקַּח לָךְ לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים, בִּשְׁבִיל דְּאִימָּא אָזְלָא וּמְנַדְּדָא מִגּוֹזְלָהּ וּמִקִּינָהּ. וְדָא גָרֵים לָךְ אֲרִיכוּ דְּאַנְפִּין, שִׁית יוֹמִין דִּלְעֵילָא, דִּירַחֲמוּ עַל עָלְמָא. הֲדָא הוּא דִכְתִיב, (שמות ל״ד:ו׳) ה' ה' אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וֶאֱמֶת. וְאָרִיךְ רוּגְזָא מִן אַפִּין דְּאִסְתַּלָּקוּ בְּחוֹבֵיהוֹן דְּיִשְׂרָאֵל. הֲדָא הוּא דִכְתִיב, (שם לג) וְרָאִיתָ אֶת אֲחוֹרָי וּפָנַי לֹא יֵרָאוּ.</p>"],[9514013097,"<p>(שיר השירים ו׳:ב׳) דּוֹדִי יָרַד לְגַנּוֹ לַעֲרֻגוֹת הַבֹּשֶׂם לִרְעוֹת בַּגַּנִּים וְלִלְקֹט שׁוֹשַׁנִּים. תָּא חֲזֵי, כָּל הַשִּׁירִים קֹדֶשׁ, וְשִׁיר הַשִּׁירִים קֹדֶשׁ קֳדָשִׁים. כְּנֶסֶת יִשְׂרָאֵל מְשַׁבַּחַת לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְאוֹמֶרֶת דּוֹדִי. הֲדָא הוּא דִכְתִיב, (שם ה) דּוֹדִי צַח וְאָדוֹם.</p>"],[9514013098,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דִּיהֵא פַּלְגוּת לֵילְיָא. אִיתְעַר שַׁלְהוֹבָא חָדָא, וְיֵעוֹל תְּחוֹת גַּדְפֵי דְּתַרְנְגוֹלָא, וְקָארֵי. וּבְהַהוּא שַׁעֲתָא, קוּדְשָׁא בְּרִיךְ הוּא יָרַד אֶל גַּנּוֹ, דְּאִיהוּ גַּן עֵדֶן עִילָּאָה, דְּאִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. וּבְהַהִיא שַׁעֲתָא אִתְעַר תַּרְנְגוֹלָא דִּלְעֵילָא, וַאֲמַר, קוּמוּ כָּל אִינוּן דְּשֵׁינְתָא בְּחוֹרֵיהוֹן, הָא שַׁעֲתָא אִיהִי לְאִתְחַבְּרָא אַיַּילְתָּא בְּבַעֲלָהּ. זַכָּאָה אִיהוּ כָּל בַּר נָשׁ דִּיקוּם בְּפַלְגוּת לֵילְיָא לְאִתְעַסְּקָא בְּאוֹרַיְיתָא. דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָיא אֲצִיתוּ לְקָלֵיהּ. הֲדָא הוּא דִכְתִיב, (שם ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִינִי.</p>"],[9514013099,"<p>וּבְהַאי שַׁעֲתָא, מַאן דְּאִתְעַסַּק בְּאוֹרַיְיתָא, אִיתָּרַק עֲלֵיהּ חַד חוּטָא דְּחֶסֶד. וּבְהַאי שַׁעֲתָא, קוּדְשָׁא בְּרִיךְ הוּא יָרַד לְגַנּוֹ. לְמִי יָרַד, לַעֲרוּגּוֹת הַבּוֹשֶׂם. וּמַאן אִינוּן עֲרוּגּוֹת הַבּוֹשֶׂם, הֲדָא הוּא דִכְתִיב, (שממות ל) בְּשָׂמִים רֹאשׁ. וּמַאן אִינוּן, צַדִּיקִים.</p>"],[9514013100,"<p>לִרְעוֹת בַּגַּנִּים, בְּגַן עֵדֶן דִּלְעֵילָא, וְגַן עֵדֶן דִּלְתַתָּא, דְּאִיקְּרֵי הָעוֹלָם הַזֶּה, וְהָעוֹלָם הַבָּא. לִלְקוֹט שׁוֹשַׁנִּים, מַאן אִינוּן שׁוֹשַׁנִּים. אִלֵּין צַדִּיקַיָיא דְּאִתְעַסְּקוּ בְּאוֹרַיְיתָא, וְאִינוּן דִּמְרַחְשָׁן אוֹרַיְיתָא בְּשִׂפְוָותַיְיהוּ. הֲדָא הוּא דִכְתִיב שׁוֹשַׁנִּים, אַל תִּקְרֵי שׁוֹשַׁנִּים, אֶלָּא שֶׁשּׁוֹנִים, שֶׁאֲפִילּוּ בַּקֶּבֶר רוֹחֲשׁוֹת תּוֹרָה.</p>"],[9514013101,"<p>אָמַר לֵיהּ, וְכִי לְאִינוּן דְּאִתְעַסְּקֵי בְּאוֹרַיְיתָא קָטֵיל לוֹן קוֹדֶם זְמַנָּם, וְאִינוּן צַדִּיקִים דְּלָא חָבוֹ. תָּא חֲזֵי, יָרָבְעָם בְּשַׁעֲתָא דְּהֲוָה יְנוּקָא, הֲוָה זַכַּאי, וְלָא הֲוָה לֵיהּ חוֹבָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַלְאַךְ הַמָּוֶת, זִיל וְאַיְיתֵי לְיָרָבְעָם בֶּן נְבָט.</p>"],[9514013102,"<p>בְּהַהוּא שַׁעֲתָא אָמְרוּ מַלְאֲכֵי הַשָּׁרֵת, (תהילים ח׳:ב׳) ה' אֲדוֹנֵנוּ מָא אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. מָה דְּשִׁמְךָ אִיהוּ אַדִּיר בֵּיהּ, וְהוּא צַדִּיק, אֲנַח לֵיהּ, וְעַל זְכוּתָא דִּילֵיהּ יֵיתֵי שֶׁפַע לָנָא. אֲמַר לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִי רַעֲוָא דִּילְּכוֹן דְּאֶשְׁבּוֹק לֵיהּ, אֲנָא שָׁבֵיק לֵיהּ.</p>"],[9514013103,"<p>וּבָתַר כֵּן נְפַק לְתַרְבּוּת רָעָה, וְעָבִיד תְּרֵי עֶגְלֵי דְּדַהֲבָא, וְחָטָא וְהֶחֱטִיא אֶת יִשְׂרָאֵל. אֲמַר לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא, הֲרֵי כָּל שֶׁפַע דְּהֲוָה יָהֵיב לְכוֹן, אִתְהַפַּךְ לְכוֹן בְּזוּהֲמָא, לָא הֲוָה טַב לְכוֹן דְתֵייתִי לֵיהּ הָכָא בְּשַׁעֲתָא דְּהֲוָה זַכַּאי, וַהֲוָה אוֹלִיף לֵיהּ מטטרו\"ן אוֹרַיְיתָא. בְּשַׁעֲתָא הַהִיא, פָּתְחוּ כָּלְהוֹ וַאֲמָרוּ, (תהילים קי״ט:קל״ז) צַדִּיק אַתָּה ה' וְיָשָׁר מִשְׁפָּטֶיךָ. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא יָרַד לְגַנּוֹ לִלְקֹּט שׁוֹשַׁנִּים.</p>"],[9514013104,"<p>פְּתַח יָנוּקָא וַאֲמַר, (מיכה ו׳:ג׳) עַמִּי מֶה עָשִׂיתִי לְךָ וּמָה הֶלְאֵתִיךָ עֲנֵה בִּי. קוּדְשָׁא בְּרִיךְ הוּא בַּחֲבִיבוּתָא דְּאִית לֵיהּ עִם יִשְׂרָאֵל, קָרָא לְהוֹן עַמִּי. מֶה עָשִׂיתִי לְךָ, לָמָּה עָשִׂיתִי לְךָ. אֶלָּא דְּתֵזְלִין לְבָתֵּי כְנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת, וְתַסְהִידוּ בִּי דַּאֲנָא אֶחָד, הֲדָא הוּא דִכְתִיב ז (דברים ו) ה' אֶחָד.</p>"],[9514013105,"<p>תַּסְהִיהוּ דַּאֲנָא חַד, וּמִתְעַלֶּה עַל שְׁמָא דְּמ\"ב תֵּיבִין, דְּאִינוּן בְּפָרָשַׁת קְרִיאַת שְׁמַע, מִן וְאָהַבְתָּ עַד וְהָיָה. וְתַעֲבִידוּ לְיַחֲדֵנִי עֲלַיְיכוּ. וְאִיהוּ שְׁמָא כְּדוּגְמָא שְׁמָא דְּמ\"ב שְׁמָהָן.</p>"],[9514013106,"<p>וּבִשְׁמָא דְּע\"ב תֵּיבִין, דְּאִית בְּפָרָשַׁת קְרִיאַת שְׁמַע, מִן וְהָיָה עַד וְשַׂמְתֶּם. וּבִשְׁמָא דַּחֲמִשִּׁין תֵּיבִין, מִן וְשַׂמְתֶּם עַד סוֹף פָּרָשָׁתָא, כְּחוּשְׁבַּן שַׁעֲרֵי בִינָה. וּבִשְׁמָא דְּע\"ב, מִן וַיֹּאמֶר עַד סוֹף הַפָּרָשָׁה.</p>"],[9514013107,"<p>וְאִינוּן אַרְבַּע פָּרָשִׁיָּין, עִם י\"ב תֵּיבִין דְּאִית בִּקְרִיאַת שְׁמַע, תְּרֵין יִחוּדִין עִילָּאִין, יִתְעֲבִידוּ כָּלְהוֹ מָאתָן וְאַרְבָּעִין וּתְמַנְיָא, כְּחוּשְׁבַּן רמ\"ח אֵבָרִים. וְכָל אֵינַשׁ דְּיִקְרֵי קְרִיאַת שְׁמַע כִּדְקָא יָאוֹת, כָּל תֵּיבָה וְתֵּיבָה מַשְׁפִּיעַ בְּכָל אֵבָר וְאֵבָר דִּילֵיהּ. וְאִי אֵינַשׁ לָא יִקְרֵי קְרִיאַת שְׁמַע בִּימָמָא וּבְלֵילְיָא, כָּל אֵבָר וְאֵבָר דִּילֵיהּ יִתְמְלֵי מִן רוּחַ רָעָה, וּמִכָּל מִלִּין וּמַרְעִין בִּישִׁין דְּעָלְמָא.</p>"],[9514013108,"<p>אֲמַר יְנוּקָא, תְּלַת תֵּיבִין אִינוּן, דְּחַסְרִין מִן קְרִיאַת שְׁמַע, מִן רמ\"ח תֵּיבִין, וּבַמֶּה אִשְׁתְּלִימוּ. אֲמַר, אֲנָא שְׁמַעְנָא מֵאַבָּא, עִם ה' אֱלֹהֵיכֶם אֱמֶת שֶׁהָשְׁלִיחַ צִבּוּר חוֹזֵר בְּקוֹל.</p>"],[9514013109,"<p>פְּתַח סָבָא דִּינוּקָא וַאֲמַר, עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעַט וְגו', (קהלת ט) וּמָצָא בָהּ יֶלֶד מִסְכֵּן חָכָם וְגו'. תָּא חֲזֵי, עִיר קְטַנָּה, דָּא תֵּיבַת נֹחַ. וַאֲנָשִׁים בָּהּ מְעַט, אֵלּוּ אִשְׁתּוֹ וּבָנָיו וּנְשֵׁי בָנָיו, וְחַיּוֹת וְעוֹפוֹת וּבְהֵמוֹת. וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל וְסָבַב אוֹתָהּ, זֶה יֵצֶר הָרָע. וּמָצָא בָהּ אִישׁ מִסְכֵּן וְחָכָם, דָּא נֹחַ. וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ.</p>"],[9514013110,"<p><Noneb>סִתְרֵי תּוֹרָה </b></p>"],[9514013111,"<p>סְעוּדְתֵי דְשַׁבָּת בְּכָל אִינוּן אוּכְלוּסִין עִילָּאִין. (שמות ט״ז:כ״ה) וַיֹּאמֶר משֶׁה אִכְלוּהוּ הַיּוֹם כִּי שַׁבָּת הַיּוֹם לַד'. הַיּוֹם לֹא תִמְצָאֻהוּ בַּשָּׂדֶה. תְּלַת זִמְנִין הַיּוֹם, כְּחוּשְׁבַּן תְּלַת סְעוּדְתֵי, דְּאִתְקְרִיאוּ עֹנֶג. וּמַהוּ עֹנֶג. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ח:י״ג) וְקָרָאתָ לַשַּׁבָּת עֹנֶ\"ג. (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וּבְחֶשְׁבּוֹן תְּלַת גָּלוּיּוֹת, שֶׁאָמַר משֶׁה כְּנֶגְדָן אֶהְיֶ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה תְּלַת זִמְנִין.</p>"],[9514013112,"<p>אֲנָא אֶהְיֶה עִמְּכוֹן בְּגָלוּתָא קַדְמָאָה, הֲדָא הוּא דַּאֲמָרוּ, גָּלוּ לְמִצְרַיִם שְׁכִינָה עִמָּהֶם. וַאֲנָא אֶהְיֶה עִמְּכוֹן בְּגָלוּתָא תִּנְיָינָא, הֲדָא הוּא דִכְתִיב, גָּלוּ לְבָבֶל שְׁכִינָה עִמָּהֶם. וַאֲנָא אֶהְיֶה עִמְּכוֹן בְּגָלוּתָא תְּלִיתָאָה, הֲדָא הוּא דִכְתִיב גָּלוּ לְיָוָן שְׁכִינָה עִמָּהֶם. אֶהְיֶה רְבִיעָאָה לָא גִּילָּה לְהוֹן, אֶלָּא (ישעיהו ס׳:כ״ב) אֲנִי ה' בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ אֲחִישֶׁנָּה, לֹא זָכוּ בְּעִתָּהּ.</p>"],[9514013113,"<p>אָמַר רַבִּי פִּנְחָס, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַסּוֹת אֶת יִשְׂרָאֵל וכו'.</p>"],[9514013114,"<p>תָּא חֲזֵי, אִם יָשִׁיבוּ לֹא נִשְׁאֲרוּ בַּגָּלוּת יוֹם א' שָׁלֵם. אֲמַר לֵיהּ בַּחֲשַׁאי, מַהוּ יוֹם א', זֶהוּ שֶׁאָמַר (בראשית כ״ט:ז׳) הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה וְגו'. אִם תָּבוּ בִּתְיוּבְתָּא, יֵצְאוּ לִזְמַן הַיּוֹם שֶׁאָמַר הַנָּבִיא. וְאִם לֹא עֵת הֵאָסֵף הַמִּקְנֶה, הַשְׁקוּ הַצֹּאן וּלְכוּ רְעוּ. בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, אִם לָא תָבוּ בִּתְיוּבְתָּא, לָא יִפְקוּן עַד דְּיִשְׁתְּלֵים שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא יהו\"ה.</p>"],[9514013115,"<p>דָּבָר אַחֵר, יִשְׂרָאֵל נִמְשְׁלוּ לְיוֹנָה, וְהַכְּנָפַיִם לְמִצְוֹת, כְּמוֹ בְּשָׁעָה שֶׁהַיּוֹנָה יֵשׁ לָהּ כְּנָפַיִם, וְהַכְּנָפַיִם שְׁלֵימִים, לֹא יֵשׁ עוֹף בָּעוֹלָם שֶׁיִּקָּחֶהָ. כָּךְ יִשְׂרָאֵל, בְּשָׁעָה שֶׁהֵם שְׁלֵמִים בְּמִצְוֹת, לֹא יֵשׁ בְּכָל הָעוֹלָם מִי שֶׁיּוּכַל לָהֶם. כְּמוֹ שֶׁהוּא כָּתוּב בְּפ' בִּלְעָם (במדבר כ״ג:ח׳) מָה אֶקֹּב לֹא קַבֹּה אֵל וּמָה אֶזְעֹם לֹא זָעַם ה'. וְאַחַר כַּךְ זָנוּ אַחֲרֵי אֱלֹהֵיהֶם, וַיִּחַר אַף ה' בָּהֶם.</p>"],[9514013116,"<p>וְעַל דָּא (במדבר ט״ו:ל״ט) וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם אֲשֶׁר אַתֶּם זֹנִים אַחֲרֵיהֶם. וּמַהוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם. זֶהוּ רַק רַע כָּל הַיּוֹם, וְזֶהוּ (משלי כ׳:י״ד) רַע רַע יֹאמַר וְגו'.</p>"],[9514013117,"<p>וְעַל דָּא (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי. הֲדָא הוּא דִכְתִיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. וּכְתִיב (דברים ל״ב:כ׳) אַסְתִּירָה פָנַי מֵהֶם אֶרְאֶה מָה אַחֲרִיתָם וְגו'. וְעַל דָּא בְּשָׁעָה שֶׁיִּשְׂרָאֵל הָיוּ בְּלֵב שָׁלֵם לִפְנֵי ה', מֶה הָיָה. פָּנִים בְּפָנִים דִּבֶּר ה'. וְאִם לָאו, בְּסִטְרָא דַּאֲחוֹרַיִים. וְזֶהוּ הָעֲרָיוֹת. הֲדָא הוּא דִכְתִיב, (ויקרא י״ח:ז׳) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה.</p>"],[9514013118,"<p>וְיֵשׁ אָחוֹר מִן קְדוּשָּׁה. הֲדָא הוּא דִכְתִיב, (הושע י״א:י׳) אַחֲרֵ\"י ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג. וְאִתְקְרֵי פָּנִים לְגַבֵּי מַטָה, וְאָחוֹר לְגַבֵּי מַעְלָה. וְאִתְקְרֵי חוֹל לְגַבֵּי מַעְלָה, וְקוֹדֶשׁ לְגַבֵּי מַטָה.</p>"],[9514013119,"<p>וְזֶה בִּקֵּשׁ משֶׁה לֵידַע, זֶה שֶׁהָיָה פָּנִים לְגַבֵּי מַעְלָה. וְאָמַר לֵיהּ, כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. וְאַחַר כַּךְ בִּקֵּשׁ שֶׁיִּתֵּן נְשָׁמָה לְיִשְׂרָאֵל מִן הַפָּנִים שֶׁהֵם לְמַטָה, וְנִקְרְאוּ אֲחוֹרַיִם לְגַבֵּי מַעְלָה. וְאָמַר לֵיהּ, וְרָאִיתָ אֶת אֲחוֹרָי. אַתָּה תִרְאֶה וְהֵם לֹא יִרְאוּ. הֲרֵי תָּבִין שֶׁהָיָה לְגַבֵּיהּ אָחוֹר, וּלְגַבֵּי יִשְׂרָאֵל פָּנִים. וְעַל זֶה אָמַר לֹא יֵרָאוּ, וְלֹא אָמַר לֹא תִרְאֶה.</p>"],[9514013120,"<p>תָּא חֲזֵי, בְּחוֹבָא דְּאָדָם קַדְמָאָה, אָבְדוּ הַפָּנִים עִילָּאִין. וּבְחוֹבָא דְעֵגֶל, פָּנִים תַּתָּאִין, דְּאִתְקְרֵי אָחוֹר לְגַבֵּי עֵילָא. וּבְכָל גָּלוּת וְגָלוּת אָבָדוּ. וְאִיהוּ רָזָא רַבְרְבָא, וְכָל דָּא נִרְמַז בְּשֵׁם יהו\"ה. י', פָּנִים עִילָּאִין. ה', אָחוֹר לְגַבֵּי י', וּפָנִים לְגַבֵּי ו'. ו', אָחוֹר לְגַבֵּי ה' עִילָּאָה, וּפָנִים לְגַבֵּי ה' תַּתָּאָה. ה', אָחוֹר לְגַבֵּי ו', וּפָנִים לְגַבֵּי רָזָא דִלְתַתָּא.</p>"],[9514013121,"<p>וּמַאי אִיהוּ ידו\"ד, דְּאִתְקְרֵי אָחוֹר לְגַבֵּי ידו\"ד דִּלְעֵילָא, וְדָא הַמַּבְדִּיל בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקֳּדָשִׁים. ידו\"ד דִּלְעֵילָא, אָדָם עִילָּאָה. ידו\"ד דִלְתַתָּא, אָדָם תִּנְיָינָא. וְאִית אָדָם דְּאִיהוּ תְּלִיתָאָה, דְּאִקְּרֵי אָחוֹר, לְגַבֵּי שְׁמָא תִּנְיָינָא. וּשְׁמָא תִּנְיָינָא אִיהוּ פָּנִים לְגַבֵּי דָּא. וְדָא הוּא הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל. וְאִינוּן תְּלַת, בְּחוּשְׁבַּן אֶהְיֶ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה תְּלַת זִמְנִין.</p>"],[9514013122,"<p>דָּבָר אַחֵר (שמות ט״ז:כ״ה) וַיֹּאמֶר משֶׁה אִכְלוּהוּ הַיּוֹם כִּי שַׁבָּת הַיּוֹם לַה' הַיּוֹם לֹא תִמְצָאוּהוּ בַּשָּׂדֶה. הַאי קְרָא אוֹקְמוּהָ חַבְרַיָא, תְּחוֹת כַּפְתּוֹר עִילָּאָה, כַּפְתּוֹר דִי מְמַנָּא בְּכ\"ב אַתְוָון. בְּעִיזְקָא דִּלְעֵילָא, לָקְטִין תְּרֵין סִטְרִין, חַד עִיזְּקָא. וְהַהוּא עִיזְּקָא אִיהוּ בְּרִיבּוּעָא לְאַרְבַּע סִטְרֵי עָלְמָא.</p>"],[9514013123,"<p>אֲחִיהָן הַאי עִיזְּקָא מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, דָּא לְיָמִינָא, וְדָא לִשְׂמָאלָא. הַהוּא דְּיָמִינָא סָלְקָא בְּרֵישָׁא, וְכַד אִיהוּ זָקְפָא, נָטֵיל עִמֵּיהּ שִׁית מְאָה אֶלֶף גּוּבְרִין גִּבָּרִין, אֲחִידָן סְיָיפִין עַל יְרֵכִין. הֲדָא הוּא דִכְתִיב, (שמות י״ב:ל״ז) כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי הַגְּבָרִים לְבַד מִטָף. וְהַהוּא דִּשְׂמָאלָא סָלְקָא לְבָתַר כֵּן, וְכַד אִיהוּ זָקְפָא, נָטֵיל עִמֵּיהּ שִׁית מְאָה אֶלֶף (\"חילופי גרסאות\") מָארֵי דְגַדְּפִין, אַנְפִּין דְּרַחֲמֵי. וּמִתְחַלְּפִין דְּיָמִינָא בִּשְׂמָאלָא, וְדִשְׂמָאלָא בְּיָמִינָא.</p>"],[9514013124,"<p>זָקְפָאן לְעֵילָא, עַד דְּאַמְטוּ לְחַד כַּהֲנָא, דְּגָלֵי מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא. כַּד מָטוֹ תַּמָּן, נָפֵיק הַהוּא כַּהֲנָא רַבָּא, וְקָא מְבָרֵךְ לְהַהוּא כַּפְתּוֹר. כֵּיוָן דְּקָא מִתְבָּרְכָא מִתַּמָּן, מִגּוֹ עַתִּיקָא סָבָא דְסָבִין סִיבָּתָא דְּכָל סִיבָּתִין, נָפֵיק טַלָּא דִּבְדוֹלָחָא, וְנָגֵיד לְהַהוּא רֹאשׁ דְּכַהֲנָא, וְאִיהוּ אִמְּלֵי לְהַאי כַּפְתּוֹר, כֵּיוָן דְּאִתְמַלְיָיא, אִתְמַלְיָיא בְּשִׁית סִטְרִין, לְשִׁית יוֹמִין דְּשַׁבַּתָּא.</p>"],[9514013125,"<p>כַד נָחִית מִסִּטְרָא דִשְׂמָאלָא, וְאַקְרִישׁ לְהַהוּא בְּדוֹלְחָא, אִתְעֲבֵיד כְּגַוְונָא דִבְדוֹלְחָא דְּאֶבֶן טָבָא. וְכָלְהוֹ אוּכְלוּסִין אִתְּזְנוּ מִנֵּיהּ בְּכָל יוֹמָא, וּמִנְּהוֹן בְּלֵילְיָא. אִינוּן דִּימָמָא אָכְלֵי בְּגַוְונָא חַד, וְאִינוּן דְּלֵילְיָא אָכְלֵי בְּגַוְונָא אָחֳרָא. אִינוּן דְּלֵילְיָא אִקְּרוּן מְתַבְּרֵי טוּרִין וְטִנָּרִין, אִלֵּין לָקְטִין מִפַּלְגוּת דְּלֵילְיָא עַד דְּיִתְתַּקֵּף שִׁמְשָׁא, כֵּיוָן דְּאָתָא שִׁמְשָׁא לָא לָקְטֵי. אִינוּן דִּימָמָא, אִקְרוּן יְלִידֵי בֵּיתָא, טְמִירֵי הֵיכָלָא. לָא לָקְטֵי אֶלָּא בְּצַפְרָא. כֵּיוָן דְּאָתֵי צַפְרָא, לָקְטֵי כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ. אָחֳרָנִין אִית דְּלָקְטֵי לְעִידַן רַמְשָׁא, וְכָל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ.</p>"],[9514013126,"<p>אִינוּן דְּלֵילְיָא, עֲלַיְיהוּ כְּתִיב (שמות ט״ז:י״ג) וּבַבֹּקֶר הָיְתָה שִׁכְבַת הַטָל. אִלֵּין אִינוּן נָזְלֵי טַלָּא דְּמַנָּא לְתַתָּאי, מְחוּלָּקָא דִּילְּהוֹן. הַאי מַנָּא לָא הֲוָה לֵיהּ גַּוָּון, וְלָא אִגְלִיד. אִינוּן דְּצַפְרָא, עֲלַיְיהוּ כְּתִיב (קהלת י״א:ו׳) בַּבֹּקֶר זְרַע אֶת זַרְעֲךָ. אִלֵּין הֲוֵי נָזְלֵי טַלָּא דְּמַנָּא לְתַתָּאי, וְיַהֲבֵי גַוָּון לְהַהוּא מַנָּא, וּמִתְקָא וְדוּבְשָׁא.</p>"],[9514013127,"<p>אִינוּן דְּרַמְשָׁא, עֲלַיְיהוּ כְּתִיב (שמות ט״ז:ו׳) עֶרֶב וִידַעְתֶּם. וְאִינוּן דְּלֵילְיָא, הֲווֹ נָזְלֵי בְּזִמְנָא חָדָא מִסִּטְרָא דְאִלֵּין. מַאן דְּאַשְׁאַר מִנֵּיהּ עַד צַפְרָא, כְּתִיב, (שם) וַיָּרֻם תּוֹלָעִים וַיִּבְאַשׁ.</p>"],[9514013128,"<p>תְּלַת סִטְרִין גְּלִיפִין הָכָא, לָקֳבֵיל תְּלַת, הַיּוֹ\"ם הַיּוֹ\"ם הַיּוֹ\"ם. תְּלַת הֵהִי\"ן, ה' ה' ה', וּלְכָלְהוֹ הֵהִי\"ן, תְּלַת תְּלַת אַתְוָון, וְאִתְעֲבִידוּ תְּרֵין עֲשַׂר, כְּחוּשְׁבַּן תְּרֵי עֲשַׂר שַׁעְתֵּי דִּימָמָא, וְכָלְהוֹ חַד, וְכָלְהוֹ יוֹם. תְּלַת שַׁבַּתֵּי אִינוּן, כָּלְהוֹן יוֹמָא חַד, שַׁבַּתָּא דְּלֵילְיָא, שַׁבַּתָּא דִּימָמָא, שַׁבַּתָּא דְּרַמְשָׁא. לְקִבְלֵהוֹן תְּלַת סְעוּדְתֵי, סְעוּדָתָא דְּלֵילְיָא, סְעוּדָתָא דִּימָמָא, סְעוּדָתָא דְּרַמְשָׁא.</p>"],[9514013129,"<p>סְעוּדָתָא דְלֵילְיָא, עַד לָא אִתְקַדֵּשׁ יוֹמָא, מִתְתַּקְּנֵי אוּכְלוּסִין כָּלְהוֹ תְּלַת קְשִׁירִין, עָאלִין גּוֹ נַהֲרֵי דַּאֲפַרְסְמוֹנָא, אִתְסַחְיָין בִּתְסִירוּ דִּוְורָדֵי גְלִיפָן, מִתְעֲבָרָן גּוֹ נְהַר דִּינוּר, וְסָלְקִין מִתַּמָּן בְּקוֹמֵי. כֵּיוָן דְּסָלְקִין לִסְטַר חִוָּורָא, אִתְסַחְיָין אִינוּן וְורָדִין. סָהֲדוֹ סָהֲדִין דְּשַׁבָּת בְּרֵאשִׁית. כָּלְהוֹן דְּלֵילְיָא קַדִּישִׁין. לִסְטַר חַד לְשִׁית שִׁית סִטְרִין.</p>"],[9514013130,"<p>כַד בָּעָא יוֹמָא לְאִתְקַדְּשָׁא, קָל שׁוֹפָרָא אִתְנְגֵיד מִלְּעֵילָא לְתַתָּא, וְהַהוּא קָלָא חוּלְקָא דְּעַמָּא דְּיִשְׂרָאֵל אִיהוּ. בְּגִין דְּלִית קִדּוּשָׁא בַּר כַּד אִשְׁתְּמַע הַהוּא קָלָא. וּכְדֵין יְדִיעַ דְּאִתְקַּדַּשׁ יוֹמָא.</p>"],[9514013131,"<p>סַנְדַּלְפוֹן נְזִירָא פְּרִישָׁא, אִתְעַטְרָא בְּעִטְרוֹי גְּלִיפִין, רְשִׁימָאן בְּאַתְוָון דְּאִקְּרֵי גִּלְגּוּלָא דְּחַד וּתְרֵין וּתְלַת אַרְבַּע וְחָמֵשׁ וְשִׁית, וְאִינוּן אַתְוָון אי\"ק בכ\"ר גל\"ש דמ\"ת הנ\"ך וכו'.</p>"],[9514013132,"<p>כְדֵין בוְאָמַר לֵיהּ, רַב אַסְוָון דְּאִקְּרֵי רְפָאֵל, (במדבר י״ב:י״ג) אֵל נָא רְפָא נָא, בָּעוּתָא דְּקָאֲמַר מְהֵימְנָא דְּמָארוֹי, וַאֲתַר דָא אַסֵּי לְמִרְיָם. נ\"א נ\"א הוּא בוְאָמַר לֵיהּ, בְּאַתְוָון רְשִׁימָאן דְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוּ\"ד. בֵּי\"ת וָא\"ו אָלֶ\"ף לָמֶ\"ד, דָּא הוּא בוְאָמַר לֵיהּ. הַאי רַב אַסְוָון אַסֵּי לְכָלְהוֹ אוּכְלוּסֵי, וּמַעֲבַר מִנַּיְיהוּ זִיוָא דַּחֲשׁוֹכָא, דְּהֲוָה מְקַרְבָא גַּבַּיְיהוּ שְׁאָר יוֹמֵי.</p>"],[9514013133,"<p>בְּהַהוּא שַׁעֲתָא מִתְעָרֵי תְּרֵין רוּחִין עִילָּאִין, חַד מִסִּטְרָא דְּאוֹר וְחַד מִסִּטְרָא דְחשֶׁךְ. וְאִינוּן מִיכָאֵל גַּבְרִיאֵ\"ל, מִתְגַּלְפָאן לְשִׁתִּין רִבּוֹא אוּכְלוּסִין, דְּשָׁלְטָן בְּהַהוּא לֵילְיָא. וְאִתְעַתְּדָן חַד לְיָמִינָא וְחַד לִשְׂמָאלָא, לְכָל חַד וְחַד פָּתוֹרֵי אִתְתַּקְּנָן. בָּתַר דְּאִתְחַזּוּן כָּל פָּתוֹרֵי דִּלְתַתָּא בְּהֵיכָלָא יְדִיעָא.</p>"],[9514013134,"<p>כָל אוּכְלוּסִין דִּלְעֵילָּא, אִית לוֹן דּוּכְתִּין פְּרִישָׁן בְּהַאי לֵילְיָא. וְכָל חַד רַב וְיַקִּירָא בְּדוּכְתֵּיהּ, עַל כָּל שְׁאָר חֵילוֹי, וְאִינוּן חַיָילִין מְמַנָּן תְּחוֹת יְדוֹי. מֵאִינוּן חֵילוֹי, מִתְפָּרְשָׁן תְּרֵין עִילָּאִין דִּי בְהוֹ, וְנָטְלֵי פָּתוֹרָא חַד מִיָּמִינָא וְחַד מִשְׂמָאלָא, וְכָל פָּתוֹרָא דְּלָא אִתְקְרַב בֵּין תְּרֵין אִלֵּין, לָאו אִיהוּ פָּתוֹרָא דְּשַׁבַּתָּא, וְלָאו אִיהוּ פָּתוֹרָא דְּקַמֵּי מַלְכָּא קַדִּישָׁא.</p>"],[9514013135,"<p>וְכַד אִינוּן אִתְּתָא וּבַעֲלָהּ בְּחֶדְוָוה, כְּדֵין הַהוּא פָּתוֹרָא מִתְעַטְרָא. כַּד אִתְקְרֵיב הַהוּא פָּתוֹרָא, בְּשִׁית נַהֲמֵי דְּהַהוּא מַנָּא בְּהַהוּא סִטְרָא. וְשִׁית נַהֲמֵי דְּהַהוּא מַנָּא בְּהַאי סִטְרָא. דָּא אִיהוּ פָּתוֹרָא דְּמִתְעַטְרָא בְּעִטְרוֹי.</p>"],[9514013136,"<p>אִינוּן תְּרֵין דְּנָטְלִין פָּתוֹרָא, אִצְטְרִיכוּ לְנַטְרָא פָּתוֹרָא, דְּלָא יִתְעָרְבוּ נַהֲמֵי שִׁית דְּהַאי סִטְרָא, וְשִׁית דְּהַאי סִטְרָא. כֵּיוָן דְּהַאי פָּתוֹרָא, אִתְקְרֵיב קַמֵּי הַהוּא רַב וְעִילָּאָה מִינַּיְיהוּ, כְּדֵין נָטֵיל חַד מֵהַאי סִטְרָא, וְחַד מֵהַאי סִטְרָא, וְקָא מְבָרְכָא עֲלַיְיהוּ. כָּל חַד אֲמַר לְאוּכְלְסוֹי, זֶה הַשּׁוּלְחָן אֲשֶׁר לִפְנֵי ה'. הֵכִין זֶ\"ה תְּרֵין עֲשַׂר.</p>"],[9514013137,"<p>עַל כָּל פָּתוֹרָא וּפָתוֹרָא, אִתְמַנָּן תְּלַת סַרְכִין, וְרוּחָא עִילָּאָה עֲלַיְיהוּ, וְהַהוּא רוּחָא חָדֵי בְּהַהוּא חֶדְוָה, וְהוּא אוֹרִיאֵ\"ל. וְעִם כָּל אוּכְלוּסִין דִּילֵיהּ אָזִיל, עַל כָּל אִינוּן פָּתוֹרִין.</p>"],[9514013138,"<p>שִׁתִּין מְמַנָּן, טָעֲמִין טַעֲמָא עַל כָּל חַד וְחַד, וְאוֹמֵר הַמּוֹצִיא, וּמְבָרֵךְ לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וּמַאן דְּטָעֵים בְּתֵיאוֹבְתָּא, הָכֵי אִיתּוֹסַף חֵילָא בְּתֵיאוּבְתָּא עִילָּאָה. הַהוּא רוּחָא דְקָא שָׁלְטָא עֲלַיְיהוּ, שֶׁסָּלְקָא נְהִירוּ בְּחֶדְוָוה.</p>"],[9514013139,"<p>וְתָּא חֲזֵי, כְּדוּגְמָא דְּאִינוּן מַלְאָכִים, דְּאִינוּן שֵׁדִין יְהוּדָאִין, דְּאָכְלִין בְּדוּגְמָא דְּבַר נָשׁ. כָּךְ אִית אָחֳרָנִין עִילָּאָה לְעֵילָא לְעֵילָא, וְאִינוּן אָכְלִין וְשָׁתִין מֵאוֹר דִּשְׁכִינְתָּא דְּאִינוּן נֶהֱנִין. וְדָא הוּא דְּאָמְרוּ, צַדִּיקִים יוֹשְׁבִין וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶן, וְנֶהֱנִין מֵאוֹר הַשְּׁכִינָה. וְדָא הָאֲכִילָה וַדָּאִית.</p>"],[9514013140,"<p>חַד אָת נָהֵיר לְעֵילָא לְעֵילָא, וְאִיהִי אָת י'. הַאי אָת נָהֵיר, וְאַנְהֵיר כָּל אוּכְלוּסִין, וְאִיהִי לָא יְדִיעַ, וְלָא אִתְגַּלְּיָיא. תְּחוֹת הַאי, אִתְנַהֲרָן חָמֵשׁ אַתְוָון, וּפְרִישָׂן עַל כָּלְהוֹ אוּכְלוּסִין, וְאִינוּן אֱלֹהִי\"ם. אִתְגַּלְגְּלָא אָת א', וְשַׁרְיָיא עַל אוּכְלֻסָא חַד. וְכֵן כּוּלָּם.</p>"],[9514013141,"<p>וְתָּא חֲזֵי, בְּיוֹמָא דָא דְּשַׁבַּתָּא, בָּעֵי בַּר נָשׁ לְמֶחֱדֵי בִּימָמָא וּבְלֵילְיָיא, וּבָעֵי לְתַקָּנָא פָּתוֹרָא, וְיַעֲבֵיד חֵידוּ לְעִילָאִין וְתַתָּאִין.</p>"],[9514013142,"<p>וְתָּא חֲזֵי, כַּד אָתֵי בַּר נָשׁ מִבֵּי כְּנִישְׁתָּא, יָהֲכוֹן עִמֵּיהּ מַלְאָכִין קַדִּישִׁין מֵהַאי גִיסָא, וּמַלְאָכִין מֵהַאי גִיסָא, וּשְׁכִינְתָּא עַל כָּלְהוֹן, כְּאִימָּא עַל בְּנִין. וּבְהַאי שַׁעֲתָא, (תהילים צ״א:ז׳) יִפֹּל מִצִּדְּךָ אֶלֶף וּרְבָבָה מִימִינֶךָ וְגו', (שם) רַק בְּעֵינֶיךָ תַבִּיט וְגו', (שם) כִּי אַתָּה ה' מַחְסִי וְגו', (שם) לֹא תְאֻנֶּה אֵלֶיךָ רָעָה וְגו'.</p>"],[9514013143,"<p>כָל דָּא, אִם אִינִישׁ יָעֵיל לְבֵייתֵיהּ בְּחֶדְוָוא, וִיקַבֵּל אוּשְׁפִּיזִין בְּחֶדְוָוא. וְכַד אָתֵי שְׁכִינְתָּא וּמַלְאָכִין, וְיֶחֱזוּ שְׁרַגָּא נָהֲרָא, וּפָתוֹרָא מִתְתַּקְּנָא, וְאִינִישׁ וְאִיתְּתֵיהּ בְּחֶדְוָה, הַאי שַׁעֲתָא שְׁכִינְתָּא אָמְרַת, זֶה שֶׁלִּי הוּא, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר.</p>"],[9514013144,"<p>וְאִם לָאו, שְׁכִינְתָּא אָזְלַת, וּמַלְאָכִין עִמָּהּ, וְיֵיתֵי יֵצֶר הָרָע עִם חֵילֵיהּ, וְאִתְחַבָּרוּ עִמְּהוֹן, וְיֹאמֶר זֶה שֶׁלִּי הוּא, וּמִן חֵיילִין דִּילִי. וּמִיָּד שׁוֹרָה עָלָיו וּמְטַמְאָתּוֹ, וְיִסְתַּלֵּק י\"ה, מִן אִישׁ וְאִשָּׁה, וְיִשְׁתָּאַר אֶשָׁא עִם אֶשָׁא. וּמַאֲכָלוֹ טָמֵא. וְעַל דָּא, (משלי כג) וְאַל תִּתְאָו לְמַטְעַמּוֹתָיו שֶׁל רַע עַיִן. וַדַּאי פָּתוֹרָא דִילֵיהּ הִיא מְלֵאָה קִי\"א צוֹאָ\"ה. וְאֵין צוֹאָה, אֶלָּא יֵצֶר הָרָע, שֶׁהוּא טָמֵא.</p>"],[9514013145,"<p>וְעַל דָּא הַבָּא לִיטָהֵר מְסַיְיעִין אוֹתוֹ. בָּא לִטָמֵא פָּתְחִין לוֹ. וְתָּא חֲזֵי, מַלְאָכִין קַדִּישִׁין, וּמַלְאָכִין מְסָאֲבִין, אָזְלִין עִם בַּר נָשׁ בְּכָל אֲתַר דְּאָזֵיל. אִם בַּר נָשׁ זַכָּאָה הוּא, אִזְדַּוְּוגוּ לֵיהּ מַלְאָכִין קַדִּישִׁין, וְיִנְטְרוּן לֵיהּ בְּכָל אַתְרָא דְּאָזֵיל, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י״א) כִּי מַלְאָכָיו יְצַוֶּה לָךְ לִשְׁמָרְךָ בְּכָל דְּרָכֶיךָ. וְאִם לָאו, יִסְתַּלְּקוּן מִנֵּיהּ מַלְאָכִין קַדִּישִׁין, וְיִשְׁלְטוּן עֲלֵיהּ מַלְאָכִין מְסָאֲבִין, וְאַנְהִיגוּ לֵיהּ לַגֵּיהִנֹּם. וּבְהַאי שַׁעֲתָא, קָרָאתִי וְאֵין עוֹנֶה בִּשְׁעַת דָּחֲקוֹ. וּבְשַׁעֲתָא דְּשַׁלֵּיט עֲלֵיהּ רוּחַ מְסָאֲבָא, אוֹ מַרְעִין, אוֹ שָׁלְטִין עֲלֵיהּ אוּמוֹת הָעוֹלָם, (איכה ג׳:מ״ד) סַכֹּתָה בֶעָנָן לָךְ מֵעֲבוֹר תְּפִלָּה. וְגַם תְּפִלָּתוֹ תּוֹעֵבָה.</p>"],[9514013146,"<p>דָּבָר אַחֵר (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה', (ישעיהו כ״ז:ה׳) אוֹ יַחֲזֵק בְּמָעֻזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִּי. תָּא חֲזֵי, דַּל אִתְקְרֵי, גַּבְרָא דְּלֵית לֵיהּ מִדִּילֵיהּ כְּלוּם, וְלָא שָׁאֵיל פְּרוּטָה מִשּׁוּם גַּבְרָא, וְאִיהוּ נִסְתָּר, דְּלָא גָּלֵי דּוֹחֲקָא דִילֵיהּ לְשׁוּם גַּבְרָא. וּבִשְׁעַת דּוֹחֲקָא דִילֵיהּ, הוּא יַעֲשֶׂה מְרִיבָה כְּלַפֵּי מַעְלָה, וַאֲמַר, יוֹתֵר חַיָּיבָא אֲנָא מִכָּל שְׁאָר גּוּבְרִין דְּעָלְמָא, לְגַבְרָא חַד עוֹתְרָא סַגֵּי, בֵּיתָא דִילֵיהּ מַלְיָיא מִן דַּהֲבָא, מִן כַּסְפָּא, וְלִי אֵין לִי שׁוּם פְּרוּטָה בָּעוֹלָם, וְלָא אִית לִי לֶחֶם לֶאֱכֹל וּבֶגֶד לִלְבּשׁ, עַד דְּיֵחוֹב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְכָל אִינִישׁ דְּיַחֲזֵק בְּמָעֻזּוֹ, וִיהֵיב לֵיהּ צְדָקָה, יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִי.</p>"],[9514013147,"<p>וְתָּא חֲזֵי, כָּל אִינִישׁ דְּאִיהוּ דַּל וְחָב קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, לָא חָשֵׁיב לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא חוֹבָה, בְּגִין דְּלָאו אִיהוּ בְּדַעְתֵּיהּ. וּמְנָא לוֹן, מֵאִיּוֹב, בְּשַׁעֲתָא דַּאֲמַר קוּדְשָׁא בְּרִיךְ הוּא לַשָּׂטָן (איוב א׳:ז׳) מֵאַיִן תָּבֹא כו', (איוב ב׳:ג׳) הֲשַׂמְתָּ לִבְךָ אֶל עַבְדִּי אִיּוֹב. אָמַר לֵיהּ הַשָּׂטָן לְקוּדְשָׁא בְּרִיךְ הוּא, אִית בַּר נָשׁ בְּעָלְמָא, דְּיָהֵיב לֵיהּ מָארֵיהּ כַּסְפָּא וְדַהֲבָא וּמַרְגָּלִיּוֹת וּבָנִים וְכָל טוּבָא דְּעָלְמָא, וִיהֵא בִישׁ.</p>"],[9514013148,"<p>אָמַר לֵיהּ, הִנֵּה כָּל אֲשֶׁר לוֹ בְּיָדְךָ רַק אֵלָיו אַל תִּשְׁלַח יָדְךָ. יָהַב לֵיהּ בִּידוֹי, וְקָטֵיל בְּנוֹי, וְלָא נִשְׁאַר בִּידוֹי כְּלוּם. לְבָתַר הָדַר וַאֲמַר, וְגַע אֶל עַצְמוֹ וְאֶל בְּשָׂרוֹ. עַד דְּקוּדְשָׁא בְּרִיךְ הוּא אֲמַר לֵיהּ, הִנּוֹ בְּיָדְךָ אַךְ אֶת נַפְשׁוֹ שְׁמֹר.</p>"],[9514013149,"<p>בְּהַהִיא שַׁעֲתָא נְפַק אִיּוֹב מִדַּעְתֵּיהּ, וַאֲמַר הָכֵי, (שם י) הֲטוֹב לְךָ כִּי תַעֲשֹׁק. הֲטוֹב זֶה הָעוֹשֶׁק שֶׁתַּעֲשֶׂה לִי. אָבִי וְאִמִּי עָשׂוּ הַגּוּף. וְאַתָּה הִתְחַבַּרְתָּ עִמָּהֶם בְּשׁוּתְּפוּת, וְנָתַתָּ בִּי נֶפֶשׁ וּנְשָׁמָה. הַנֶּפֶשׁ שֶׁהוּא שֶׁלְּךָ, אָמַרְתָּ אַךְ אֶת נַפְשׁוֹ שְׁמוֹר, וְהַגּוּף שֶׁעָשׂוּ לִי אָבִי וְאִמִּי, אָמַרְתָּ עֲשֵׂה בוֹ כָּל מַה שֶּׁתִּרְצֶה, וְכִי הוּא טוֹב זֶה הָעוֹשֶׁק שֶׁתַּעֲשֶׂה לִי.</p>"],[9514013150,"<p>דָּבָר אַחֵר (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל, מַהוּ דָּל. אָדָם שֶׁיָּמוּת בְּלֹא בָנִים. יָצְאָה נִשְׁמָתוֹ מִמֶּנּוּ, בִּשְׁעַת פְּטִירָתוֹ מִן הָעוֹלָם, רְאֵה מַה אָמַר עָלָיו הַפָּסוּק, (משלי י״א:כ״א) יָד לְיָד לֹא יִנָּקֶה רָע. וְאִם נִשְׁאָר לוֹ בֵּן בָּעוֹלָם, אִם יַחֲזִיק בּוֹ א', וִילַמְדֶנוּ תּוֹרָה, יַעֲשֶׂה שָׁלוֹם לִי. וּבְיוֹם רָעָה יְמַלְּטֵהוּ ה'.</p>"],[9514013151,"<p>וְתָּא חֲזֵי, גַּבְרָא חַד אָזֵיל לְבֵי טוּרֵי קַרְדוֹנְיָיא, הוּא וּתְרֵין עִמֵּיהּ, וְחָמָא גּוּמִין בְּקִיעִין דְּאֶשָׁא, וּתְנָנָא נָפֵיק מִן גּוּמִין. וְשָׁמַע גַּבְרָא חַד דַּאֲמַר וַוי וַוי. אֲמַר, וַדַּאי אֲתַר חַד מִן דּוּכְתֵּי דְּגֵיהִנֹּם הָכָא.</p>"],[9514013152,"<p>אַהְמוּךָ וְחָזָא בְּחֶלְמֵיהּ לְאֵינַשׁ חַד, וַחֲדָא גְדִישָׁא מִן קוֹצִין עַל כִּתְפוֹי, וּתְרֵין מְמוּנִּין מִן גֵּיהִנֹּם עָאלִין נוּרָא תְּחוֹת גְּדִישָׁא דְּמִן קוֹצִין, וְאִיתּוֹקַד. וַהֲוָה צָעֵיק. וַהֲווּ אָמְרִין לֵיהּ תְּרֵין מַלְאָכִין קַדִּישִׁין, שְׁלוּחִין מִן הַשּׁוֹפֵט דִּלְעֵילָא דְּדָן לֵיהּ, אַתְּ שָׁבַקְתְּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא וּלְמַלְאָכִין דִּילֵיהּ, דַּהֲווֹ נָטְרִין לָךְ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, וְאַתְּ עָבַדְתְּ רַעֲוָוא דְּקוֹצִין, דְּאִינוּן רְשָׁעִים, דְּאִינוּן מִסִּטְרָא דִּסמאָמַר לֵיהּ וְנָחָשׁ. הַקּוֹצִין יִשְׂרְפוּ אוֹתְךָ.</p>"],[9514013153,"<p>אָמַר לֵיהּ לְהַהוּא חַיָּיבָא דְּגֵיהִנֹּם, מַאן אַנְתְּ. אֲמַר יוּדָאי חַיָּיבָא אֲנָא, וּמְמוּנִּין דְּגֵיהִנֹּם לָא מַדְכְּרִין לִי שְׁמִי. וּתְלַת זִמְנִין דַּיְינִין לִי בְּיוֹמָא, וּתְרֵין בְּלֵילְיָא. אֲמַר לֵיהּ שְׁמָא דְּדוּכְתָּךְ יָדְעֵית. אֲמַר לֵיהּ, גְּלִילָא עִילָּאָה. וְשָׁבַקְתְּ בַּר בְּעָלְמָא.</p>"],[9514013154,"<p>אֲמַר יְנוּקָא שָׁבַקְנָא. וַאֲנָא קַצָּבָא הֲוֵינָא. וּמִן בִּישִׁין סַגִּיאִין דַּעֲבִידְנָא בְּקַדְמִיתָא, הֲווֹ דָּיְינִין לִי מִפִּי, וּמֵרַגְלַי, וּמִיָּדַי. וּמַלְאָךְ שֶׁהוּא מְמוּנֶּה עַל הַקְּבָרוֹת, אוֹמֵר לִי בְּשַׁעֲתָא דְּדָיְינִין לִי, אוֹי לְמִי שֶׁנִּשְׁבַּע לְקַיֵּים אֶת הַתּוֹרָה, וְנִשְׁבַּע עַל שָׁקֶר. וַוי לְקַרְקַפְתָּא דְּלָא מַנְחָא תְּפִלִּין מֵעוֹלָם. וְאוֹי לַיָּדַיִם שֶׁשִּׁמְשׁוּ בְּהַבְלֵי הָעוֹלָם. וְאוֹי לָרַגְלַיִם שֶׁהָיוּ הוֹלְכִים בְּהַבְלֵי הָעוֹלָם.</p>"],[9514013155,"<p>בְּשַׁעֲתָא שֶׁהָיוּ מַלְקִין אוֹתִי מַכּוֹת מַרְדּוּת, אָמַרְתִּי כָּל מַה שֶּׁעָשִׂיתִי. וּבָאָה נִשְׁמָתִי, וְהַמַּלְאָךְ שֶׁהָיָה מְמוּנֶּה עַל נִשְׁמָתִי, וְנָתְנוּ כְּתַב אֶחָד מִכָּל מַה שֶׁעָשִׂיתִי. וְנִשְׁמָתִי עָשְׂתָה עֵדוּת עִם הַמַּלְאָךְ, וְאָמְרוּ (דברים י״ז:ו׳) עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלשָׁה עֵדִים יוּמַת הַמֵּת. וְעַל דָּא (מיכה ז׳:ה׳) מִשֹׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִיךָ. וּמַאן אִיהוּ. דָּא נִשְׁמָתָא, דְּהִיא מְעִידָה עַל בַּר נַשׁ בִּשְׁעַת מִיתָתוֹ.</p>"],[9514013156,"<p>אִיתְעַר מִשִּׁינְתֵיהּ הַהוּא גַבְרָא, אָזֵיל לִגְלִילָא עִילָּאָה, וַאֲמַר לְגַבְרָא חַד, חָזִיתָא לִינוּקָא דְּאִיהוּ בֶּן קַצָּבָא, דְּמִית בִּזְמַן פְּלוֹנִי. אָמַר לֵיהּ יְנוּקָא דָא דְּאַתְּ שְׁאֵיל עֲלֵיהּ, אִיהוּ אָזֵיל בְּבֵי מִטְבָּחַיָא, וְאִיהוּ רָשָׁע כַּאֲבוּהִי, כָּךְ וְכָךְ יְהֵא לֵיהּ, וְלַאֲבוּהָ, וּלְמֵינִיקְתָּא דְּיַנִיקָא לֵיהּ. אָזֵיל לְמִדְרְשָׁא חַד, שָׁמַע לִינוּקָא דְּהֲוָה אֲמַר, (משלי ב) אִם תְּבַקְּשֶׁנָּה כַכָּסֶף וְגו'.</p>"],[9514013157,"<p>אָזַל לְבֵי מִטְבָּחַיָא, וְחָזָא לִינוּקָא דְּהֲוָה מְשַׂחֵק עִם הַנְּעָרִים בְּבֵי מִטְבָּחַיָיא, אָמַר לֵיהּ, בְּרִי, זִיל עִמִּי, וְאָזַל עִמֵּיהּ, וְאַלְבֵּישׁ יָתֵיהּ, וִיהַב לֵיהּ לְרַב חַד דְּהֲוָה אוֹלִיף לֵיהּ אוֹרַיְיתָא, עַד דְּרָבָא רַבְיָא וּקְרָא. וַעֲבַד לֵיהּ, דְּיֵימַר הַפְטֹרָה בְּבֵית הַכְּנֶסֶת, וַעֲבַד לֵיהּ דְּיִתְפַּלֵּל. עַד דְּקָרָא וְשָׁנָה וְאִתְחַכֵּם יוֹתֵר, עַד דְּקָרוּ לֵיהּ רַבִּי.</p>"],[9514013158,"<p>הַהוּא בַּר נָשׁ מִית דְּהוּא אֲבוּהִי דִינוּקָא, דַּהֲווֹ דָּיְינִין לֵיהּ, אָתָא בְּחֶלְמָא לְחָכָם דָּא וַאֲמַר לֵיהּ, רַבִּי, כְּמָה דְּנִחַמְתְּ לִי, יְנַחֵם לָךְ קוּדְשָׁא בְּרִיךְ הוּא. בְּשַׁעֲתָא דַּאֲמַר בְּנִי הַהַפְטֹרָה בַּקָּהָל, אַפְקְעֵי לִי מִן דִּינָא. בְּשַׁעֲתָא דַּעֲבַר לִתְפִלָּה, וַאֲמַר קַדִּישׁ, קָרְעוּ לִי גְּזַר דִּין מִכֹּל וָכֹל. וּבְשַׁעֲתָא דְּאִתְחַכַּם, יַהֲבוּ לִי חוּלָקָא בְּגִנְתָּא דְעֵדֶן, וְדָא הוּא חֵלֶק, דְּאָמְרֵי חֵלֶק לעוֹלָם הַבָּא, חֵלֶק שֶׁיֵּשׁ לְכָל צַדִּיק וְצַדִּיק בִּפְנֵי עַצְמוֹ, וְעָאלוּ לִי עִם הַצַּדִּיקִים בִּישִׁיבָה דִּילְּהוֹן.</p>"],[9514013159,"<p>וּבְשַׁעֲתָא דְּאִתְחַכַּם יוֹתֵר, וּקְרוֹ לֵיהּ רַבִּי, אַעֲטָרוּ לִי בְּכִתְרָא, דְּצַדִּיקַיָּיא אִתְעַטְרִין בֵּיהּ. וְיַהֲבוּ לִי אֲכִילָה וּשְׁתִיָּה, מֵהַהִיא שֶׁנֶּהֱנִין מִזִּיו הַשְּׁכִינָה. וְדָא הוּא דְּאָמְרֵי, צַדִּיקִים יוֹשְׁבִין וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם וְנֶהֱנִין מִזִּיו הַשְּׁכִינָה. וְכָל גַּבְרָא דְּנֶהֱנָה מִזִּיו הַשְּׁכִינָה, כְּאִלּוּ אָכַל וְשָׁתָה. וּבִשְׁבִילְךָ רַבִּי, זָכֵינָא לְכָל הַאי יְקָר. זַכָּאָה חוּלָקָךְ, שֶׁבִּשְׁבִיל דָּא אִית לָךְ חוּלָקָא עִילָּאָה יַתִּיר, בְּעָלְמָא דֵין, וּבְעָלְמָא דְאָתֵי. וְזַכָּאָה אִיהוּ, מַאן דְּזָכֵי דְּיִשְׁבּוֹק בְּרָא בְּעָלְמָא.</p>"],[9514013160,"<p>עִנְיַן י\"ח אֶלֶף עוֹלָמוֹת, רַבִּי שִׁמְעוֹן אוֹמֵר, עַד שֶׁלֹּא בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, הֲוָה הוּא וּשְׁמֵיהּ סָתִים בְּגַוֵּיהּ. סָלֵיק בִּרְעוּתָא לְמִבְרֵי עָלְמָא, כֵּיוָן דְּסָלֵיק בִּרְעוּתָא, אַסְחַר נְקוּדָה דְּסָתִים, וְאַסְחַר תְּחוּמֵיהּ בְּהֵיכָלֵיהּ. וּפָשִׁיט פְּשִׁיטוּ לִתְלַת סִטְרִין וְלָא יַתִּיר.</p>"],[9514013161,"<p>מִגּוֹ דִנְקוּדָה דָא, נָפְקוּ כַּחֲדָא תְּלַת נְקוּדִין, וְאִתְיַישְּׁרוּ תְּרֵין בְּחַד גַּוְונָא, וְחַד לְתַתָּא. וְאִיהִי נְקוּדָה דְּאַפֵּיק אִלֵּין תְּלַת, עָאל וְאִתְטַמַּר בְּאֶמְצָעִיתָא, וְעַד דְּלָא עָאל, סָלֵיק וְאִיגְנִיז.</p>"],[9514013162,"<p>בְּשַׁעֲתָא דִּנְפָקוּ אִלֵּין תְּלַת נְקוּדִין, וְדָלִיגוּ מִגַּוָּוהּ, נְפַק מִגּוֹ סְתִימָא דְּסָתִים, חַד בּוּצִינָא יְדִיעַ וְלָא יְדִיעַ, טָמִיר וְלָא טָמִיר, וּמָדֵיד מִשְׁחָתָא סְתִימָא, מִנְּקוּדָא דָא לִנְקוּדָא דָא. אִתְפַּשְּׁטוּ נְקוּדִין גּוֹ חֵילָא דְּבוּצִינָא, וּמָדֵיד אֶלֶף עָלְמִין סְתִימִין, דְּעַיִן לֹא רָאָתָה, מִן דָּא נְקוּדָה לְדָא נְקוּדָה. וְאִתְאַחִידוּ תְּרֵין נְקוּדִין כַּחֲדָא. וּבֵין נְקוּדָה לִנְקוּדָה, אֶלֶף עָלְמִין. מָדֵיד אֶלֶף מִגּוֹ נְקוּדָה תִּנְיָינָא, עַד נְקוּדָה דִּלְתַתָּא, וְעָבַד מִשְׁחָתָא בִּפְשִׁיטוּ דְּאֶלֶף עָלְמִין אָחֳרָנִין. וְכָלְהוֹ עָלְמִין סְתִימִין.</p>"],[9514013163,"<p>וְאִלֵּין, אִינוּן תְּרֵין אַלְפִין שְׁנִין דְּקָיְימָא אוֹרַיְיתָא, עַד לָא אִבְרֵי עָלְמָא. כְּדֵין עָאל אוֹרַיְיתָא, נְקוּדָה סְתִימָא בְּאֶמְצָעִיתָא, וְאַשְׁלֵים לְהַאי סִטְרָא, וּלְהַאי סִטְרָא. וְאִשְׁתַּכָּחוּ לְהַאי סִטְרָא תְּלַת נְקוּדִין, וּלְהַאי סִטְרָא תְּלַת נְקוּדִין.</p>"],[9514013164,"<p>כֵיוָן דְּאִתְעֲבֵיד דָּא, אִתְפַּשְּׁטוּ נְקוּדִין מֵהַאי נְקוּדָה לְהַאי נְקוּדָה אָחֳרָא, נְהוֹרָא דְּנָהֵיר, וְאִתְלַבֵּשׁ נְקוּדָה דָא בִּנְקוּדָא דָּא. דָּלֵיג מֵהַאי נְקוּדָא אָחֳרָא סְתִימָא, נְקוּדָא אָחֳרָא, וְאִתְלַבַּשׁ דָּא בְּדָא.</p>"],[9514013165,"<p>נְקוּהָה סְתִימָא דִּבְרָא כֹּלָּא, בָּטַשׁ, וּבְגִין דְּקָיְימָא בְּאֶמְצָעִיתָא, אַפֵּיק נְקוּדָה אָחֳרָא, עַמּוּדָא דְּקָיְימָא בְּאֶמְצָעִיתָא בֵּין אִינוּן נְקוּדִין דִּנְפָקוּ, דְּאִינוּן לְבוּשִׁין לְהַנֵּי סְתִימִין.</p>"],[9514013166,"<p>עַד הָכָא תְּרֵין נְקוּדִין סְתִימִין, דְּאִתְפַּשְּׁטוּ וְאִיבְרוּ מִגּוֹ נְקוּדָה סְתִימָא, עָבְדוּ אוּמָּנוּת דָּא, בְּהַהִיא נְקוּדָה סְתִימָא. הַהוּא נְקוּדָה דִּלְתַתָּא, דְּאַסְחַר בֵּין אִינוּן תְּרֵין, אַפֵּיק כִּנְקוּדָא דִּלְעֵילָא, תְּרֵין נְקוּדִין לְתַתָּא. וּמֵאִינוּן נְקוּדִין לְבוּשִׁין דְּקָא אֲמָרָן.</p>"],[9514013167,"<p>וְהַהִיא נְקוּדָה עִיקָּרָא דְּכֹלָּא, אַפֵּיק וְדָלֵיג מִנֵּיהּ נְקוּדָה אָחֳרָא, דְּקָיְימָא בְּאֶמְצָעִיתָא, בֵּין תְּרֵין נְקוּדִין אִלֵּין דִּלְתַתָּא.</p>"],[9514013168,"<p>עַד הָכָא, אִינוּן נְקוּדִין לְבוּשִׁין לִנְקוּדִין עִילָּאִין כִּדְקָא חָזֵי. וְאִינוּן שִׁית נְקוּדִין, דְּנָפְקָא מִגּוֹ תְּלַת נְקוּדִין סְתִימִין, דְּאִינוּן שִׁית בִּנְקוּדָא עִיקָּרָא דְּכֹלָּא, דְּאַשְׁלֵים לְכָל סְטַר.</p>"],[9514013169,"<p>אִלֵּין נְקוּדִין לְבוּשִׁין, דְּאִינוּן שִׁית, כָל חַד אַפֵּיק תְּרֵין, וְאִיהוּ עָאל בְּאֶמְצָעִיתָא, וְאִתְלַבַּשׁ בִּתְרֵין נְקוּדִין אִלֵּין, וְאִתְעֲבִידוּ לְבוּשִׁין לְהַאי נְקוּדָה דִּנְפָקוּ מִתַּמָּן.</p>"],[9514013170,"<p>וְאַף עַל גַּב דַּאֲמָרָן דְּאִינוּן שִׁית, אַרְבַּע נְקוּדִין מִנַּיְיהוּ הֲווֹ, דַּאֲפִיקוּ כָּל חַד וְחַד תְּרֵין נְקוּדִין, לְאִתְכַּסָּאָה וּלְאִתְלַבְּשָׁא בְּהוּ, וְאִתְעֲבִידוּ תְּמַנְיָיא נְקוּדִין, דְּאִינוּן לְבוּשִׁין לְד' נְקוּדִין. לְבוּשִׁין לְאִינוּן עִילָּאִין סְתִימִין. עַד הָכָא נְקוּדִין דְּצִיּוּרָא דְּעָלְמָא עִילָּאָה.</p>"],[9514013171,"<p>כֵיוָן דְּאִצְטַיָּירוּ נְקוּדִין, נְפַק בּוּצִינָא, וְעָבַד מִשְׁחָתָא, וּמָדֵיד אֶלֶף בֵּין נְקוּדָא לִנְקוּדָא. וּבֵין כָּל נְקוּדָא וּנְקוּדָא אִשְׁתַּכָּחוּ, מְדִידוּ וּמִשְׁחָתָא דְּבוּצִינָא. בְּאִלֵּין נְקוּדִין תְּמַנְיָיא אֶלֶף עָלְמִין מִתְפַּשְׁטִין. תְּמַנְיָא נְקוּדִין דְּאִתְאַחֲדָן בְּהוּ אִלֵּין מָשְׁחָתֵי, אִקְרוּן תְּמַנְיָיא אֶלֶף עָלְמִין גְּנִיזִין, אִשְׁתַּכָּחוּ מָשְׁחָתֵי בְּאִתְגַּלְּיָיא, וּנְקוּדֵי דְאִתְכַּסְיָין, שִׁיתְּסַר אֶלֶף עָלְמִין. וּמִן שִׁית נְקוּדִין לְבוּשִׁין אִלֵּין, אִשְׁתַּכָּחוּ תְּרֵין דְּאִינוּן בְּאֶמְצָעִיתָא דִּנְקוּדִין, עַל כָּל חַד אֶלֶף עָלְמִין, אִשְׁתַּכָּחוּ תְּמַנֵּיסַר אֶלֶף עָלְמִין, דְּאָזֵיל בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא. וְכָל עָלְמָא וְעָלְמָא גָּנִיז וְסָתִים מִן דָּא. וְעַל כָּלְהוֹ כְּתִיב (קהלת ה׳:ז׳) כִּי גָּבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבֹהִים עֲלֵיהֶם. וּכְתִיב (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ.</p>"],[9514013172,"<p>רַבִּי שִׁמְעוֹן פְּתַח (משלי ח׳:כ״א) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא. מַאי אֹהֲבַי, דָּא אַבְרָהָם, דְּאִתְּמָר בֵּיהּ (ישעיהו מ״א:ח׳) זֶרַע אַבְרָהָם אֹהֲבִי. אָמַר רִבִּי אֶלְעָזָר, אַבָּא אַבָּא, וְהָא יִשְׁמָעֵאל וּבְנֵי קְטוּרָה מִנֵּיהּ קָא אַתְיָין.</p>"],[9514013173,"<p>בְּהַהוּא שַׁעֲתָא תָּמַהּ רַבִּי שִׁמְעוֹן, אַדְּהָכֵי אָתָא אֵלִיָּהוּ. אָמַר לֵיהּ, בּוּצִינָא קַדִּישָׁא שְׁרַגָּא עִילָּאָה, שַׁפִּיר קָאֲמַר ר' אֶלְעָזָר, דְּלֵית אֹהֲבִי אֶלָּא זַרְעָא דְיַעֲקֹב. דִּכְתִיב (מלאכי א׳:ב׳) וָאֹהַב אֶת יַעֲקֹב. בָּדַח ר' שִׁמְעוֹן וּנְשָׁקֵיהּ לְר' אֶלְעָזָר עַל רֵישֵׁיהּ, אָמַר לֵיהּ, בְּנִי, (משלי כ״ג:ט״ו) אִם חָכָם לִבְּךָ יִשְׂמַח לִבִּי גַּם אָנִי. קוּם בְּרִי וְיִתְגְּלֵי רָזָא דְהַאי קְרָא, אִזְדַּעֲזַע, וְקָם עַל רַגְלוֹי.</p>"],[9514013174,"<p>אָמַר רִבִּי שִׁמְעוֹן, לְהַנְחִיל אֹהֲבַי יֵ\"שׁ, מַאי יֵשׁ, דָּא רָזָא דְיוֹבֵל וּשְׁמִטָה, דְּלָא מְסַר יַתְהוֹן קוּדְשָׁא בְּרִיךְ הוּא לִשְׁאָר עַמִין, אֶלָּא לְעַמָּא קַדִּישָׁא. וּבְשַׁעֲתָא דְיִשְׂרָאֵל נָטְרִין שַׁתָּא דִּשְׁמִטָה כִּדְקָא יָאוֹת, נִשְׁמַתְהוֹן דְּצַדִּיקַיָּא מִשְׁתַּעְשְׁעָן בְּגִנְתָּא דְּעֵדֶן, וְאִתְהַדָּרוּ חַדְתִּין. וַעֲלַיְיהוּ אִתְּמָר, (ישעיהו מ׳:ל״א) וְקוֵֹי ה' יַחֲלִיפוּ כֹּחַ.</p>"],[9514013175,"<p>וְתוּ, כָּלְהוֹ נִשְׁמָתִין קוּדְשָׁא בְּרִיךְ הוּא טָבִיל לוֹן בְּנַהֲרָא דְּחַמְשִׁין, דִּבְגִנְתָּא דְעֵדֶן דִּלְעֵילָא, וְאִתְקְרֵי נְהַר דִּינוּר.</p>"],[9514013176,"<p>וּבְרָזָא דִשְׁמִטָה וְיוֹבֵל, קַבֵּל קוּדְשָׁא בְּרִיךְ הוּא צְלוֹתָא, דְּשָׂרָה רִבְקָה רָחֵל וְלֵאָה וְזִלְפָּה וּבִלְהָה. דְּהָא כּוּלְהוֹ אִתְרְשִׁימוּ בְּהֵ\"א הֵ\"א, דְּהִיא שְׁמִטָה וְיוֹבֵל.</p>"],[9514013177,"<p>וּבְגִין דְּחָזַת רָחֵל דְּאִתְרְמִיז שְׁמִטָה וְיוֹבֵל בִּשְׁמָא דְלֵאָה, וְהִיא לֵית לָהּ רְשִׁימוּ דְּהֵ\"א, מִיָּד אָמְרָה הִנֵּה אֲמָתִי בִּלְהָה דְּאִית בָּהּ תְּרֵי. סוֹפֵיהּ דְּיוֹבֵ\"ל, בְּרֵישָׁא דִּשְׁמָא דְלֵאָה, וּבְסֵיפָא דִּשְׁמָא דְּרָחֵל.</p>"],[9514013178,"<p>וְכִי בְּכָל עֵת יָכֵיל בַּר נָשׁ לְמֶעְבַּד צְדָקָה, אִי הָכִי תְּרֵיסַר שַׁעֲתֵי בִּימָמָא מַאן יָכֵיל. אֶלָּא הָכֵי אוֹלִיפְנָא, מַאן דְּעָבִיד צְדָקָה, בְּכָל עֵת עָבִיד. מַאי בְּכָל עֵת, כְּמָה דְאַתְּ אָמֵר (ויקרא ט״ז:ב׳) וְאַל יָבֹא בְּכָל עֵת אֶל הַקֹּדֶשׁ, וְאוֹקְמוּהָ.</p>"],[9514013179,"<p>וְלָא תֵימָא בִּכְנֶסֶת יִשְׂרָאֵל בִּלְחוֹדוֹי, דְּאִיהִי עֵת רַעֲוָוא קַדִּישָׁא דְּצַדִּיק, אֶלָּא אֲפִילּוּ בְּכָל עֵת דִּלְתַתָּא, אַסְגֵי צְדָקָה עֲלַיְיהוּ, וְאִתְעַר צְדָקָה בְּכוּלְהוֹ בְּעִילָּאֵי וּבְתַתָּאֵי. וּבְגִין כָּךְ יְשַׁוֵּי בַּר נָשׁ לִבֵּיהּ וּרְעוּתֵיהּ, וְיִדְבַּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514013180,"<p>כֵיוָן דְמָטוֹ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, סָחוּ לֵיהּ עוֹבָדָא. אֲמַר, וּמַה דָּא בִּלְחוֹדוֹי, אֶלָּא כָּל מַאן דְּאָחֵיד בְּאִילָנָא דְחַיֵּי, יִשְׁתֵּיזֵיב בְּהַאי עָלְמָא, וַאֲפִילּוּ מִן מוֹתָא דְּעָלְמָא מִשְׁאָר בְּנֵי נְשָׁא, כָּל שֶׁכֵּן מִמּוֹתָא אָחֳרָא.</p>"],[9514013181,"<p>אָמַר רַבִּי שִׁמְעוֹן, בְּכוּלְהוֹ אִיתְעַר צְדָקָה אִילָנָא דְחַיֵּי. וְהַאי אִיהוּ אֲתַר דִּמְזוֹנָא לְכוּלֵי עָלְמָא. תַּלְמִידֵי חֲכָמִים מַאי עֲבִידְתַּיְיהוּ, דְּהָא אִינוּן בִּצְדָקָה אֲחִידָן, וְכָל בְּנֵי עָלְמָא בִּזְכוּתַיְיהוּ נִיזּוֹנִין בְּהוּ מַמָּשׁ, וְאִינוּן לָא יָכְלִין לְאִתְּזָן בְּהוּ מַמָּשׁ. בְּגִין דְּאִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וּמַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִשְׁתַּדַּל בְּאִילָנָא דְחַיֵּי דְּכָל בְּנֵי עָלְמָא נִזּוֹנִין מִנֵּיהּ. אִשְׁתְּכַח דְּתַּלְמִידֵי חֲכָמִים מִתְעָרֵי מְזוֹנֵי לְעָלְמָא וּשְׁלָמָא. אִי לְכָל בְּנֵי עָלְמָא מִתְעָרֵי מְזוֹנָא, לוֹן אַמַּאי לָא מִתְעָרֵי.</p>"],[9514013182,"<p>אֶלָּא, תַּלְמִיד חָכָם הוּא אִילָנָא דְחַיֵּי מַמָּשׁ, וְאִילָנָא דְחַיֵּי לָא מִתְּזַן, אֶלָא מִן הָעוֹלָם הַבָּא, וְהָעוֹלָם הַבָּא לָא אִשְׁתַּכַּח בְּהַאי עָלְמָא. אֶלָּא בָּתַר דְּעָאל לְהַהוּא עָלְמָא, כְּדֵין אִתְּזָן בֵּיהּ, וְאִתְנַטְעָן שָׁרְשׁוֹי עֲלֵיהּ.</p>"],[9514013183,"<p>הַשְׁתָּא אָכְלֵי מֵאִיבָּא דְּאִילָנָא דְחַיֵּי. וּמַאן אִיהוּ, הַהוּא אֲתַר דְּאִשְׁתַּכַּח לְגַבֵּי מִסְכֵּינָא, וְאִיהוּ אִקְרֵי פְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן. וְעַל דָּא אָכְלֵי מֵהַהוּא פְּרִי בְּהַאי עָלְמָא.</p>"],[9514013184,"<p>וְעַל דָּא תָּנִינָן, הֵם נִיזּוֹנִין בִּזְרוֹעַ. מַאי זְרוֹעַ. גְּבוּרָה. וְאִינוּן זְמִינִין לָעוֹלָם הַבָּא. דִּמְזוֹנָא דְּעוֹלָם הַבָּא לָאו אִיהִי בְּהַאי עָלְמָא, אֶלָּא צִמְצוּמָא זְעֵירָא, דְּחִילָא דִילֵיהּ אִשְׁתַּכַּח בִּמְתִיקוּ דְאוֹרַיְיתָא. וְדָא טַעֲמֵי עַל הַהוּא אִיבָּא דְאִילָנָא תַּתָּאָה, וְדָא הוּא חֶדְוָותָא וּמְזוֹנָא דִילְּהוֹן.</p>"],[9514013185,"<p>כֵיוָן דְּעָבְרִין מֵהַאי עָלְמָא, כַּמָּה נַחֲלִין עִילָּאִין דְּעה\"ב, סָחֲרִין לְדוּכְתַּיְיהוּ, וְיִשְׁתַּרְשׁוּן בֵּיהּ, וְיִסְתַּלְּקוּן לְעֵילָא, כְּדֵין (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. מַאן יַעֲשֶׂה. דָּא יוֹבְלָא, הַהוּא דְּאִקְרֵי הָעוֹלָם הַבָּא. לִמְחַכֵּה לוֹ, וַדַּאי דְּלָא בָּעְיָין מְזוֹנָא בְּעָלְמָא דָא, עַד דְּאַתְקִינוּ לִמְזוֹנָא דִּילְּהוֹן וְהַאי מְזוֹנָא דִּילְּהוֹן בָּעוֹלָם הַבָּא. וְעַל דָּא זַכָּאִין אִינוּן בְּכוֹלָּא, דַּעֲלַיְיהוּ כְּתִיב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9514013186,"<p>תָּא חֲזֵי, כֵּיוָן דִּבְנֵי נְשָׁא אִשְׁתְּלִימוּ שַׁיְיפוֹי, בְּהַהוּא זִימְנָא אִתְתַּקַּן כָּל שַׁיְיפָא כִּדְקָא יָאוֹת. כְּגַוְונָא דָא, כֵּיוָן דִּשְׁכִינְתָּא אַקְדִימַת לְבֵי כְּנִישְׁתָּא, בָּעְיָין עֲשָׂרָה דְּיִשְׁתַּכְּחוּן תַּמָּן כַּחֲדָא, וְיִשְׁתְּלֵים מַה דְּיִשְׁתְּלֵים, לְבָתַר דְּיִתְתַּקַּן כֹּלָּא. וּבַמֶּה הוּא תִּיקּוּנָא דְּכֹלָּא, כְּמָה דְאַתְּ אָמֵר, (משלי י״ד:כ״ח) בְּרָב עָם הַדְרַת מֶלֶךְ, וְעַל דָּא עַמָּא דְאַתְיָא לְבָתַר כֵּן, כָּלְהוֹ תִּיקּוּנָא דְּגוּפָא.</p>"],[9514013187,"<p>וְכַד אָתַת וְאַקְדִּימַת שְׁכִינְתָּא, וּבְנֵי נְשָׁא לָא אַתְיָין כַּחֲדָא כִּדְקָא יָאוֹת, קוּדְשָׁא בְּרִיךְ הוּא קָארֵי, (ישעיהו נ׳:ב׳) מַדּוּעַ בָּאתִי וְאֵין אִישׁ. מַאי וְאֵין אִישׁ. דְּלָא מִתְתַּקְּנֵי שַׁיְיפֵי, וְלָא אִשְׁתְּלֵים, אֵין אִישׁ וַדַּאי, וּבְגִין דָּא וְאֵין אִישׁ דַּיְיקָא.</p>"],[9514013188,"<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּגוּפָּא אִשְׁתְּלֵים לְתַתָּא, קְדוּשָּׁה עִילָּאָה אַתְיָא, וְעָאל בְּהַאי גוּפָא, וְאִתְעֲבֵיד תַּתָּאָה כְּגַוְונָא דִּלְעֵילָא מַמָּשׁ. וּכְדֵין כָּלְהוֹ בָּעְיָין דְּלָא יִפְתְּחוּן פּוּמָּא בְּמִילֵי דְעָלְמָא, בְּגִין דְּהָא קָיְימֵי יִשְׂרָאֵל בִּשְׁלִימוּ עִילָּאָה, וּמִתְקַדְּשֵׁי בִּקְדוּשָּׁה עִילָּאָה. זַכָּאָה חוּלָקֵיהוֹן.</p>"],[9514013189,"<p>(במדבר ו׳:כ״ג) וַיְדַבֵּר ה' כו', כֹּה תְבָרַכוּ. תָּא חֲזֵי, כֵּיוָן דִּשְׁלִיחַ צִבּוּר סִיֵּים צְלוֹתֵיהּ, וְאָתָא לְבָרְכָא בִּרְכְתָא דְּכַהֲנֵי, אִצְטְרִיךְ וַדַּאי לְכַוְּונָא בִּרְעוּתָא דְלִבָּא, לְבָרְכָא לֵיהּ לְעַמָּא קַדִּישָׁא. דִּי בְּעוֹבָדָא וּבְמִילּוּלָא, קָשִׁיר קִשּׁוּרָא דְּיִיחוּדָא. וְיִשְׁתַּכַּח דְּעַל יָדֵיהּ מִתְבָּרְכִין עִילָאִין וְתַתָּאִין.</p>"],[9514013190,"<p>וּכְדֵין בָּעֵי לֵיהּ שְׁלִיחַ צִבּוּר לְמֵימַר, יְבָרֶכְךָ ה' כְּלַפֵּי הַהֵיכָל. וְיִשְׁמְרֶךָ, לְאִסְתַּכָּלָא לְסִטְרָא דְיָמִינָא דִּילֵיהּ, לְאַמְשָׁכָא חוּטָא דְחֶסֶד עַל עַמָּא קַדִּישָׁא בְּקַדְמִיתָא. וּלְבָתַר יֹאמַר יָאֵר ה', כְּלַפֵּי הַהֵיכָל. פָּנָיו אֵלֶיךָ וִיחֻנֶךָֹּ, וְיִסְתַּכֵּל לְסִטְרָא דִשְׂמָאלָא דִּילֵיהּ, לְיַיחֲדָא בְּיָמִינָא. בְּגִין דִּמְקוֹרָא דְּבִרְכְתָא מִסִּטְרָא דְיָמִינָא הוּא. וּכְדֵין כָּל סִטְרָא דִשְׂמָאלָא אִסְתַּלַּק, וְלָא הַוְיָיא נִזְקָא כְּלָל. וּכְדֵין, יִשָּׂא ה' פָּנָיו אֵלֶיךָ וְיָשֵׂם לְךָ שָׁלוֹם, וְדָא הוּא צְלוֹתָא שְׁלִים.</p>"],[9514013191,"<p>וַוי לֵיהּ, לְמַאן דְּאָתָא לִמְפַתֵּי לְמָארֵיהּ, בְּלִבָּא רְחִיקָא, וְלָא בִּרְעוּתָא שְׁלֵימָתָא, כְּמָה דְאַתְּ אָמֵר, (תהילים ע״ח:ל״ו-ל״ז) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוּ לוֹ וְלִבָּם לֹא נָכוֹן עִמּוֹ. וְדָא הוּא שְׁלִיחָא דְצִיבּוּרָא, דְּיִסְתַּכֵּל בְּקַדְמִיתָא בְּסִטְרָא דִשְׂמָאלָא דִּילֵיהּ, בְּגִין דְּיִתְעוֹרֵר סִטְרָא דְדִינָא בְּקַדְמִיתָא, וְעַל יְדֵיהּ הֲוֵי פֵּירוּדָא, וְלָא קִישּׁוּרָא.</p>"],[9514013192,"<p>דְּיִחוּהָא דִצְלוֹתָא וּבִרְכְתָא, תַּלְיָיא בְּדִיבּוּרָא וּבְמִילּוּלָא דְפוּמָא, וְכוֹלָא תַּלְיָיא בְּעִיקָּרָא דְעוֹבָדָא. וּמַאן דְּלָא יְדַע עִיקְּרָא דְּעוֹבָדָא, לָאו עֲבִידְתֵּיהּ עֲבוֹדָה. וְאִי פָּגֵים עוֹבָדָא מִילּוּלָא, לָא אַשְׁכַּח אֲתַר לְשַׁרְיָיא בֵיהּ בִּרְכְתָא. וְלָאו אִיהוּ צְלוֹתֵיהּ צְלוֹתָא. וְאִתְפְּגֵים הַהוּא בַּר נָשׁ לְעֵילָא וְתַתָּא. וַוי לְהַהוּא בַּר נָשׁ דְּפָגֵים צְלוֹתֵיהּ פּוּלְחָנָא דְמָארֵיהּ. עֲלֵיהּ כְּתִיב, (ישעיהו א׳:י״ב-י״ג) כִּי תָבֹאוּ לֵרָאוֹת כו', רְמֹס חֲצֵרָי לֹא תוֹסִיפוּ הָבִיא וְגו' לֹא אוּכַל אָוֶן וַעֲצָרָה.</p>"],[9514013193,"<p>(במדבר כא) וַיִּסְעוּ מֵהֹר הָהָר דֶּרֶךְ יַם סוּף. הָא אִתְעָרוּ חַבְרַיָיא, דִּנְטָלוֹ מִלְּאוֹלָפָא תַּלְמוּדָא, דְּאִקְרֵי הֹר הָהָר. אַמַּאי אִקְרֵי הֹר הָהָר, בְּגִין דִּמְתַמָּן נָפֵיק הוֹרָאָה לְעָלְמָא. דִּכְתִיב (שמות כד) אֲשֶׁר כָּתַבְתִּי לְהוֹרֹתָ\"ם, וְדָא אִיהוּ תּוֹרָה שֶׁבְּעַל פֶּה.</p>"],[9514013194,"<p>אֲבָל תָּא חֲזֵי, רָזָא דְחָכְמְתָא אִית הָכָא. הַאי אַתְרָא דְּאִיקְּרֵי הֹר הָהָר, אוֹרְחָא הוּא לְיַמָּא דְסוּף, סוֹפָא דְדַרְגִּין, דַּהֲוַת מֵדַבְּרָא קֳדָמֵיהוֹן בְּמַדְבְּרָא, וּמְאַלְפָא לְהוֹן אוֹרְחִין דְּחַיִּין, בְּגִין דְּאִיהִי אוֹרְחָא, לְמֵיעַל לְעָלְמָא דְאָתֵי.</p>"],[9514013195,"<p>וְאִינוּן נְטָלוּ מִבַּתְרָהּ וּמֵאוֹרְחָהּ, וְאָזְלִין בָּתַר אֹרַח חִוְיָא עֲקִימָא, דְּשַׁלִּיט בְּאֶרֶץ אֱדוֹם, כְּדֵין (במדבר כא) וַתִּקְצַר נֶפֶשׁ הָעָם בַּדָּרֶךְ, בְּגִין דְּטָעוֹ מֵאָרְחָא דְחַיֵּי. כְּדֵין, וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמשֶׁה. בְּכֹלָא אִיתְרַעֲמוּ, בְּתוֹרָה שֶׁבְּעַל פֶּה, וּבְתוֹרָה שֶׁבִּכְתָב. כִּי אֵין לֶחֶם, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. וְאֵין מַיִם, דָּא תּוֹרָה שֶׁבִּכְתָב, וְהוּא לֶחֶם הַקְּלֹקֵל, דִּקְלִילָא הֲוָה בְּעֵינֵיהוֹן מִלְּתָא דְאוֹרַיְיתָא דִּבְעַל פֶּה.</p>"],[9514013196,"<p>תָּא חֲזֵי, אַהֲרֹן יְמִינָא דְמַלְכָּא, אִסְתַּלַּק, וְאִסְתַּלְּקָן ז' עֲנָנִים מִנְהוֹן, כְּדֵין אִתְחֲזָרוֹ לְבַתְרֵיהוֹן שֶׁבַע דַּרְגִּין. כַּד נְטָלֵי מֵהַאי בֵּירָא דְּמַיִּין נָבְעִין, דְּהֲוָה מְנַסְכָא עֲלַיְיהוּ לְקַבָּלָא עוֹל מַלְכוּתָא דִשְׁמַיָא. דְּהָא בְּקַדְמִיתָא הֲווֹ סָלְקִין בְּאִינוּן דַּרְגִּין מִתַּתָּא לְעֵילָא. לְבָתַר, אִתְחֲזָרוֹ לַאֲחוֹרֵיהוֹן, וְאִתְדַּבְּקֵי בְּחִוְּיָא עֲקִימָא, דְּשָׁאט בְּיַמָּא, דְּהָא נְפָקוּ מֵרְשׁוּתָא עִילָאָה, בְּאִינוּן ז' דַּרְגִּין דְּחָבוּ בְּהוֹן, וְאִסְתַּלָּקוּ מִנְּהוֹן. כְּדֵין הֲוָה לֵיהּ רְשׁוּתָא לְחִוְּיָא תַּתָּאָה לְשָׁלְטָא בְהוֹ, וְאִיהוּ, (שם יג) עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. אִי לָאו דְּאַהַדְּרוּ בִּתְיוּבְתָּא, וְאִתְדַּבָּקוּ בְּקוֹל יַעֲקֹב, וּכְדֵין שְׁלִיטוּ בְּהַהוּא חִוְּיָא וְאִתְמְסַר בִּידַיְיהוּ.</p>"],[9514013197,"<p>וּלְבָתַר אִתְהַדְּרוּ לְסוּרְחָנַיְיהוּ, וְחָבוֹ בְאַתְרָא דְּתוֹרָה וּמִצְוֹת, וְאִתְהַדְרוּ לְאָחוֹר שֶׁבַע דַּרְגִּין. כְּדֵין אִיתְעַר חִוְיָא עִילָאָה לְשַׁלְטָאָה עֲלַיְיהוּ, דִּכְתִיב, (שם כא) וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים. מַאי שְׂרָפִים. כְּמָה דְאַתְּ אָמֵר (ישעיה ו) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ. תְּרֵי הֲווֹ, חַד אִתְחֲזָרוּ, תַּנִּינָם כְּתִיב חָסֵר.</p>"],[9514013198,"<p>וְכַמָּה נְחָשִׁים נְפָקוּ מֵהַהוּא חִוְּיָא עִילָאָה, וְאִזְדַּוְּוגוּ בְּהוּ. כְּדֵין אַהֲדָרוּ בִּתְיוּבְתָּא שְׁלֵימָתָא, וְאִתְדַּבָּקוּ בְּסִטְרָא דְרַחֲמֵי, לְנַחֲתָא רַחֲמֵי, לְבַסְמָא עָלְמָא, וְאִתְעַדֵּי חִוְּיָא, וְאִתְבַּסְּמוּ כָּלְהוֹ עָלְמִין.</p>"],[9514013199,"<p>תָּא חֲזֵי, כַּד חָבוֹ, כְּתִיב, וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמשֶׁה. כַּד אַהֲדָרוּ בִּתְיוּבְתָּא כְּתִיב (במדבר כא) כִּי דִּבַּרְנוּ בַּה' וָבָךְ. אֶלָּא בָּעוֹ לְאַהֲדָרָא מַיָּא מִמָּקוֹרָא עִילָאָה לְאַתְרַיְיהוּ, מִתּוֹרָה שֶׁבִּכְתַב לְתוֹרָה שֶׁבְּעַל פֶּה, וְאִתְדַּבָּקוֹ בְּאַתְרָא עִילָאָה, דְּבֵיהּ תַּלְיָיא כּוֹלָא לְבַסְמָא אַתְרָא, וּלְאִנְגְּדָא מַיִין עִילָאִין לְאַתְרָא דְשַׁרְיָיא עֲלַיְיהוּ, בְּגִין כָּךְ כִּי דִבַּרְנוּ בַּה' וָבָךְ.</p>"],[9514013200,"<p>תָּא חֲזֵי, כַּד בַּר נָשׁ חָב בְּאַתְרָא דְדִינָא, כְּאִלּוּ חָב בְּאַתְרָא דְּדִינָא עִילָאָה. כָּל שֶׁכֵּן הָכָא, דִּבְכוֹלָא חָבוּ, בֵּאלֹהִים וּבְמשֶׁה. וּמַאי טַעְמָא אָתָא עֲלַיְיהוּ נָחָשׁ. בְּגִין דְּאִינוּן נְחִישׁוּ, וַאֲמָרוּ, אִי לָא יֵיתֵי עֲלַיְיהוּ דִינָא, לֵית לוֹן לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וְאִי אָתֵי נִשְׁתַּדֵּל בָּהּ.</p>"],[9514013201,"<p>עֲשֵׂה לְךָ שָׂרָף, כְּמָה דְאַתְּ אָמֵר (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים. בְּגִין דְּכֵיוָן דְּתָבוּ בִּתְיוּבְתָּא עִילָאָה, הָא אִינוּן בְּהֵיכָלִי, כִּשְׂרָפִים עִילָאִין דִּמְשַׁמְּשִׁים קֳדָמַי. וְשִׂים אוֹתוֹ עַל נֵס, לְאַגְבָּהָא לוֹן לְעֵילָא, דְּיָנְקָא לוֹן אֲתַר דְּמַדְבְּחָא עִילָאָה בְּגַדְפָהָא לְשֵׁזָבוּתְהוֹן מֵחִוְּיָא. כְּמָה דְאַתְּ אָמֵר, (שמות י״ז:ט״ו) וַיִּקְרָא שְׁמוֹ ה' נִסִּי, וְעַל דָּא וְשִׂים אוֹתוֹ עַל נֵס וַדַּאי.</p>"],[9514013202,"<p>תָּא חֲזֵי, (בראשית כ״ב:א׳) וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם, דְּאָרֵים דִּגְלֵיהּ עַל כֹּלָא. אוּף הָכָא אָרֵים דִּגְלָא דִּילְּהוֹן עַל כּוֹלָא. וּמַאי טַעְמָא עָבְדֵיהּ מִנְּחשֶׁת. בְּגִין דִּנְחשֶׁת בְּאַתְרָא דְּחַיִּים תַּלְיָיא, אַתְרָא דְיַעֲקֹב שְׁרֵי תַּמָּן, בְּגִין כָּךְ וָחָי, וָחָי וַדַּאי.</p>"],[9514013203,"<p>וְתָּא חֲזֵי, כַּמָּה הִיא עִילָאָה חֵילָא דִתְיוּבְתָּא עַל כֹּלָא. בְּגִין דְּכַד בַּר נָשׁ תָּב קַמֵּי מָארֵיהּ, כְּדֵין בְּאֵר מַיִם חַיִּים אִתְמְלֵי, וְנָפְקִין מַבּוּעוֹי לְכָל סִטְרִין, וּלְכָל שִׁבְטָא וְשִׁבְטָא נָגֵיד לֵיהּ בִּתְרֵי עֲשַׂר תַּרְעֵי, לְאַשְׁקָאָה חֵיוָן זְעִירָן עִם רַבְרְבָן.</p>"],[9514013204,"<p>יִשְׂרָאֵל כַּד תָּבוּ בִּתְיוּבְתָּא, כְּדֵין אָמְרֵי שִׁירָתָא. וְאִינוּן שֶׁבַע דַּרְגִּין דְּתָבוּ מִבַּתְרֵיהוֹן, אַהֲדָרוּ לוֹן בְּשִׁירָתָא דִילְּהוֹן, וּסְלִיקוּ בֵּירָא עִילָאָה לְעֵילָא, דְּאִתְפְּרַשׁ חִוְּיָא מֵעָלְמָא. הֲדָא הוּא דִכְתִיב, (במדבר כ״א:י״ז) אָז יָשִׁיר יִשְׂרָאֵל וְגו', עֲלִי בְּאֵר עֱנוּ לָהּ, דְּסָלְקָא לְעֵילָא לְעֵילָא, וְאִתְחַבְּרָא אִימָא תַּתָּאָה בְּעִילָאָה.</p>"],[9514013205,"<p>הֲדָא הוּא דִכְתִיב, (שם) בְּאֵר חֲפָרוּהָ שָׂרִים, דָּא אַבָּא וְאִמָא, דְּאוֹלִידוּ לָהּ. כָּרוּהָ נְדִיבֵי הָעָם, אִלֵּין אֲבָהָן. מַאי כָּרוּהָ, כְּמָה דְאַתְּ אָמֵר (הושע ג׳:ב׳) וָאֶכְּרֶהָ לִּי בַּחֲמִשָּׁה עָשָׂר כָּסֶף. אִלֵּין אֲבָהָן. וְזַרְעָא דְיִשְׂרָאֵל דְּאִתְחַבָּרוּ בָּהּ, בְּט\"ו בְּנִיסָן, וְאִתְעָרָא יַד רָמָּה דְּאִקְּרֵי כָּסֶף, יְמִינָא דְמַלְכָּא עֲלַיְיהוּ.</p>"],[9514013206,"<p>בִּמְחוֹקֵק בְּמִשְׁעֲנוֹתָם, עַל יְדָא דְמשֶׁה, דְּאִיהוּ מְחוֹקֵק, אִתְחַבְּרָא בִּתְרֵי עֲשַׂר שִׁבְטִין, דְּאִינוּן בְּנִין דִּילָהּ דְּשָׁרָאן סַחְרָנָהָא. מַאי בְּמִשְׁעֲנוֹתָם, תָּא חֲזֵי, כַּד יִשְׂרָאֵל מִשְׁתַּדְּלִין בְּאוֹרַיְיתָא, דְּאִתְיְיהִיבָא עַל יְדָא דִמְחוֹקֵק, כְּדֵין סָמְכִין לָהּ לִשְׁכִינְתָּא אִינוּן תְּרֵיסַר סָמְכִין דִּלְעֵילָא, וְעַל דָּא בְּמִשְׁעֲנוֹתָם, דְּאִיהִי נִשְׁעֶנֶת עֲלַיְיהוּ.</p>"],[9514013207,"<p>וְתָּא חֲזֵי, תְּרֵיסַר תַּרְעִין אִית לָהּ לְהַאי בֵּירָא קַדִּישָׁא, קַרְתָּא קַדִּישָׁא, דְּאִקְּרֵי יְרוּשָׁלַיִם. וּמִן אִינוּן תַּרְעִין נָפְקִין לְעָלְמָא תְּרֵיסַר מַתְּנָן עִילָאִין: טוֹבָה. וְשִׂמְחָה. בְּרָכָה. וְשָׁלוֹם. עֶזְרָה. כַּפָּרָה. תּוֹרָה. חָכְמָה. וְחַיִּים. וְרָצוֹן. וְעוֹשֶׁר. וְכָבוֹד. וְכָל שִׁבְטָא וְשִׁבְטָא, יַנִּיקוּ מַתָּנָה עִילָאָה לֵיהּ.</p>"],[9514013208,"<p>הֲדָא הוּא דִכְתִיב, וּמִמִּדְבָּר מַתָּנָה. מַאי מִדְבָּר. כְּמָה דְאַתְּ אָמֵר, (שה\"ש ד) וּמִדְבָּרֵךְ נָאוֶה. מֵהַהוּא מִדְבָּר אַתְיָין לוֹן מַתָּנָה עִילָאָה. בְּהַאי זִמְנָא כַּד אִינוּן לָא מִתְפָּרְשָׁאן מִלְּאַסְמָכָא לָהּ.</p>"],[9514013209,"<p>וְעַל דָּא אִתְעָרוּ חַבְרַיָיא, דְּכַד בַּר נָשׁ נְסִיב אִיתְּתָא, אִתְדַּבַּק בִּשְׁכִינְתָּא. דְּהָא עַד לָא אִנְסִיב, לָא שַׁרְיָא עֲלֵיהּ. דְּלֵית שְׁכִינְתָּא שַׁרְיָא עַל אַתְרָא פְּגִימָא. וְכַד לָא שַׁרְיָא עֲלֵיהּ, אִיהִי אִתְמְנָעוֹ מִנֵּיהּ תְּרֵיסַר מַתָּנָן עִילָאִין.</p>"],[9514013210,"<p>וְעַל דָּא אִיתְעָרוּ חַבְרַיָּיא, כָּל הַשָּׁרוּי בְּלֹא אִשָּׁה, שָׁרוּי בְּלֹא טוֹבָה. כְּמָה דְאַתְּ אָמֵר, (בראשית ב׳:י״ח) לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ. בְּלֹא שִׂמְחָה, דִּכְתִיב (דברים י״ד:כ״ו) וְשָׂמַחְתָּ אַתָּה וּבֵיתֶךָ. בְּלֹא בְּרָכָה, דִּכְתִיב (יחזקאל מ״ד:ל׳) לְהָנִיחַ בְּרָכָה אֶל בֵּיתֶךָ. בְּלֹא שָׁלוֹם, כְּמָה דְאַתְּ אָמֵר (איוב ה׳:כ״ד) וְיָדַעְתָּ כִּי שָׁלוֹם אָהֳלֶךָ. בְּלֹא עֶזְרָה, דִּכְתִיב (בראשית ב׳:י״ח) אֶעֱשֶׂה לּוֹ עֵזְר כְּנֶגְדּוֹ. בְּלֹא כַּפָּרָה, דִּכְתִיב (ויקרא ט״ז:ו׳) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ. בְּלֹא תוֹרָה, כְּמָה דְאַתְּ אָמֵר (איוב ו׳:י״ג) הַאִם אֵין עֶזְרָתִי בִי וְתֻשִׁיָּה נִדְּחָה מִמֶּנִּי. בְּלֹא חָכְמָה, כְּמָה דְאַתְּ אָמֵר (משלי י״ד:א׳) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ. בְּלֹא חַיִּים, כְּמָה דְאַתְּ אָמֵר (קהלת ט׳:ט׳) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ. בְּלֹא רָצוֹן, כְּמָה דְאַתְּ אָמֵר (משלי י״ח:כ״ב) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵה'. בְּלֹא עוֹשֶׁר, כְּמָה דְאַתְּ אָמֵר (שם לא) בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר. בְּלֹא כָבוֹד, כְּמָה דְאַתְּ אָמֵר (שם יא) אֵשֶׁת חֵן תִּתְמֹךְ כָּבוֹד.</p>"],[9514013211,"<p>בְּגִין דְּהַאי אֵשֶׁת חַיִל, יִרְאַת ה' אִקְּרֵי. כְּמָה דְאַתְּ אָמֵר, (תהילים י״ט:י׳) יִרְאַת ה' טְהוֹרָה. וְכַד אִנְסִיב בַּר נָשׁ, כָּלְהוֹ תְּרֵיסַר תַּרְעִין אִתְפַּתְּחָן, לְאוֹסָפָא בִּרְכָאן עַל רֵישֵׁיהּ. בְּגִין דִּיתֵיב בְּסִתְרָא דְּמַטְרוֹנִיתָא, וְאִשְׁתְּלֵים כְּגַוְונָא דִּלְעֵילָא.</p>"],[9514013212,"<p>וְעַל דָּא, (במדבר כ״א:י״ח-י״ט) וּמִמִּדְבָּר מַתָּנָה, וּמִמַּתָּנָה נַחֲלִיאֵ\"ל. נַחֲלִין דְּאֵל נָגְדִין עֲלֵיהּ. וּמִנַּחֲלִיאֵל בָּמוֹת. מַאי בָּמוֹת, אִסְתַּלָּקוּת, דְּאִסְתַּלֵּיק וִיתֵיב בְּרוּמֵי עָלְמָא, וְאִשְׁתַּדֵּל בְּמִלִּין עִילָאִין דְּאוֹרַיְיתָא.</p>"],[9514013213,"<p>וּמִבָּמוֹת הַגַּיְא, אוֹקְמוּהָ. אֲבָל תָּא חֲזֵי, כַּד בַּר נָשׁ אִתְדַּבַּק בְּאוֹרַיְיתָא, וִיתֵיב בְּרוּמֵי עָלְמָא, אִיבָּעֵי לֵיהּ לְאַשְׁפָּלָא גַרְמֵיהּ, בְּגִין דְּיִצְרָא בִּישָׁא קַטֵיגוֹרָא דִּמְקַטְרֵג עֲלוֹי, לָא יִשְׁלוֹֹט עֲלוֹי לְאַסְטָאָה לֵיהּ. וְעַל דָּא, וּמִבָּמוֹת הַגַּיְא, אִיבָּעֵי לֵיהּ לְמֶעְבַּד כְּגַיְא בְּגִין דְּיִתְפְּרַשׁ מִנֵּיהּ הַהוּא דִּיתֵיב בִּשְׂדֵה מוֹאָב, וַדַּאי, יִצְרָא בִּישָׁא דְּאִקְּרֵי לוֹט, וְשַׁרְיָא בְּמוֹאָב, בְּגִין דְּאִתְדַּבְּקוּתֵיה בְּקַדְמִיתָא לַאֲפָקָא פֵּירָא דְּעוֹבָדִין בִּישִׁין בְּעָלְמָא, בְּמוֹאָב הֲוָה, כְּמָה דְאַתְּ אָמֵר, (בראשית י״ט:ל״ז) וַתֵּלֶד הַבְּכִירָה בֵּן וַתִּקְרָא שְׁמוֹ מוֹאָב.</p>"],[9514013214,"<p>וְאִי בַּר נָשׁ אִתְפְּרַשׁ מִנֵּיהּ, סָלֵיק לְמֶהֱוֵי רֹאשׁ, וּלְמִשְׁרֵי בַּפִּסְגָּה. מַאי פִּסְגָּה, כְּמָה דְאַתְּ אָמֵר (תהילים מ״ח:י״ד) פַּסְּגוּ אַרְמְנוֹתֶיהָ. וְנִשְׁקָפָה. דְּאִסְתַּכְּלוּתָא דִלְעֵילָא בֵּיהּ. ו (במדבר כ״א:כ׳) עַל פְּנֵי הַיְשִׁימוֹן, דָּא עָלְמָא דְאָתֵי, דְּאִקְרֵי יְשִׁימוֹן, דְּאִסְתַּכַּל בָּהּ בְּהַאי פִּסְגָּה, קַרְתָּא קַדִּישָׁא יְרוּשָׁלַיִם.</p>"],[9514013215,"<p>דָּבָר אַחֵר, כַּד יִשְׂרָאֵל אֲהַדְּרוּ בִּתְיוּבְתָּא, וּסְלִיקוּ לְבֵירָא לְעֵילָא, אִתְיְיהִיבַת לוֹן בְּמַתָּנָה. וְכַד תָּבוּ לְאוֹרַח בִּישָׁא, כְּדֵין וּמִבָּמוֹת הַגַּיְא. כְּמָה דְאַתְּ אָמֵר (דברים ג׳:כ״ט) וַנֵּשֶׁב בַּגָּיְא מוּל בֵּית פְּעוֹר. עַל הַהוּא חוֹבָה, יָתְבוּ לְתַתָּא בַּגָּיְא. אֲשֶׁר בִּשְׂדֵה מוֹאָב, בְּגִין דְּסִטְרָא דְמוֹאָב גָּרֵים לוֹן.</p>"],[9514013216,"<p>וּלְבָתַר דְּקַבִּילוּ עוֹנְשַׁיְיהוּ, סְלִיקוּ לְרֵישָׁא, וַאֲרִימוּ דִּגְלֵיהוֹן עַל כֹּלָא. כְּמָה דְאַתְּ אָמֵר (במדבר כה) וַיְהִי אַחֲרֵי הַמַּגֵּפָה וכו', שְׂאוּ אֶת רֹאשׁ. לַאֲרָמָא דִּגְלֵיהוֹן עַל כֹּלָא.</p>"],[9514013217,"<p>תָּא חֲזֵי, הַאי בֵּירָא מִנְחָה אִקְּרֵי, כְּמָה דְאַתְּ אָמֵר (בראשית מ״ג:י״א) וְהוֹרִידוּ לָאִישׁ מִנְחָה. תְּחַבְּרוּן מִנְחָה בְּבַעֲלָהּ, דְּגָרַמְתּוּן דְּיִסְתַּלֵּק מִינָּהּ, כַּד נָחֲתוּ כ הַהוּא צַדִּיק לְמִצְרַיִם.</p>"],[9514013218,"<p>וְהָא הוּא תּוֹרָה שֶׁבְּעַל פֶּה, וְאִקְּרֵי בְּאֵר, דִּכְתִיב (דברים א׳:ה׳) הוֹאִיל משֶׁה בֵּאֵר. וְאִית בָּהּ שִׁית סִדְּרִין. בְּגִין כָּךְ שִׁית דַּרְגִּין יִסְתַּלֵּיק, מַאן דְּיִתְעַסֵּק בָּה.</p>"],[9514013219,"<p>הֲדָא הוּא דִכְתִיב, וּמִמִּדְבָּר מַתָּנָה. מַאי מִדְבָּר, כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:ג׳) וּמִדְבָּרֵךְ נָאוֶה. מַתָּנָה, גָּרִים לַצַּדִּיק, דִּיהֵיב לֵיהּ מַתָּנָה. וּמִמַּתָּנָה נַחֲלִיאֵל, אִלֵּין נַחֲלִין עִילָאִין, נֶצַח וָהוֹד. וּמִנַּחֲלִיאֵל בָּמוֹת, דָּא אִסְתַּלְּקוּתָא לְאַתְרָא דְמַלְכָּא שָׁארֵי. וּמִבָּמוֹת הַגַּיְא אֲשֶׁר בִּשְׂדֵה מוֹאָב, דָּא יִצְחָק, דִּיתֵיב בְּהַהוּא שָׂדֶה. דִּכְתִיב (בראשית כ״ד:ס״ג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה. וּמֵהַהוּא שָׂדֶה אִיתְעַר עֲלֵיהוֹן דִּינָא, עַד דְּיָתְבוּ בַּגָּיְא. רֹאשׁ הַפִּסְגָּה, דָּא אַבְרָהָם, רֵישָׁא דְעָלְמָא.</p>"],[9514013220,"<p>וְתָּא חֲזֵי, כַּד נָחַת יוֹסֵף לְמִצְרַיִם, חָזָא יַעֲקֹב בְּחָכְמָה, וְרָמַז לוֹן דְּיַחֲתוּן תַּמָּן לְמִנְחָה, דְּתֶהֱוֵי מְגִינָה עֲלֵיהוֹן בְּגָלוּתָא. וּבְהַאי מִנְחָה, שִׁית סִטְרִין כְּלִילָן. (בראשית מ״ג:י״א) מְעַט צֳרִי וּמְעַט דְּבַשׁ.</p>"],[9514013221,"<p>מַאי טַעְמָא מְעַט מְעָט. תָּא חֲזֵי, כַּד בַּר נָשׁ לֹא אִתְכַּשְׁרוֹן עוֹבָדֵיהוֹן לְעֵילָא, כְּדֵין סִטְרָא דְּיָמִינָא אִתְרַפְיָיא, וְשַׁלִּיט שְׂמָאלָא, וְעַל דָּא מְעַט צֳרִי וּמְעַט דְּבַשׁ, דָּא תָּמָר, דְּאִסְתַּלַּק דְּכוּרָא מִן נוּקְבָא, וּכְדֵין מְעַט דְּבַשׁ. נְכֹאת, כְּמָה דְאַתְּ אָמֵר (מלכים ב כ׳:י״ג) וַיַּרְאֵם אֶת כָּל בֵּית נְכֹתֹה. (בראשית מ״ג:י״א) וָלֹט בָּטְנִים וּשְׁקֵדִים, הָא שִׁיתָּא דַּרְגִּין הָכָא, דִּכְלִילָן בְּהַאי מִנְחָה.</p>"],[9514013222,"<p>וְעִם כָּל דָּא אַף עַל גַּב דְּנָחֲתָא, מְעַט צֳרִי אָתִי מִשּׁוּם דְּיָתְבָא בְּגָלוּתָא. וְכַד תַּעַבְדוּן הַאי מִנְחָה, כְּדֵין (שם) וְאֵל שַׁדַּי יִתֵּן לָכֶם רַחֲמִים. אֵל: דָּא אַבְרָהָם. שַׁדַּי: דָּא יִצְחָק. יִתֵּן לָכֶם רַחֲמִים: דָּא יַעֲקֹב. לִפְנֵי הָאִישׁ: דָּא יוֹסֵף. כָּל אִלֵּין דַּרְגִּין יִתְחַבָּרוּ. וַאֲנִי כַּאֲשֶׁר שָׁכֹלְתִּי שָׁכָלְתִּי. שָׁכֹלְתִּי בְּמִקְדָּשׁ רִאשׁוֹן. שָׁכָלְתִּי בְּמִקְדָּשׁ שֵׁנִי. לֹא אֶשְׁכַּל עוֹד. וְכָל דָּא בְּחוֹבָא דְּהַהוּא זַכָּאָה, דְּנָחֲתוּ לְמִצְרַיִם.</p>"],[9514013223,"<p>וְתָּא חֲזֵי, תְּרֵיסַר שְׁנִין יָתִיב הַהוּא צַדִּיק בְּבֵית הָאֲסוּרִים. בְּגִין כָּךְ תְּרֵיסַר שְׁבָטִין בְּגָלוּתָא דֶּאֱדוֹם. בְּגִין מְאָה בִּרְכָאן דִּמְנָעוּ מִכָּל יוֹמָא.</p>"],[9514013224,"<p>וְשַׁתָּא חָדָא לְחוּד יָתִיב בְּבֵית פּוֹטִיפַר. דִּכְתִיב, (בראשית ל״ט:ה׳) וַיְהִי בִּרְכַּת ה' בְּכָל אֲשֶׁר יֶשׁ לוֹ בַּבַּיִת וּבַשָּׂדֶה. בַּבַּיִת, דָּא פַּלְגוּת שַׁתָּא דִּקְרִירוּ נָחִית לְעָלְמָא. וּבַשָּׂדֶה, דָּא פַּלְגוּת שַׁתָּא דְּבַר נָשׁ יָתִיב בְּעוֹבָדוֹי בְּחַקְלָא. יִשְׁתָּאֲרוּ י\"ב שְׁנִין דְּיָתִיב בְּהַהוּא בּוֹר. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אִתְעַר עֲלֵיהוֹן בּוֹר דְּהַהוּא נָחָשׁ, גָּלוּתָא דְּעֵשָׂו. וְעַל דָּא וְהוֹרִידוּ לָאִישׁ מִנְחָה, וּבְסוֹף גָּלוּתָא, בְּגִין דְּאִינוּן יָהֲבוּ מִנְחָה, אִתְקַיִּים בְּהוּ (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה'.</p>"],[9514013225,"<p>וְתָּא חֲזֵי, הַאי מִנְחָה אַרְעָא קַדִּישָׁא אִתְקַרְיָיא, וְאִשְׁתַּבְּחָא בְּשִׁבְעָה פֵּירִין עִילָאִין דְּאִית בָּהּ, כַּד אִיהִי בְּאִתְחַבְּרוּתָא לְעֵילָא. וְעַל דָּא פַּקֵּיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, כַּד יֵיעֲלוּן לְאַרְעָא קַדִּישָׁא, דְּיִתְחַבְּרוּן אִתְּתָא בְּבַעֲלָהּ.</p>"],[9514013226,"<p>הֲדָא הוּא דִכְתִיב, (דברים כו) וְלָקַחְתָּ מֵרֵאשִׁית כָּל פְּרִי הָאֲדָמָה. אָדָם, דָּא יַעֲקֹב, כַּד אִתְחַבַּר בֵּיהּ אִימָא עִילָאָה, דְּאִתְקַרְיָא ה', וְאַעֲטָרַת לֵיהּ, כְּדֵין יָהֵיב פְּרִי הַהוּא אִילָנָא רַבְרְבָא, וְאִיקְרֵי בִּשְׁלִימוּ אֲדָמָ\"ה.</p>"],[9514013227,"<p>וְשַׂמְתָּ בַטֶנֶא, דָּא מַטְרוֹנִיתָא, דְּאָתֵי לָהּ נְהִירוּ מִנֵּיהּ, וְשַׁוֵּי בָהּ נְהִירוּ עִילָאָה דְּאָתֵי לֵיהּ מֵרֵאשִׁית. וּכְדֵין, וְהָלַכְתָּ אֶל הַמָּקוֹם. וּמַאן הוּא פְּרִי דְאָדָם דְּעֵילָא, דָּא יוֹסֵף, דְּאִקְרֵי צַדִּיק, פְּרִי מֵהַהוּא עֵץ חַיִּים. וְהַהוּא פְּרִי תְּחַבֵּר בַּטֶנֶא. וְאִי לָא תֵיזֵל עִם הַאי פְּרִי, אִסְתַּמַּר מִלְּמֵיזַל לְהַהוּא אַתְרָא, דְּלָא תּוֹקִיד לָךְ בְּשַׁלְהוֹבְהָא.</p>"],[9514013228,"<p>כָךָ אָמַר יַעֲקֹב לִבְנוֹי, אִסְתַּמָּרוּ מִלְּמֵיחַת לְמִצְרַיִם, אִי לָא תַחֲתוּן לָאִישׁ הַהוּא מִנְחָה. וְכַד תַּחֲתוּן, תִּתְפַּיְיסוּן כַּחֲדָא, וְכָל עָלְמָא בְּחֶדְוָה.</p>"],[9514013229,"<p>וְתָּא חֲזֵי, מַה כְּתִיב, וַיָּכִינוּ אֶת הַמִּנְחָה עַד בֹּא יוֹסֵף. דְּהַאי מִנְחָה אִתְתַּקָּנַת בִּתְרֵיסַר סַמְכִין דִּילָהּ, עַד דְּאָתָא בַּעֲלָהּ לְאִתְחַבָּרָא בָּהּ בַּצָּהֳרָיִם. וּבְהַהוּא זִמְנָא אִינוּן יֵיכְלוּן לַחֲמָא תַּמָּן, וְסַמָּא דְחַיֵּי אִתְעַר עֲלַיְיהוּ.</p>"],[9514013230,"<p>פְּתַח וַאֲמַר, (תהילים י׳:י״ב) קוּמָה ה' אֵל נְשָׂא יָדֶךָ. לְאַגְבָּרָא יָמִינָא עַל כֹּלָא. כְּמָה דְאַתְּ אָמֵר, (שמות ו׳:ח׳) נָשָׂאתִי אֶת יָדִי. וְדָא יָמִינָא עִילָאָה, דְּאִקְרֵי אֵל, דַּאֲרֵימַת דִּגְלָא לְעֵילָא. וְעַל דָּא, (דברים כ״ו:ג׳) וּבָאתָ אֶל הַכֹּהֵן, וְדָא סִטְרָא דְּיָמִינָא, דְּאִתְעַר בְּעָלְמָא, וְהוּא יְקַבֵּל מִינָךְ הַהוּא מִנְחָה, וִיקַבֵּל לָהּ בְּיָמִינָא.</p>"],[9514013231,"<p>וְעַל דָּא כְּתִיב, (דברי הימים א כ״ט:י״א) לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה. מַה טַעַם, מִשּׁוּם דִּכְתִיב כִּי כֹל בַּשָּׁמַיִם. וְאִתְחַבַּר בָּאָרֶץ הַאי רֵאשִׁית פְּרִי, וְכָל כִּתְרִין.</p>"],[9514013232,"<p>וְעַל דָּא כְּתִיב, (תהילים קל״ד:ב׳) שְׂאוּ יְדֵיכֶם קֹדֶשׁ, קַבִּילוּ לְהַהוּא מִנְחָה דְּאִקְרֵי יֶדְכֶם דְּיָמִינָא, וְתִשְׂאוּ יָתָהּ לְאַתְרָא דְאִקְרֵי קֹדֶשׁ, דְּהַיְינוּ שַׁבָּת, תִּשְׂאוּ יָתָהּ לֵיהּ. וּכְדֵין וּבָרְכוּ אֶת ה', וְאִיהִי אִתְבָּרְכַת מִכֹּלָא, עַל יְדוֹי דְּכַהֲנָא דְּאִתְלַבַּשׁ בְּבַד, דְּאִיהוּ עֲנָפָא דְאִילָנָא עִילָאָה, דְּאִקְרֵי חָכְמָה עִילָאָה דְּאִתְלַבְּשַׁת בֵּיהּ. וּמֵהַהוּא עֲנָפָא, נָפְקִין כָּל בִּרְכָאן בְּעָלְמָא.</p>"],[9514013233,"<p>וְחוּשְׁבְּנָא דְּהַאי כֹּהֵן שִׁבְעִין וְחָמֵשׁ. שִׁבְעִין וּתְרֵין, לָקֳבֵיל ע\"ב סִטְרִין, רְשִׁימִין בְּסִטְרָא דְחֶסֶד. וּתְלָתָא דְּאִישְׁתָּאֲרוּ, לָקֳבֵיל תְּלָתָא דַּרְגִּין עִילָאִין, דְּאִתְלַבַּשׁ בְּהוֹן. וְלָא בָּעֵי כַּהֲנָא לְמִיפְסַק, בֵּין הַהוּא לְבוּשׁ עִילָאָה דְּאִתְלַבַּשׁ בֵּיהּ, דְּלָא לְאַחֲזָאָה פִּרוּדָא בְּאַתְרָא עִילָאָה. וּכְדֵין אִתְבָּרְכָן עִילָאִין וְתַתָּאִין עַל יָדֵיהּ.</p>"],[9514013234,"<p>וְתָּא חֲזֵי, אִלְמָלֵא הַהוּא מִנְחָה דְּנָחֲתָא עִמְּהוֹן, וּבָעְיָא עֲלֵיהוֹן רַחֲמִין, לָא נַפְקֵי מִתַּמָּן. הֲדָא הוּא דִכְתִיב, (שמות ב׳:כ״ג) וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים מִן הָעֲבוֹדָה. הָאֱלֹהִים: דָּא אִימָא עִילָאָה. מִן הָעֲבוֹדָה: דָּא מִנְחָה, דְּאִיהִי עֲבוֹדָה וְאִיהִי מְצַלְּאָה עַל בְּנָהָא, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ט:ד׳) וַאֲנִי תְפִלָּה. וְאִקְרֵי עֲבוֹדָה, בְּגִין דְּהִיא גַּן עֵדֶן, וְאִצְטְרִיךְ לְמִפְלְחָה.</p>"],[9514013235,"<p>וְאִיהִי קִיּוּמָא דְּעָלְמָא. וְעַל דָּא אִיתְעָרוּ חַבְרַיָיא, עַל תְּלַת מִלִּין עַלְמָא מִתְקַיִּים, עַל הַתּוֹרָה, דָּא יַעֲקֹב. עַל הָעֲבוֹדָה, דָּא תּוֹרָה שֶׁבְּעַל פֶּה. וְעַל גְּמִילוּת חֲסָדִים, דָּא אַבְרָהָם. דָּבָר אַחֵר, עֲבוֹדָה, דָּא יִצְחָק, וְכוֹלָא חַד.</p>"],[9514013236,"<p>וְכַד אִיתְעַר הַאי כֹּהֵן, לְהַאי עֲבוֹדָה, כְּדֵין נָחִית לֶחֶם מִן הַשָּׁמַיִם לְהַאי אֶרֶץ, וְזָן לְיָתְבָהָא. וּמַאי לֶחֶם. דָּא לֶחֶם, דְּאִסְתַּלַּק לְעֵילָא, וּמְזוֹנֵי בְּמַזָּלָא תַּלְיָין. וּמִתַּמָּן נָחִית בְּשַׁבָּת מְזוֹנֵי. כֵּיוָן דְּאִיהִי קִיּוּמָא דִּלְעֵילָא. בְּגִין דְּהוּא עָלְמָא דְאָתֵי, וְעָלְמָא דְאָתֵי אַפֵּיק נְהִירוּ לְעֵילָא.</p>"],[9514013237,"<p>וְעַל דָּא, (שמות ט״ז:כ״ה) הַיּוֹם לֹא תִמְצָאֻהוּ בַּשָּׂדֶה, בְּגִין דְּהַאי יוֹמָא, קַבֵּילַת הַאי שָׂדֶה, שַׁקְיוּ לְגַרְמָהּ. אֲבָל לְעַלְמָא דְאָתֵי, תִּשְׁכְּחוּן הַהוּא יוֹמָא טָבָא, דָּא הוּא שָׂדֶה, דְּנָהֵיר בִּנְהִירוּ דְשִׁמְשָׁא.</p>"],[9514013238,"<p>וְתָּא חֲזֵי, הַאי שַׁבָּת כָּ\"ל אִיקְרֵי. בְּגִין דְּחַמְשִׁין תַּרְעִין בֵּיהּ אִתְפַּתְּחִין וְאִיתְעַר. וְכַד הַאי כָּל אִתְעַר לְכַלָּה, כְּדֵין אִימָא עִילָאָה אַלְבֵּישַׁת לֵיהּ גְּבוּרָן עִילָאִין, וְאִיתְעָרוּ רַחֲמִין בְּעָלְמִין, וְתִיקוּנָא עִילָאָה אִתְתַּקַּן.</p>"],[9514013239,"<p>וְהוּא, הַהוּא אַפִּרְיוֹן. וְעַל דָּא כְּתִיב (שיר השירים ג׳:ט׳) אַפִּרְיוֹן עָשָׂה לוֹ הַמֶּלֶךְ שְׁלמֹה. דָּא תִּיקוּנִין דְּעָלְמָא. עַמּוּדָיו עָשָׂה כֶסֶף, דָּא אַבְרָהָם. רְפִידָתוֹ זָהָב, דָּא יִצְחָק. מֶרְכָּבוֹ אַרְגָּמָן, דָּא יַעֲקֹב, כָּלֵיל תְּרֵין סִטְרִין. דְּרָכֵיב עַל כּוּרְסַיָּיא, דְּאִקְרֵי אַהֲבָה זוּטָא.</p>"],[9514013240,"<p>דָּבָר אַחֵר, תּוֹכוֹ רָצוּף אַהֲבָה, דָּא אַהֲבָה רַבָּה, דְּאִיהִי פְּנִימָאָה. מִבְּנוֹת יְרוּשָׁלַיִם, כַּד אַתְקִינוּ לְהַאי מִנְחָה, דְּאַנְהֵיר לָהּ שִׁמְשָׁא.</p>"],[9514013241,"<p>וְעַל דָּא (בראשית מ״ג:כ״ה) וַיָּכִינוּ אֶת הַמִּנְחָה, כְּדֵין וַיִּשָׂא מַשְׂאֹת, פָּלִיג לוֹן חוּלָקֵיהוֹן. וּמֵאָן אֲתַר יָהֵיב לוֹן, מֵאֵת פָּנָיו, דָּא הַאי כּוּרְסַיָיא, דִּמְזוֹנָא דְּכוֹלָא בֵּיהּ.</p>"],[9514013242,"<p>(שם) וַתֵּרֶב מַשְׂאַת בִּנְיָמִין, מַאי טַעְמָא, בְּגִין דִּשְׁכִינְתָּא בְּחוּלָקֵיהּ. מִמַּשְׂאֹת כֻּלָּם חָמֵשׁ יָדוֹת, תָּא חֲזֵי, הַאי ה' בַּתְרָאָה, אִקְרֵי כַּלָּה, כַּד אִתְחַבַּר כָּ\"ל עִמָּהּ, לָא אִתְיַיְשְׁבוּ אֶלָּא בְּחוּלָקָא דְּבִנְיָמִין. וְעַל דָּא חָמֵשׁ יָדוֹת קַבֵּיל, כַּד קַבֵּיל הַאי ה' דְּאִקְרֵי מִנְחָה בְּחוּלָקֵיהּ. וְכָל חַמְשִׁין בִּרְכָאן, דְּאַתְיָין מִכָּ\"ל לְהַאי כַּלָּ\"ה, קַבֵּיל בִּנְיָמִין. מַאי טַעְמָא, בְּגִין דְּאִיהוּ זְעֵירָא דְּכָלְהוֹ.</p>"],[9514013243,"<p>מַשְׂאַת כָּלְהוֹ שִׁבְטִין עֲשָׂרָה, מַשְׂאַת בִּנְיָמִין, אִתְרַבֵּי, ה' זִמְנִין עֲשָׂרָה. הָא חַמְשִׁין. וְכוֹלָא בְּגִין הַאי ה' דְּשַׁרְיָא בְּחוּלָקֵיהּ. מַאי טַעְמָא, בְּגִין דְּאִיהִי זְעֵירָא, וְאִיהוּ זְעִיר, אִתְרְעִיאַת בֵּיהּ, לְשַׁוָּאָה מְדוֹרָה עִמֵּיהּ.</p>"],[9514013244,"<p>וְעַל דָּא כְּתִיב, (שיר השירים א׳:ד׳) הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו, דָּא בִּנְיָמִין, דְּאָעֵיל לֵיהּ יוֹסֵף בְּאִידְרֵיהּ. נָגִילָה וְנִשְׂמְחָה, אָגִילָה מִבָּעֵי לֵיהּ, מַאי נָגִילָה. דְּכָלְהוֹ אָעֵיל לוֹן בְּגִינֵיהּ דְּבִנְיָמִין. בָּךְ, מַאי בָּךְ. דָּא כְּלָלָא דְאוֹרַיְיתָא, דְּאִתְקַיִּים כַּד נָטֵיר אוֹת בְּרִית קֹדֶשׁ. נַזְכִּירָה דוֹדֶיךָ מִיָּיִן, דִּכְתִיב וַיִּשְׁתּוּ וַיִּשְׁכְּרוּ עִמּוֹ.</p>"],[9514013245,"<p>וְעַל דָּא כְּתִיב, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה, דְּמָשִׁיךְ לוֹן לַאֲחוֹי תַּמָּן. כְּמָה דְאַתְּ אָמֵר, (הושע י״א:ד׳) בְּחַבְלֵי אָדָם אֶמְשְׁכֵם בַּעֲבֹתוֹת אַהֲבָה, דָּא אַהֲבָה דְּנַחֲתָא עִמְּהוֹן לְדַיְיָרָא תַּמָּן, וְחָדוֹ תַּמָּן בְּמַלְכָּא עִילָּאָה, דְּאִתְחַבַּר עִם יוֹסֵף תַּמָּן, בְּגִין דְּנָטַר בְּרִית קֹדֶשׁ דְּאִתְיְיהֵיב לִתְמַנְיָא יוֹמִין.</p>"],[9514013246,"<p>וְעַל דָּא כְּתִיב, (שיר השירים א׳:ד׳) מֵישָׁרִים אֲהֵבוּךָ. מַאי מֵישָׁרִים, כְּמָה דְאַתְּ אָמֵר (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וּמַאן אִינוּן, כְּמָה דְאַתְּ אָמֵר, (שם) מִשְׁפָּט וּצְדָקָה. אִלֵּין אִיקְרוּן מֵישָׁרִים וַדַּאי. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ד׳) צַדִּיק וְיָשָׁר הוּא. וְאִתְכְּלֵיל דְּכוּרָא עִם נוּקְבָא, מִשְׁפָּט אִתְכְּלֵיל בְּצֶדֶק, וּצְדָקָה אִיתְעָרַת בְּעָלְמִין כָּלְהוֹ. וְעַל דָּא מֵישָׁרִים אֲהֵבוּךָ וַדַּאי.</p>"],[9514013247,"<p>(בראשית ל״ז:ג׳) וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו. יִשְׂרָאֵל מִבָּעֵי לֵיהּ, מַאי וְיִשְׂרָאֵל. לְאַכְלָלָא עִמֵּיהּ שְׁכִינְתָּא, דִּרְחִימָא לֵיהּ לְיוֹסֵף. כְּגַוְונָא דָא תָּנִינָן וַה', הוּא וּבֵית דִּינוֹ.</p>"],[9514013248,"<p>וְכָלְהוֹ שְׁבָטִין אוֹדוּ לֵיהּ, עַל דְּאִתְרְחֵים מֵאַבָּא וְאִימָא. וּבְרִיכוּ לֵיהּ בִּרְכַּת עָלְמִין כָּלְהוֹ, לְאִתְיַישְׁבָא בְּדוּכְתֵּיהּ כִּדְקָא חָזֵי.</p>"],[9514013249,"<p>וּמְנָא לָן דַּאֲפִילוּ אֲחוֹי רְחִימוּ לֵיהּ. דִּכְתִיב (שיר השירים א׳:ג׳) עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. מַאי עֲלָמוֹת כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״ה) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר. וְאִינוּן בְּעַלְמָא דְנוּקְבָא, וְאִינוּן אִיקְרוּן עֲלָמוֹת.</p>"],[9514013250,"<p>בָּתַר דְּאִסְתַּלֵּיק יוֹסֵף לְעֵילָא, מַה כְּתִיב, (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה, בְּגִין דְּאִתְתַּקֵּיף גָּלוּתָא עֲלַיְיהוּ. וְעִם כָּל דָּא וְנָאוָה, דְּלָא אִתְעַרְבֵי בְּהוּ. כְּאָהֳלֵי קֵדָר, אִתְקַדְרִית בֵּינַיְיהוּ, דְּגָזְרוּ עָלַי כַּמָּה גִּזְרִין בִּישִׁין, וְעִם כָּל דָּא אֲנָא אִיהִי כִּירִיעוֹת שְׁלמֹה, בְּעוֹבָדִין טָבִין. בְּגִין דְּשִׁבְטֵי יָהּ עָאלוּ, וְשִׁבְטֵי יָהּ נָפְקוּ.</p>"],[9514013251,"<p>(שם) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת, בְּגִין דְּשִׁמְשָׁא אִסְתְּלֵיק. וְכָל דָּא בְּנֵי אִמִּי גָּרְמוּ. מַאן בְּנֵי אִמִּי. דָּא בְּנוֹי דְּיַעֲקֹב, דְּזַבִּינוּ לְיוֹסֵף הָכָא. וְאִינוּן גָּרְמוּ לִי וְלִשְׁכִינְתָּא דְּאִתְגַּלְּיָיא עִמִּי הָכָא.</p>"],[9514013252,"<p>עַל דָּא אָמַר (שמות ב) וַיֵּאָנְחוּ בְנֵי יִשְׂרָאֵל. כַּד חָמוּ פּוּלְחָנָא קַשְׁיָא, עַד דְּהֲוָה דָּכֵיר לְהוֹן קְיָימָא עִילָאָה וְאִתְעָרַת בְּרַחֲמִין עַל בְּנָהָא, אִימָא עִילָאָה. הֲדָא הוּא דִכְתִיב, (שם) וַתַּעַל שַׁוְעָתָם אֶל הָאֱלֹהִים, דָּא אִימָא עִילָאָה, דְּכָל חֵירוּ בִּידָהָא, וּפָתְחָה לוֹן פִּתְחִין עִילָּאִין, חַמְשִׁין תַּרְעִין, וַאֲפֵיקַת לוֹן מִתַּמָּן. וְאִתְמַלְיָיא אִימָא תַּתָּאָה רַחֲמִין עֲלַיְיהוּ. וּמשֶׁה נְפַק לְעַלְמָא, מְמַנָּא וְאַב לְמִרְעֵי לְיִשְׂרָאֵל בְּאוֹרַיְיתָא.</p>"],[9514013253,"<p>תָּא חֲזֵי, דָּוִד רָמַז לֵיהּ לְהַאי תּוּשְׁבַּחְתָּא דְּשִׁיר הַשִּׁירִים קוֹדֶשׁ קוּדְשַׁיָיא, עַל יְדָא דִבְנֵי קֹרַח, אֶלָּא דְלָא מָטָא זִמְנָא דְּיִתְאֲמַר. בְּגִין כָּךְ כְּתִיב, (תהלים מה) לַמְנַצֵּחַ עַל שׁוֹשַׁנִּים לִבְנֵי קֹרַח מַשְׂכִּיל שִׁיר יְדִידֹת. עַל שׁוֹשַׁנִּים, אִלֵּין נְשִׁיקוֹת פִּיהוּ, דְּאִיקְרוּן שִׂפְתוֹתָיו שׁוֹשַׁנִּים.</p>"],[9514013254,"<p>דָּבָר אַחֵר, שׁוֹשַׁנִּים, אִלֵּין שִׁית שְׁנִין, דְּאִתְחַבְּרוּן בְּהַאי שׁוֹשַׁנָה סוּמְקָא, דְּאִיהִי שְׁבִיעָאָה דְּכֹלָא. מַשְׂכִּיל, דָּא נְגִידוּ דְּעַתִּיקָא קַדִּישָׁא, דְּנָגֵיד לוֹן בְּהַאי שַׁעֲתָא, דְּיָתְבֵי יַחַד וְלָא מִתְפָּרְשִׁין. בְּגִין אִינוּן נְשִׁיקִין בִּדְבֵיקוּתָא דְרוּחָא, וְלָא מִתְפָּרְשִׁין.</p>"],[9514013255,"<p>שִׁיר יְדִידוּת, רֶמֶז לְהַאי שִׁירָתָא, דְּאִקְרֵי שִׁיר כָּפוּל. הָכָא שִׁיר הַשִּׁירִים, וְהָכָא שִׁיר יְדִידוּת, וְכוֹלָא חַד. קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל, אִיקְרוּן דּוֹדִים. הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:א׳) שְׁתוּ וְשִׁכְרוּ דּוֹדִים. בְּגִין כָּךְ שִׁיר יְדִידוּת, דְּאִינוּן דּוֹדִים, דָּא מְשַׁבְּחָא לְדָא, וְדָא מְשַׁבְּחָא לְדָא. וּכְמָא דְהָתָם, כְּנֶסֶת יִשְׂרָאֵל שְׁרִיאַת בְּתוּשְׁבַּחְתָּא, דְּהָכֵי אִתְחֲזֵי, דִּכְתִיב יִשָׁקֵנִי. אוּף הָכָא, הִיא שְׁרִיאַת לְשַׁבָּחָא לְמַלְכָּא.</p>"],[9514013256,"<p>(תהלים מה) רָחַשׁ לִבִּי דָּבָר טוֹב. רָחַשׁ לִבִּי, דָּא חַיָיתָא, דְּרָחִישׁ בְּלֵילְיָא, דְּאִקְרֵי לִבִּי. דָּבָר טוֹב, דִּסְלִיקַת בִּרְעוּתָהּ דְּיִתְחַבַּר מַלְכָּא עִמָּהּ, דְּאִקְרֵי טוֹב.</p>"],[9514013257,"<p>דָּבָר אַחֵר, בְּגִין דְּלָא אִתְיְיהֵיב לֵיהּ רְשׁוּ לְגַלָּאָה, אָמַר רָחַשׁ בְּגִין דִּמְרַחֲשָׁא לֵיהּ הַאי מִלָּה בְּלִבֵּיהּ, וַאֲפִילוּ בְּשִׂפְוָותֵיהּ לָא אִתְיְיהֵיב לֵיהּ רְשׁוּ לְרַחֲשָׁא, אֶלָּא בְּלִבֵּיהּ.</p>"],[9514013258,"<p>דָּבָר אַחֵר, מַאי טַעְמָא רָחַשׁ לִבִּי. בְּגִין דְּדִבּוּר בְּלָא קוֹל, לָא יָכִיל לְמַלָּלָא. וְהַאי לִבִּ\"י דְּאִקְּרֵי דִּבּוּר, עַד הַשְׁתָּא לָא אִשְׁתַּלֵּימַת, עַד דְּאָתָא שְׁלֹמֹה מַלְכָּא, וּבְנָא לָהּ בֵּיתָא, וְאִשְׁתַּלֵּימַת סִיהֲרָא בִּרְבוּ יַתִּיר עַל כּוֹלָא. בְּגִין דְּקוֹל אִתְחַבַּר עִמָּהּ.</p>"],[9514013259,"<p>וְהַהִיא שַׁעֲתָא, אִתְיְיהֵיב רְשׁוּ לְמַלָּלָא, דְּהָא אִשְׁתְּלֵימַת בְּקָלָא. וְיָתְבָא בִּשְׁלִימוּ עִם מַלְכָּא. בְּגִין דַּאֲפֵיקַת בְּרָא חַכִּימָא לְעָלְמָא, וְאַתְקֵינַת בֵּיתָא לְמַלְכָּא. כְּדֵין מַלְכָּא שַׁוֵּי מְדוֹרֵיהּ עִמָּהּ, וְשָׁרַאת לְמַלָּלָא, וַאֲמָרַת יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ.</p>"],[9514013260,"<p>אֲבָל הַשְׁתָּא בְּיוֹמֵי דְדָוִד, עַד כְּדֵין לָא יָתְבָא בְּאִשְׁתַּלָּמוּתָא, בְּגִין כָּךְ רָחַשׁ לִבִּי וַדַּאי הַהוּא דָּבָר טוֹב. הַשְׁתָּא טוֹב, וְלֹא טוֹבִים. כֵּיוָן דְּאִתְחַבַּר קוֹל עִמָּהּ, כְּדֵין טוֹבִים וַדַּאי בְּכוֹלָא. צַדִּיק טוֹב אִקְּרֵי, דִּכְתִיב, (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב. אוּף אִיהִי אִתְקְרִיאַת טוֹבָה, (קהלת ז) טוֹבָה חָכְמָה. וְכַד אִיתְקְרִיבוּ אִתְחַבָּרוּ כַּחֲדָא בְּאִינוּן נְשִׁיקִין, כְּדֵין (שיר השירים א׳:ב׳) כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן, אִינוּן דּוֹדִים תַּרְוַויְיהוּ כַּחֲדָא.</p>"],[9514013261,"<p>הָכָא דּוֹדִים, וְהָכָא יְדִידוּת. וְאֵימַת אִינוּן טוֹבִים. מִיָּיִן. כַּד אִשְׁתַּקְיָין מִנֵּיהּ דְּהַהוּא יַיִן דְּמִנְטְרָא. וְעַל דָּא כְּתִיב, (שם ה) שְׁתוּ וְשִׁכְרוּ דּוֹדִים. דְּהָא נְטִיעָן שַׁקְיוּ בָּעְיָין מִנַּהֲרָא עֲמִיקָא, אִימָא עִילָאָה, דְּאִיהִי אַשְׁקִיאַת לוֹן בְּקַדְמִיתָא מֵהַהוּא יַיִן.</p>"],[9514013262,"<p>הֲדָא הוּא דִכְתִיב, (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, וּלְבָתַר לְרֵיחַ שְׁמָנֶיךָ טוֹבִים, הֲדָא הוּא דִכְתִיב וִימִינוֹ תְּחַבְּקֵנִי. וְדָא הוּא מִשְׁחָא טָבָא, דְּנָגִיד לֵיהּ מֵאִימָא.</p>"],[9514013263,"<p>הֲדָא הוּא דִכְתִיב, (תהילים קל״ג:ב׳) כַּשֶּׁמֶן הַטוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן זְקַן אַהֲרֹן. דָּא כַּהֲנָא רַבָּא לְעֵילָא, יָמִינָא דְמַלְכָּא, כֹּהֵן לְעוֹלָם. וְכַד מָטָא הַהוּא מִשְׁחָא אֶל דִּיקְנֵיהּ דְּאַהֲרֹן, כְּדֵין שְׁמָנֶיךָ וַדַּאי אִיקְרוּן, מִסִּטְרָא דְאִימָא וּמִסִּטְרָא דְאַבְרָהָם, וּכְדֵין שְׁמָנֶיךָ טוֹבִים.</p>"],[9514013264,"<p>מַאי טַעְמָא נְגִיד הַהוּא מִשְׁחָא טָבָא לְאַבְרָהָם. מִשּׁוּם דְּפָּשִׁיט יָמִינָא, לְאַנְהָרָא לְסִיהֲרָא. וְעַל דָּא כְּתִיב, (שם) הִנֵּה מַה טוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. מַה טוֹב, דָּא נְהוֹרָא קַדְמָאָה. דִּכְתִיב (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וּמַה נָּעִים, דָּא נְעִים זְמִירוֹת יִשְׂרָאֵל. יוֹמָא רְבִיעָאָה, סִיהֲרָא.</p>"],[9514013265,"<p>וְתָּא חֲזֵי, כְּמָה דִנְהוֹרָא דְּאִתְבְּרֵי בְּיוֹמָא קַדְמָאָה, יָהֵיב שְׁלִימוּ, וְנָגִיד מִנֵּיהּ נְהִירוּ, לִנְהוֹרָא דְּהַאי עָלְמָא אִתְנְהֵיג בֵּיהּ. אוּף אַבְרָהָם, נְהוֹרָא קַדְמָאָה, יְהֵיב נְהִירוּ לְהַאי בְרַתָּא דְמַלְכָּא, יוֹמָא רְבִיעָאָה, דְּעַל יָדָהּ אִתְנְהֵיג הַאי עָלְמָא. וְעַל דָּא חוּט שֶׁל חֶסֶד מָשׁוּךְ עֲלֵיהּ, לְאַנְהָרָא מִן נְהוֹרֵיהּ. וְכַד אִתְחַבְּרַת עִמֵּיהּ וְיָתְבָא לְיָמִינָא, אִתְגַּדֵּל אִיהוּ בְּכוֹלָא.</p>"],[9514013266,"<p>וְתָּא חֲזֵי, אַבְרָהָם כַּד אָתָא לְעָלְמָא, מַה כְּתִיב בֵּיהּ, (בראשית י״ב:ב׳) וַאֲגַדְּלָה שְׁמֶךָ. מַאי הִיא, דְּאוֹסִיף בֵּיהּ הֵ\"א. וְהַאי אַתְרָא, בֵּיהּ אִתְגַּדֵּל קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (תהילים מ״ח:ב׳) גָּדוֹל ה' וּמְהֻלָל מְאֹד בְּעִיר אֱלֹהֵינוּ. כַּד הַאי קַרְתָּא קַדִּישָׁא, דְּאִקְּרֵי ה' תַּתָּאָה, אַהֲבָה זוּטָא אִתְדַּבְּקַת בֵּיהּ, וְשָׁרֵי בְּגַוָּוהּ, שְׁמֵיהּ יִתְגַּדֵּל עַל כּוֹלָא.</p>"],[9514013267,"<p>וְתָּא חֲזֵי, כְּתִיב (שם קמה) צַדִּיק ה' בְּכָל דְּרָכָיו. בְּגִין דִּבְהַאי דַרְגָּא יָהֵיב בַּיָּם דָּרֶךְ. וְחָסִיד בְּכָל מַעֲשָׂיו, בְּהַהוּא דַּרְגָּא, יָמִינָא דְמַלְכָּא אִתְעֲבֵיד בְּעָלְמָא. וְעַל דָּא, אַבְרָהָם בְּהַאי יָמִינָא, עָבִיד לֵיהּ בְּרִיָה חֲדָשָׁה, וְאִתְחַדֵּשׁ מַזָּלָא דִילֵיהּ לְאוֹלָדָא, וְאִתְגַּדֵּל עַל כּוֹלָא. וְעַל דָּא, (בראשית כ״ד:א׳) וַי\"י בֵּרַךְ אֶת אַבְרָהָם בַּכֹּ\"ל בְּהַאי בַּכֹּ\"ל, בְּרַתָּא דְמַלְכָּא דְּאִתְיְיהִיבַת לֵיהּ.</p>"],[9514013268,"<p>וּמַאי בִּרְכָתָא. מִשְׁחָא טָבָא דְּנָחִית עַל רֵאשֵׁיהּ. הֲדָא הוּא דִכְתִיב, (תהילים קל״ג:א׳) מַה טוֹב וּמַה נָּעִים. וַדַּאי. כַּשֶּׁמֶן הַטוֹב, שֶׁמֶן שַׁרְיָיא בֵּיהּ בִּרְכָתָא, דְּאַתְרָא גָּרִים. וְעַל דָּא, וַה' בֵּרַךְ אֶת אֲדוֹנִי מְאֹד, וַיִּגְדָּל כְּמָא דִכְתִיב, (בראשית כ״ד:ל״ה) וַאֲגַדְּלָה. שְׁמֶךָ, כְּמָא דִכְתִיב, (שיר השירים א׳:ג׳) שֶׁמֶן תּוּרַק שְׁמֶךָ.</p>"],[9514013269,"<p>תָּא חֲזֵי, כַּד קוּדְשָׁא בְּרִיךְ הוּא זַמִּין לַאֲרָמָא יְמִינֵיהּ עַל כּוֹלָא, בְּיוֹמֵי דִמְשִׁיחָא, בְּהַאי מִשְׁחָא טָבָא. מַאי כְּתִיב. (עמוס ט׳:י״א) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפָלֶת. הַאי יוֹם הַהוּא לָא יְדַעְנָא מַאן הוּא. אֶלָּא דָּא יוֹמָא קַדְמָאָה, יְמִינָא דְאַבְרָהָם, דְּזַמִּין לְאַתְעָרָא לְאַקְמָא לָהּ מֵעַפְרָא.</p>"],[9514013270,"<p>וְעַל דָּא בַּיּוֹם הַהוּא, יוֹמָא קַדְמָאָה דְּכֹלָא. נְאוּם ה', דָּא אַבְרָהָם, דְּאִתְּמָר עֲלוֹי נְאוּם ה' מִקַּמֵּי כּוֹלָא. דִּכְתִיב, (בראשית כ״ב:ט״ז) בִּי נִשְׁבַּעְתִּי נְאֻם ה'. וְהָכָא אִתְרְמִיז שְׁמָא דְעַתִּיקָא, דְּאוֹמֵי בֵּיהּ זְעֵיר אַנְפִּין לְאַבְרָהָם. וְעַל דָּא הַהוּא יוֹמָא, לָא יוֹם וְלָא לַיְלָה אִקְרֵי, דִּבְעַתִּיקָא תַּלְיָא, דְּבָעֵי לְאוֹקִיר דִיקְנֵיהּ. בְּהַהוּא יוֹמָא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפָלֶת.</p>"],[9514013271,"<p>משֶׁה, חָמָא כָּל אִינוּן עַקְתִין דְּזַמִּינִין לְמֵיתֵי לְעָלְמָא, כַּד הַאי סֻכָּה נוֹפָלֶת. דִּכְתִיב, (ויקרא כ״ו:כ״ד) וְהִכֵּיתִי אֶתְכֶם גַּם אָנִי, אַף אֲנָא עִמְּכוֹן בְּגָלוּתָא. וְכַד אִשְׁתַּלִּימוּ אִינוּן חוֹבִין מַאי כְּתִיב, (שם) וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכֹּר וְהָאָרֶץ אֶזְכֹּר. סָמַךְ אַרְעָא קַדִּישָׁא, סוּכַּת דָּוִד, לְאַבְרָהָם, לְאָקְמָא לָהּ בְּיָמִינָא, וְתֵיתִיב בִּשְׁלִימוּ.</p>"],[9514013272,"<p>מַאן בְּרִיתִי. דָּא אַבְרָהָם. דִּכְתִיב, (בראשית י״ז:ד׳) הִנֵּה בְרִיתִי אִתָּךְ וְהָיִיתָ לְאַב הֲמוֹן גּוֹיִם. וְכַד הַאי בְּרִית דְּאִיהִי ה' עִמָּךְ, תִּשְׁתַּלֵּים בְּכוֹלָא. וְעַל דָּא אִיתְעָרוּ חַבְרַיָיא, מַאן דְּקָרֵי לֵיהּ אַבְרָם, פָּגֵים אַתְרָא דְּאִקְרֵי עֲשֵׂה וְלֹא תַעֲשֶׂה. בְּגִין דִּבְהַאי ה', אִשְׁתְּלֵים בִּמְהֵימְנוּתָא.</p>"],[9514013273,"<p>וְכַד תִּסְתַּלֵּיק ה' בְּיָמִינָא דְאִימָא, בְּרַתָּא תְּקַבֵּל מֵאִימָא עִילָאָה, הַהוּא טוֹבָה דְּלָא אִתְפְּסַק לְעָלְמִין, וּכְדֵין עָבְדַת נוֹקְמִין לִשְׁאָר עַמִּין. וְעַל דָּא כְּתִיב, (דניאל ב׳:מ״ה) דִּי מִטוּרָא אִתְגְּזֶרֶת אֶבֶן דִּי לָא בִידַיִן. מִטוּרָא: דָּא אַבְרָהָם, טוּרָא עִילָאָה. אִתְגְּזֶרֶת אֶבֶן. דָּא אִיהוּ אֶבֶן אַחַת, דַּעֲלָהּ ז' עַיְינִין. וַעֲבָדַת דִּינִין בְּכָלְהוֹ דְּהַדִּיקוּ בְּנָהָא בֵּין רַגְלִין, הַדִּיקַת לוֹן בְּכוֹלָא. וּכְתִיב (שם) הֲוַת לְטוּר רַב וּמְלָאת כָּל אַרְעָא, בְּגִין דְּאִתְדַּבְּקַת בְּיָמִינָא, אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה.</p>"],[9514013274,"<p>וְתָּא חֲזֵי, בְּקַדְמִיתָא כַּד אָתָא אַבְרָהָם לְעָלְמָא, אִתְנְהֵירַת סִיהֲרָא. וְשָׁרַאת לְאַנְהָרָא, עַד דְּאִשְׁתְּלֵימַת בְּדַרְגָּהָא, בְּיוֹמוֹי דִשְׁלֹמֹה, דְּאִתְגַּדֵּל עַל כֹּלָא. דִּכְתִיב, (מלכים א א׳:מ״ז) וִיגַדֵּל אֶת כִּסְאוֹ מִכִּסְאֶךָ. וְעַל דָּא, (הושע ג׳:ב׳) וָאֶכְּרֶהָ לִּי בַּחֲמִשָּׁה עָשָׂר כָּסֶף, אִינוּן ט\"ו זַכָּאִין עַד שְׁלֹמֹה. וְעַל דָּא עַל יָדוֹ אִתְיְיהֵיבַת הַאי תּוּשְׁבַּחְתָּא עִילָאָה, בְּגִין דְּיִתְגַּדֵּל בָּהּ. אֲבָל דָּוִד בִּלְחִישׁוּ אִתְאֲמַר, וְלָא אִתְיְיהֵיב לֵיהּ רְשׁוּ לְגַלָּאָה.</p>"],[9514013275,"<p>(תהילים מ״ה:ב׳) אוֹמֵר אָנִי מַעֲשַׂי לְמֶלֶךְ, לְאַתְעָרָא מֶלֶךְ עִילָאָה. וּמַאי אִינוּן מַעֲשַׂי, מַאן דְּלָא תָּלֵי בֵּיהּ עוֹבָדָא מַאי עָבִיד, דְּהָא מַעֲשֶׂה לְעֵילָא תָּלֵי. אֶלָּא, מַאי מַעֲשַׂי אִלֵּין אִינוּן (שם) לְשׁוֹנִי עֵט סוֹפֵר מָהִיר. בְּגִין דְּשַׁבַּחַת בְּפַלְגוּ לֵילְיָא לְמַלְכָּא עִילָאָה. שִׁיר יְדִידוּת, כְּמָה דְאַתְּ אָמֵר שִׁיר הַשִּׁירִים, דְּשַׁבְּחָא מַטְרוֹנִיתָא לְמַלְכָּא, אוּף הָכָא מַטְרוֹנִיתָא שַׁבַּחַת לֵיהּ.</p>"],[9514013276,"<p>(שם) יָפְיָפִיתָ מִבְּנֵי אָדָם, הָא אוֹקְמוּהָ חַבְרַיָיא בְּאַבְרָהָם. נִתְיַפֵּיתָ בָּעֶלְיוֹנִים, פ (בראשית ט״ו:א׳) אָנֹכִי מָגֵן לָךְ. נִתְיַפֵּיתָ בַּתַּחְתּוֹנִים, (שם כג) נְשִׂיא אֱלֹהִים אַתָּה. לְכָךְ יָפְיָפִיתָ, תְּרֵין תּוּשְׁבְּחָן כְּלִילָן. הוּצַק חֵן בְּשִׂפְתוֹתֶיךָ, (שם יח) הִנֵּה נָא הוֹאַלְתִּי. עַל כֵּן בֵּרַכְךָ, (שם כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל.</p>"],[9514013277,"<p>אֲבָל תָּא חֲזֵי, הַאי קְרָא, רָזָא עִילָאָה אִית בֵּיהּ. לָקֳבֵיל מַלְכָּא עִילָאָה, אֲמָרֵית לֵיהּ יָפְיָפִיתָ לְעֵילָא בְּמִשַּׁרְיָין עִילָאִין, דְּאִינוּן מְשַׁבְּחָן קַמָּךְ. וּלְתַתָּא, בְּאִינוּן זַכָּאֵי קְשׁוֹט, דְּקָיְימִין בְּפַלְגּוּת לֵילְיָא. הוּצַק חֵן בְּשִׂפְתוֹתֶיךָ, בְּשַׁעֲתָא דְּאַתְּ קָרֵי וּמַקִּישׁ לִתְרַע הֵיכָלִי, פִּתְחִי לִי אֲחוֹתִי. עַל כֵּן בֵּרַכְךָ אֱלֹהִים. אִימָא עִילָאָה אִעַטְרָא לָךְ בְּעִטְרִין עִילָאִין. לְעוֹלָם, בְּגִין הַהוּא עוֹלָם בַּתְרָאָה, וּבְגִינָהּ קָאֲמַר, דְּאִיהוּ אַנְהֵיר לָהּ.</p>"],[9514013278,"<p>דָּבָר אַחֵר. לְעוֹלָם, דָּא יָמִינָא לְעֵילָא. דִּכְתִיב, (תהילים ק״י:ד׳) אַתָּה כֹהֵן לְעוֹלָם. וְכָל בִּרְכָאן וּמִשְׁחָא טָבָא שַׁרְיָין בֵּיהּ, וְאוֹקִימְנָא לֵיהּ. וְעַל דָּא כְּתִיב עַל כֵּן, כַּד הַאי כֵּן אִתְחַבְּרַת לְעֵילָא. אֲבָל בְּזִימְנָא דְּאִתְרַחֲקָא מִנֵּיהּ הַאי עוֹלָם, מַאי כְּתִיב (ירמיהו כ״ה:ל׳) שָׁאֹג יִשְׁאַג עַל נָוֵהוּ, דָּא מַטְרוֹנִיתָא, בְּגִין דְּאִתְמְנָעוֹ מִנֵּיהּ בִּרְכָאן, דְּלָא שַׁרְיָין בֵּיהּ, אֶלָּא כַּד הַאי נָוֵהוּ אִתְחַבְּרַת בֵּיהּ. וְהַאי הוּא דִכְתִיב שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. לָקֳבֵיל דָּא כְּתִיב, (שיר השירים א׳:ב׳-ג׳) כִּי טוֹבִים דּוֹדֶיךָ מִיָּיִן לְרֵיחַ שְׁמָנֶיךָ טוֹבִים, מַאי טַעְמָא, בְּגִין דְּבֵרְכֲךָ אֱלֹהִים לְעוֹלָם.</p>"],[9514013279,"<p>מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה, לָקֳבָל דָּא כְּתִיב, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר. דָּא (ישעיהו ל״ד:ו׳) חֶרֶב לַה' מָלְאָה דָּם. לְאִתְפְּרָעָא מֵחַיָּיבַיָא, דְּגָרְמִין לָהּ פִּרוּדָא מִלְּעֵילָא. קָרְבֵית יָתָהּ לְגַבָּךְ לְרַחֲמָא עָלְמָא, וְתִתְבַּסְּמוּן כַּחֲדָא.</p>"],[9514013280,"<p>וְכַד אִתְקְרִיבַת בֵּיהּ, אִתְלַבֵּשׁ בְּהוֹד וְהָדָר. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:א׳) הוֹד וְהָדָר לָבָשְׁתָּ. וּמַאי טַעְמָא, בְּגִין דְּהַהִיא שַׁעֲתָא אִתְגַּדֵּל בְּגִין דְּאִתְחַבַּר בְּעִיר אֱלֹהֵינוּ. וְעַל דָּא כְתִיב, (שם) גָּדַלְתָּ מְאֹד הוֹד וְהָדָר לָבָשְׁתָּ. בְּאִינוּן לְבוּשִׁין דִּיקָר, דְּפָרְשַׂת עֲלֵיהּ אִימָא עִילָאָה. בְּגִין כָּךְ (בראשית ל״ו:ל״ט) הֲדַר וְשֵׁם עִירוֹ פָּעוּ, אֵימָתַי, כַּד אִתְחַבְּרַת בֵּיהּ מְהֵיטַבְאֵל בַּת מַטְרֵד. וְעַל דָּא הוֹדְךָ וַהֲדָרֶךָ וַדַּאי. כְּגַוְונָא דָא, (שיר השירים א׳:ד׳) נָגִילָה וְנִשְׂמְחָה בָּךְ נַזְכִּירָה דּוֹדֶיךָ מִיָּיִן, נְגִידוּ דְּאִימָא, דְּאַשְׁקֵי לָךְ וּלְכֹלָא. וְדָא הֲוֵי הוֹדְךָ וַהֲדָרֶךָ וַדַּאי.</p>"],[9514013281,"<p>וַהֲהָרְךָ צְלַח רְכַב עַל דְּבַר אֱמֶת וְעַנְוָה צֶדֶק, לָקֳבֵיל דָּא, שְׁחוֹרָה אֲנִי וְנָאוָה. בְּקַדְמִיתָא כַּד אִתְקְרִיאַת חֶרֶב לְמֵידַן עָלְמָא, אִיתְקְרֵי שְׁחוֹרָה וַדַּאי. וְהַשְׁתָּא כַּד אִתְקְרֵיבַת לְעֵילָא בַּעֲנָוָה, אִתְקְרֵי נָאוָה. נָאוָה וַדַּאי בְּכוֹלָא. בְּנוֹת יְרוּשָׁלַיִם, אִינוּן תְּרֵיסַר חִיוָן עִילָאִין רַבְרְבָן דְּאִקְרוּן הָכֵי, וְכָלְהוֹ בִּשְׁלִימוּ. עַל דַּהֲווֹ הַשְׁתָּא בְּגָלוּתָא כְּאָהֳלֵי קֵדָר, אִתְהַדְּרוּ אִינוּן הַשְׁתָּא כִּירִיעוֹת שְׁלֹמֹה וַדַּאי.</p>"],[9514013282,"<p>וְתָּא חֲזֵי, כֵּיוָן דְּהַהִיא חַרְבָּא אִסְתַּחֲרַת מִדִּין דְּהֲוָה בָהּ, דְּאַכְשְׁרוּ בְּנֵי עָלְמָא עוֹבָדַיְיהוּ. אִתְעֲבִידַת דָּבָר, דְּבַר אֱמֶת, וְאִתְחַבָּרַת בֶּאֱמֶת. וֶאֱמֶת בַּעֲנָוָה. וּכְדֵין צֶדֶק בְּכֹלָא וְכוֹלָא חַד.</p>"],[9514013283,"<p>סוֹפָא בְּרֵישָׁא דְּבַר אֱמֶת. אֱמֶת בְּרֵישָׁא, דִּכְתִיב (תהילים קי״ט:ק״ס) רֹאשׁ דְּבָרְךָ אֱמֶת. רֵישָׁא דְּהַהוּא דְּאִקְרֵי דְּבָרְךָ, סֵיפָא דְדַרְגִּין, אֱמֶת אִקְרֵי. רֵישָׁא בְּסוֹפָא, עֲנָוָה צֶדֶק בְּלָא פִּירוּדָא, אִתְכְּלִילוּ וְאִתְחַבָּרוּ בְּכוֹלָא. עֲנָוָה רֵישָׁא, צֶדֶק סוֹפָא, (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת ה'.</p>"],[9514013284,"<p>וְתוֹרְךָ נוֹרָאוֹת יְמִינֶךָ, דָּא יַעֲקֹב, דְּנָטֵיל תְּרֵין חוּלָקִין בְּגִין דְּאִתְדַּבַּק בְּיָמִינָא לְעָלְמִין, דִּכְתִיב (בראשית ל׳:ל״ז) מַחְשׂף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת.</p>"],[9514013285,"<p>וּבְהַהִיא שַׁעֲתָא, כּוֹלָא אִתְהַדַּר כִּירִיעוֹת שְׁלֹמֹה. בְּגִין דְּסִטְרָא דְיָמִינָא אִיתְעַר בְּעָלְמָא, וִידָא יְמִינָא פְּשׁוּטָה לְקַבֵּל לִדְתָיְיבִין בִּתְיוּבְתָּא. דְּהָא עַד הַשְׁתָּא אִתְקַדָּרוּ בְּחוֹבַיְיהוּ כְּאָהֳלֵי קֵדָר, וְהַשְׁתָּא דְּהַדְּרִין בִּתְיוּבְתָּא אִינוּן כִּירִיעוֹת שְׁלֹמֹה, בְּגִין דְּאַבְרָהָם אִיתְעַר בְּעָלְמָא, יָמִינָא דְמַלְכָּא.</p>"],[9514013286,"<p>חִצֶּיךָ שְׁנוּנִים, אוֹקְמוּהָ עַל אַבְרָהָם, כַּד רָדַף בָּתַר כָּל אִינוּן מַלְכִין בְּלֵילְיָא, כַּד אִתְפַּלְגוּ רַחֲמִין מִדִּינָא, וְקָטַל אִינוּן מַלְכִין. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״א:ב׳-ג׳) כְּקַשׁ נִדָּף קַשְׁתּוֹ יִרְדְּפֵם יַעֲבוֹר שָׁלוֹם. וְנָפְלוּ כָּלְהוֹ בִּידֵיהּ.</p>"],[9514013287,"<p>אֲבָל תָּא חֲזֵי, רָזָא דְמִלָּה. חִצֶּיךָ שְׁנוּנִים, אִלֵּין חִצִּים וְאַבְנֵי בְּלִיסְטְרָאוֹת. דְּדָנַת עָלְמִין, בְּאִינוּן מָאנֵי קְרָבָא, דְּמַלְכָּא דְּאַפְקֵיד בִּידָא דְּמַטְרוֹנִיתָא. וְאִינוּן חִצִּים דְּקוּדְשָׁא בְּרִיךְ הוּא, שְׁנוּנִים וַדַּאי בְּכוֹלָא, מִסִּטְרָא דְּיוֹמָא תִּנְיָינָא, סִטְרָא דְיִצְחָק, בְּגִין דְּמִנֵּיהּ נָפַק דִּינָא לְחַיָּיבַיָא לְמֵידַן יַתְהוֹן.</p>"],[9514013288,"<p>וְעַל דָּא עַמִּים תַּחְתֶּיךָ יִפְּלוּ בְּל\"ב. וּמַאן הוּא דַרְגָּא דְּאַפִּיל לוֹן, דַּרְגָּא דְּאִקְרֵי ל\"ב, דְּאִתְמַנָּא עַל עוֹבָדִין דְּעָלְמָא, וְדָנַת לוֹן עַל דְּאִינוּן אוֹיְבֵי הַמֶּלֶךְ.</p>"],[9514013289,"<p>לָקֳבֵיל דָּא אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. מַאי טַעְמָא, בְּגִין דְּאִתְלַבַּשְׁנָא בְּדִינָא לְמֵידַן עַלְמָא. וַאֲמָרַת לִבְנָהָא דִּקְרֵיבִין לָהּ גּוֹ בֵיתָא, אַל תִּרְאוּנִי. וַדַּאי, אִי אִשְׁתַּדַּלְתּוּן בְּאוֹרַיְיתָא דְּיַהֲבֵית לְכוֹן, לָא תִדְחֲלוּן. וְאִי לָא תִּשְׁתַּדַּלְתּוּן, תִּגְרְמוּן לִי, דִּבְנֵי אִמִּי נִחֲרוּ בִי, לְמִיטַר לְאוּמִין דְּעַלְמָא בְּגִינֵיכוֹן דְּתִתְבַּדְּרוּן תַּמָּן. וְעַל דָּא אִיתְעָרוּ, אִי דִינָא אִיתְגְּזַר עַל יִשְׂרָאֵל, קוּדְשָׁא בְּרִיךְ הוּא נָחִית לֵיהּ עַל שְׁאָר אוּמִין, כַּד הַדְּרָן יִשְׂרָאֵל בִּתְיוּבְתָּא. וְאִי לָא הַדְּרָן, נַחֲתִין בֵּין שְׁאָר אוּמִין, וְאָכְלִין לוֹן גְּרָמָא וּבִשְׂרָא.</p>"],[9514013290,"<p>דָּבָר אַחֵר, בְּלֵב אוֹיְבֵי הַמֶּלֶךְ, דָּא אַבְרָהָם, דְּאִתְמַנָּא מַלְכָּא עַל עָלְמָא, וְכָל אוּמִין אִסְתַּכְּמוּ עֲלוֹי לְמֶהֱוֵי מַלְכָּא עֲלֵיהוֹן, בְּעֵמֶק שָׁוֵה. וְכָל שַׂנְאוֹי לֵילְיָא קְטֵילַת לוֹן.</p>"],[9514013291,"<p>דָּבָר אַחֵר חִצֶּיךָ שְׁנוּנִים, דְּאִינוּן זְמִינִין לְמֵיעְבַּד דִּינָא. עַמִּים תַּחְתֶּיךָ יִפְּלוּ, אִלֵּין דְּאָתוֹ מִסִּטְרָא דִּשְׁאָר עַמִּין, תַּחְתֶּיךָ יִפְּלוּ, סִטְרָא דְנָחָשׁ, כַּד הַהוּא שַׁלְהוֹבָא דְּסִטְרָא דְצָפוֹן אִיתְעַר עֲלֵיהּ, אִיהוּ נָפִיל בְּעֵמֶק יַמָּא עִילָאָה, וְאִתְבַּר חֵילֵיהּ. וְכַד חֵילֵיהּ אִתְבַּר, חֵילָא דִּשְׁאָר עַמִּין אִתְבַּר, בְּגִין דְּאִינוּן אוֹיְבֵי הַמֶּלֶךְ. מַאי מֶלֶךְ, דָּא יִשְׂרָאֵל, מַלְכָּא בְּכוֹלָא.</p>"],[9514013292,"<p>(תהילים מ״ה:ז׳) כִּסְאֲךָ אֱלֹהִים עוֹלָם וָעֶד, עֲלָה קָאָמַר הָכֵי, כְּאִתְּתָא דְּאִיתְעֲרָא לְבַעֲלָהּ, וַאֲמָרַת אִינְתְּתָךְ בַּעְיָיא לְאִתְחַבְּרָא בָּךְ, דְּהָא אִינוּן חַיָּיבִין דְּאַפְרִידוּ זִוּוּגָא דִילָן, אִתְאֲבִידוּ מֵעָלְמָא, וַעֲבֵידַת בְּהוּ דִּינָא. וְהַשְׁתָּא בָּעֵינָא, דְּיִתְחַבַּר עוֹלָם בַּתְרָאָה, בְּאַתְרָא דְאִיקְרֵי וָעֶד. בְּגִין דְּשֵׁבֶט מִישׁוֹר שֵׁבֶט מַלְכוּתֶךָ, דְּהַהוּא דִּינָא דַּעֲבָדַת כִּסְאֲךָ בְּחַיָּיבֵי עָלְמָא, דִּינָא דִקְשׁוֹט הוּא, דְּנָפֵיק מֵאַתְרָא דְאִקְּרֵי יָשָׁר. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ד׳) צַדִּיק וְיָשָׁר הוּא. וְכוּרְסְיָיא אִקְרֵי יָשָׁר, וְעַל דָּא דְּנָפִיק מִינֵיהּ שֵׁבֶט מִישׁוֹר אִיקְרֵי.</p>"],[9514013293,"<p>דָּבָר אַחֵר שֵׁבֶט מִישׁוֹר, דָּא מַלְכָּא מְשִׁיחָא, דְּאִיקְרֵי שֵׁבֶט לְאוֹכָחָא חַיָּיבֵי עָלְמָא. הֲדָא הוּא דִכְתִיב, (בראשית מ״ט:י׳) לֹא יָסוּר שֵׁבֶט מִיהוּדָה וּכְתִיב (במדבר כ״ד:י״ז) וְקָם שֵׁבֶט מִיִּשְׂרָאֵל. מִישׁוֹר, (ישעיהו י״א:ד׳) וְהוֹכִיחַ בְּמִישׁוֹר לְעַנְוֵי אָרֶץ. שֵׁבֶט מַלְכוּתֶךָ, עַל דָּא כְתִיב, וְקָם שֵׁבֶט מִיִּשְׂרָאֵל לְאַתְעָרָא בְּעָלְמָא. מַאי טַעְמָא, דְּהָא אֲפֵיקַת לָךְ בְּרָא טָבָא חַכִּימָא לְעָלְמָא. וְהַאי שִׁבְחָא מְשַׁבַּחַת מַטְרוֹנִיתָא לְמַלְכָּא לַאֲרָמָא רֵישָׁא דְיִשְׂרָאֵל עַל כּוֹלָא. לֹא יָסוּר שֵׁבֶט, בְּגִין דִּכְתִיב (תהילים פ״ט:ל״ז) כִּסְּאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי.</p>"],[9514013294,"<p>אָהַבְתָּ צֶדֶק, בְּגִין דְּהַאי צֶדֶק, אַהֲבָה דִידָךְ, הִיא אַהֲבָה זוּטָא. דִּבְאִתְחַבְּרוּתָה לְעֵילָא אִיתְעֲבִידָא רַבְרְבָא. וְאוֹף אִיהוּ נָמֵי בְּאִתְחַבְּרוּתֵיהּ עִמָּהּ, אִיהוּ גָדוֹל. הֲדָא הוּא דִכְתִיב, (שם מח) גָּדוֹל ה' וּמְהֻלָּל מְאֹד בְּעִיר אֱלֹהֵינוּ. וְעַל דָּא מָשְׁכָא לֵיהּ מַטְרוֹנִיתָא, בְּמִלִּין אִלֵּין דִּרְחִימוּ.</p>"],[9514013295,"<p>לָקֳבֵל דָּא, (שיר השירים א׳:ז׳) הַגִּידָה לִי שֶׁאָהֲבָה נַפְשִׁי. אַנְתְּ, דְּכָל רְחִימוּ דְּנַפְשָׁאי בָּךְ, אִי לָא תִתְחַבַּר בִּי, אֵיכָה תִרְעֶה עָלְמָא, אֵיךְ תָּזוֹן נַפְשְׁךָ מֵעוֹמְקָא עִילָאָה, לָךְ, וּלְאַחֲרִינֵי, דְּהָא בִּרְכָאן דִּלְעֵילָא לָא שַׁרְיָין, אֶלָא בְּאַתְרָא דִּדְכַר וְנוּקְבָא.</p>"],[9514013296,"<p>שַׁלָּמָה אֶהְיֶה כְּעֹטְיָה. אֵיכְדֵין אֱהֵא בִּכְסִיפָא, כַּד תָּבְעִין מִינִי מְזוֹנָא בְּנֵי אֲבָהָן, דְּאִינוּן עֶדְרֵי חֲבֵרֶיךָ, עֵדֶר ה' מַמָּשׁ. בְּגִין כָּךְ אָהַבְתָּ צֶדֶק, דָּא כּוּרְסְיָיא דִּילָךְ. וַתִּשְׂנָא רֶשַׁע, דָּא סִטְרָא דְּשִׁפְחָה, דְּכָל מִילָהָא בְּחִיּוּבָא, וְקָיְימָא לְחִיּוּבָא עַל עָלְמָא.</p>"],[9514013297,"<p>דָּבָר אַחֵר, אַף עַל גַּב דְּכֹלָא חַד, אָהַבְתָּ צֶדֶק, אִלֵּין יִשְׂרָאֵל דַּאֲחִידָן בְּהַאי צֶדֶק, וְאִיהִי חוּלָקֵיהוֹן, דִּכְתִיב (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם וכו', וָאֹהַב אֶת יַעֲקֹב. לְאַסְגָּאָה דַּרְגָא דְּצֶדֶק, דְּאָחִיד בָּהּ בְּשַׁעֲתָא דְּאִיקְרֵי יַעֲקֹב. וַתִּשְׂנָא רֶשַׁע, דָּא עֵשָׂו, דְּכָל עוֹבָדוֹי בְּחִיּוּבָא, וְסִטְרָא דִילֵיהּ סִטְרָא דְּרָשָׁע, חִוְיָא עֲקִימָא. הֲדָא הוּא דִכְתִיב, (שם) וְאֶת עֵשָׂו שָׂנֵאתִי. עַל כֵּן מְשָׁחֲךָ אֱלֹהִים אֱלֹהֶיךָ שֶׁמֶן שָׂשׂוֹן, דָּא מִשְׁחָא טָבָא, דְּנָגֵיד עַל רֵישָׁךְ מִסִּטְרָא עִילָאָה, דְּאִקְרֵי הָכֵי. מַאי עַל כֵּן. בְּגִין דְּאָהַבְתָּ צֶדֶק.</p>"],[9514013298,"<p>הֲדָא הוּא דִכְתִיב, (תהילים קל״ג:א׳) הִנֵּה מַה טוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. שֶׁבֶת אַחִים, אִתְחַבְּרוּתָא דְּאָח בְּצֶדֶק. גַּם, לְאַסְגָּאָה לְיִשְׂרָאֵל. בְּגִין כָּךְ אֲמָרַת לֵיהּ, אֵיכָה תִרְעֶה לְגַרְמָךְ. אֵיכָה תַרְבִּיץ, אִינוּן עֲדָרִין קַדִּישִׁין דְּיַעֲקֹב. מֵחֲבֵרֶיךָ, אִלֵּין אֲבָהָן עִילָאִין, דְּאִתְחַבָּרוּ בָּךְ בְּקַדְמִיתָא.</p>"],[9514013299,"<p>דָּבָר אַחֵר, יִשְׂרָאֵל דְּאִינוּן אַחִים וְרֵעִים לֵיהּ, נַגְדִין לְהַאי שֶׁמֶן שָׂשׂוֹן עַל רֵישֵׁיהּ, בִּצְלוֹתְהוֹן. שֶׁמֶן שָׂשׂוֹן, אִלֵּין תְּרֵיסַר נַהֲרֵי אֲפַרְסְמוֹנָא דַכְיָיא, דְּנָהֲרִין בָּהּ. וּכְדֵין חֶדְוָה בְּעָלְמִין, רָצוֹן בְּעָלְמִין, וְרוֹגְזָא אִסְתַּלַּק מֵעָלְמָא.</p>"],[9514013300,"<p>מֹר וַאֲהָלוֹת, מֹר: דָּא אַבְרָהָם, דְּאִקְּרֵי הַר הַמֹּר. וַאֲהָלוֹת: דָּא יַעֲקֹב. קְצִיעוֹת: דָּא יִצְחָק. כָּל בִּגְדוֹתֶיךָ: בְּאִלֵּין תְּלַת גְּוָונִין, חִיוַו\"ר וְסוּמָ\"ק וְיָרוֹ\"ק, אִשְׁתַּלִּימוּ אִינוּן לְבוּשֵׁי דְּאַרְגְּוָונָא.</p>"],[9514013301,"<p>מִן הֵיכְלֵי שֵׁן, אִלֵּין שִׁבְעָה הֵיכָלִין עִילָאִין, דְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָיא חָדָאן בְּהוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וּכְדֵין חֶדְוָה קַמֵּיהּ. וְאַמַּאי אִיקְרוּן הֵיכְלֵי שֵׁן, בְּגִין דְּזָכוּ בְּאוֹרַיְיתָא, וְאִתְתַּקְפ\"וּ בָּהּ, זָכוּ לְהַאי שֵׁ\"ן.</p>"],[9514013302,"<p>מִנִּי שִׂמְּחוּךָ, בְּמַאי עָסְקִין אִינוּן נִשְׁמָתִין. אִינוּן עָסְקִין בְּתֻשְׁבְּחָאן דִּידִי קַמָּךְ. וּכְדֵין חֶדְוָה קַמָּךְ אִשְׁתַּלִּימַת, דְּלֵית חֶדְוָה קַמֵּיהּ מִכָּל רְתִיכִין דִּילֵיהּ, כְּחֶדְוָה דְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָּיא דְּאִינוּן קְרִיבִין לֵיהּ.</p>"],[9514013303,"<p>דָּבָר אַחֵר, מִנִּי שִׂמְּחוּךָ, וַדַּאי דְּלֵית חֶדְוָה קַמֵּיהּ, כְּזִמְנָא דְּעָבַד שְׁלֹמֹה שִׁיר הַשִּׁירִים. וְשַׁבַּח תּוּשְׁבְּחָאן דְּמַטְרוֹנִיתָא לְמַלְכָּא.</p>"],[9514013304,"<p>וּמַאי אָמְרִין. בְּנוֹת מְלָכִים בִּיקְרוֹתֶיךָ. בְּנוֹת מְלָכִים: אִלֵּין נִשְׁמָתִין קַדִּישִׁין, דְּאִקְּרוּן וַדַּאי בְּנוֹת מְלָכִים, דְּהָא מִזִּוּוּגָא דְמַלְכָּא וּמַטְרוֹנִיתָא הֲווֹ אִינוּן. בִּיקְרוֹתֶיךָ: דָּא גַּן עֵדֶן, דְּיַקִּיר מִכָּל מַה דִּבְרָא קוּדְשָׁא בְּרִיךְ הוּא בְּהַאי עָלְמָא דְּאִינוּן נְטִיעָן דִּידוֹי.</p>"],[9514013305,"<p>נִצְּבָה שֵׁגָל לִימִינְךָ, כְּמָה דְאַתְּ אָמֵר, (שם קי) נְאֻם ה' לַאדֹנִי שֵׁב לִימִינִי. בְּגִין כָּךְ לְתַתָּא, בְּאַבְרָהָם אִתְדַּבְּקַת, וּבְגִין כָּךְ אִיקְרֵי אַבְרָהָם אוֹהֲבִי, דְּאִתְדַּבְּקַת בֵּיהּ אַהֲבָה דִילִי. וְאוֹדַע דִּינִי לְעָלְמָא, וּבְגִינָהּ זָכָה לְבֵן, דְּהָא ה\"א אִיתּוֹסְפַת עֲלוֹי מִקַּדְמַת דְּנָא.</p>"],[9514013306,"<p>בְּכֶתֶם אוֹפִיר, כְּמָה דְאַתְּ אָמֵר, (ישעיה יג) וְאָדָם מִכֶּתֶם אוֹפִיר, וְאֵימָתַי הוּא בְּכֶתֶם אוֹפִיר. כַּד אִזְדַּוְּוגָא בְּמַלְכָּא, כַּד נָחִית כִּתְרָא בְּדִלּוּגִין, דְּאַנְהֵיר מִסִּטְרָא דְּאִימָא עִילָאָה, וְשַׁרְיָא עַל רֵישָׁא דְּמַטְרוֹנִיתָא, וּכְדֵין (שם מד) תִּפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת. דְּהָא בֵּיתָא דְּהַאי עָלְמָא, עַל יָדָהּ אִתְנְהִיגַת.</p>"],[9514013307,"<p>בְּגִין כַּךְ אָמְרָה לֵיהּ, אִם לֹא תִתְחַבֵּר בִּי, אֵכְדֵין אֶהֱוֵי בְּצַחוּתָא עַל אִינוּן עֲדָרִין קַדִּישִׁין, דְּסָמְכִין עַל פָּתוֹרִי. הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ז׳) שַׁלָּמָה אֶהְיֶה כְּעוֹטְיָה עַל עֶדְרֵי חֲבֵרֶיךָ.</p>"],[9514013308,"<p>קוּדְשָׁא בְּרִיךְ הוּא מָה אָתֵיב לָהּ, (תהלים מה) שִׁמְעִי בַת וּרְאִי. לָקֳבֵיל דָּא, אִם לֹא תֵדְעִי לָךְ הַיָּפָה בַּנָּשִׁים צְאִי לָךְ בְּעִקְבֵי הַצֹּאן וּרְעִי אֶת גְּדִיּוֹתַיִךְ. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, הָא עֵיטָא עִילָאָה לָךְ, צְאִי לָךְ בְּעִקְּבֵי הַצֹּאן, אִלֵּין זַכָּאִין שְׁלֵימִין דְּאִתְעַטְרַת בְּהוּ קֳדָמַי, וּרְעִי אֶת גְּדִיּוֹתַיִךְ אִינוּן דְּאִתְמַשְּׁכִין אֲבַתְרָךְ.</p>"],[9514013309,"<p>וְאִינוּן חַיָּיבֵי דָרָא, יִתְמַשְׁכְּנוּן בְּחוֹבַיְיהוּ, אַלְקֵי יַתְהוֹן בִּרְצוּעָא, וְלָא יוֹסִפוּן לְמֶחֱטֵי. וְתִטְרֵי בְּנָיךְ דְּאָזְלִין אֲבַתְרָיךְ, דְּלָא יִתְמַשְׁכְּנוּן עֲלֵיהוֹן, וְכוֹלָא בְּדִינָא דִקְשׁוֹט. מַאי טַעְמָא. דְּכָל הַנְּשָׁמוֹת קֳדָמַי אִינוּן, וְעַל דָּא (יחזקאל יח) בֵּן לֹא יִשָּׂא בַּעֲוֹן הָאָב וְאָב לֹא יִשָּׂא בַּעֲוֹן הַבֵּן.</p>"],[9514013310,"<p>כְגַוְונָא דָא שִׁמְעִי בַת וּרְאִי. שִׁמְעִי, דְּבָךְ תַּלְיָא שְׁמִיעָה, כַּד יִשְׂרָאֵל אֲהַדְּרִין בִּתְיוּבְתָּא קַמָּאי, שִׁמְעִי, אָעֵיל צְלוֹתְהוֹן קֳדָמַי, דְּפִתְחָא דְּכֹלָּא בָּךְ הוּא, כּוֹלָא מְסָרִית בִּידָךְ לְאַנְהָגָא עַלְמָא תַּתָּאָה. וְעַל דָּא שִׁמְעִי בַת וּרְאִי, בְּגִין דְּאַתְּ חֵיזוּ דְּכוֹלָא, אַתְּ אִתְקְרִיאַת בְּאֵר לַחַי רוֹאִי. בְּגִין כָּךְ אִית לָךְ לְעַיְינָא כָּל יוֹמָא בְּעוֹבָדֵיהוֹן דְּעָלְמָא, לְמֵיהַב לְבַר נָשׁ כְּפִי עוֹבָדוֹי.</p>"],[9514013311,"<p>תָּא חֲזֵי, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, מַנֵּי הֵיכָלֵיהּ בִּידָא דְּמַטְרוֹנִיתָא לְעַיְינָא עַל עָלְמָא. וְכַד בְּנֵי עָלְמָא זַכָּאִין, חֶדְוָה אִתּוֹסֵיף לְעֵילָא.</p>"],[9514013312,"<p>וְהַטִי אָזְנֵךְ, לָקֳבֵל צְלוֹתָא דְכוֹלָא. וְכֵן עֲבָדַת אוּף אִיהִי מִכָּל צְלוֹתִין, לְקָרְבָא עֲטָרָה לַצַּדִּיק. בְּגִין דְּהָא כָּל צְלוֹתִין, לְקָרְבָא עֲטָרָה לַצַּדִּיק הוּא.</p>"],[9514013313,"<p>וְשִׁכְחִי עַמֵּךְ, דְּכַד בָּנַי לָא אָזְלִין בְּאוֹרַח מֵישָׁר, אִית לָךְ לְאַיְיתָאָה עֲלֵיהוֹן מָחָאן. כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ו:כ״ד) וְהִכֵּיתִי אֶתְכֶם גַם אָנִי שֶׁבַע. וְעַל דָּא וְשִׁכְחִי עַמֵּךְ, עָבִיד יַתְהוֹן כְּאִלּוּ הֵם שְׁכוּחִין מֵעָלְמָא, עַד דִּיתוּבוּן בִּתְיוּבְתָּא קַמָּאי. וּבֵית אָבִיךְ, דְּאִיהוּ אַבְרָהָם, דְּאִיהִי בְּרַתֵּיהּ, וּבַכֹּל שְׁמָהּ.</p>"],[9514013314,"<p>וְיִתְאָו הַמֶּלֶךְ יָפְיֵךְ, דָּא מַלְכָּא עִילָאָה, דְּרָחִים לְאִתְדַּבְּקָא בָּךְ, וּלְאִזְדַּוֵּוג בָּךְ זִוּוּג עָלְמִין. אֵימַת, בְּשַׁעֲתָא דְּכָל בְּנֵי הֵיכָלָא דְמַלְכָּא זַכָּאִין. בְּשַׁעֲתָא דְּיָסַרְתְּ לוֹן, וְדַבַּרְתְּ לוֹן לִרְעוּתָא דְמַלְכָּא. הֲדָא הוּא דִכְתִיב, (משלי ל״א:א׳) מַשָּׂא אֲשֶׁר יִסְרַתּוּ אִמּוֹ. וְדָא בַּת שֶׁבַע אֵם שְׁלֹמֹה, דְּדַּבְּרַת לֵיהּ לִרְעוּתָא דְמַלְכָּא.</p>"],[9514013315,"<p>כִי הוּא אֲדֹנַיִךְ, כָּל חֵילָא דִידָךְ מִנֵּיהּ הוּא. סִיהֲרָא לָא אִתְנְהֵירַת אֶלָּא מִשִּׁמְשָׁא. שְׁמָה דִּילָהּ אדנ\"י, סִימָנָא נָקְטַת מִבֵּי מַלְכָּא. א' מֵרֵישָׁא דְּכוֹלָא לְאִתְנַהֲגָא בָּהּ. וְי' רֵישָׁא דִּשְׁמָא קַדִּישָׁא, חָכְמָה עִילָאָה.</p>"],[9514013316,"<p>וְהִשְׁתַּחֲוִי לוֹ, כְּמָה דְאַתְּ אָמֵר (מלכים א א) וַתִּקֹּד בַּת שֶׁבַע. וּכְדֵין מַלְכָּא עָבִיד כָּל רְעוּתָהּ. וְיִשְׂרָאֵל מִתְגַּבְּרִין לְעֵילָא לְעֵילָא. וּמְדוֹרַיְיהוּ עִם מַלְכָּא וְעִם מַטְרוֹנִיתָא.</p>"],[9514013317,"<p>כְדֵין שְׁאָר עַמִּין אִתְכַּפְיָין תְּחוֹתַיְיהוּ, וְכָלְהוֹ אִתְהַדְּרוּן לְעָבְדִין לוֹן, בְּגִין דְּאִינוּן בְּנֵי מַלְכָּא. בְּגִין כָּךְ (תהלים מה) וּבַת צוֹר בְּמִנְחָה פָּנַיִךְ יְחַלּוּ עֲשִׁירֵי עָם.</p>"],[9514013318,"<p>לָקֳבֵיל דָּא, לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִיתִיךְ רַעְיָתִי. דְּקוּדְשָׁא בְּרִיךְ הוּא יָהֵיב בְּלִבֵּיהּ לְמֵיעַל בַּתְרַיְיהוּ לְיַמָּא, בְּגִין דְּיִשְׂבְּעוּן יִשְׂרָאֵל מִמָּמוֹנֵיהוֹן, דְּאוֹבִילוּ עִמְּהוֹן תַּמָּן. וְכוֹלָא נָטְלוּ יִשְׂרָאֵל בְּיַמָּא, אַגְרָא דְּהַהוּא עֲבִידְתָּא דַּעֲבָדוּ עִמְּהוֹן.</p>"],[9514013319,"<p>כְגַוְונָא דָא לְזִמְנָא דְּאָתָא, וּבַת צוֹר, דָּא סִטְרָא דְעֵשָׂו וּשְׁאָר עַמִּין דְּאָעְקוּ לְיִשְׂרָאֵל, וְעַד הַשְׁתָּא הֲווֹ אָעְקִין לוֹן בְּחוֹבַיְיהוּ. כְּמָה דְאַתְּ אָמֵר, (ישעיה נט) כִּי יָבוֹא כַנָּהָר צָר רוּחַ ה' נֹסְסָה בוֹ.</p>"],[9514013320,"<p>כְהֵין, יִשְׂרָאֵל יְהַדְּרוּן בִּתְיוּבְתָּא שְׁלֵימָתָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְחֲזֵי בְּאִינוּן עָקְתִין סַגִּיאִין דְּאַתְיָין עֲלַיְיהוּ, כְּמַאן דְּאִשְׁתַּכַּח דּוּכְרָנֵיהוֹן לְעֵילָא. וְכַד אִינוּן הַדְּרָן בִּתְיוּבְתָּא בְּלִבָּא שְׁלֵימָא, כְּגַוְונָא דִּכְתִיב (דברים ד) בַּצַּר לְךָ וּמְצָאוּךָ וְגו', וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ. וְיָשׁוּב מַלְכָּא לְבֵי מַטְרוֹנִיתָא לְפַיְיסָא לָהּ. וְעַל דָּא י (ישעיה נט) וּבָא לְצִיּוֹן גּוֹאֵ\"ל, דָּא מַלְכָּא דְּאָתֵי לְבֵי מַטְרוֹנִיתָא. בְּגִין דְּבֵיתָהּ כָּלְהוֹ שְׁלֵמִין קַמָּהּ, אָתֵי לְאַקְמָא לָהּ מֵעַפְרָא.</p>"],[9514013321,"<p>בְּמִנְחָה פָּנַיִךְ יְחַלּוּ עֲשִׁירֵי עָם, בְּגִין דְּאַתְּ (תהלים מה) כְּבוּדָה בַת מֶלֶךְ פְּנִימָה. וּמַאי כְּבוּדָה. כְּבוֹד ה'. וְדָא בַּת מֵהַהוּא מֶלֶךְ דְּאִיהִי פְּנִימָה וַדַּאי. וְדָא אִימָא עִילָאָה, דְּאִיהִי פְּנִימָה דְּכֹלָּא, וְאִיהִי אִיתְעָרַת חֵירוּ וְנַיְיחָא עַל בְּנָאָה.</p>"],[9514013322,"<p>(שם) מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, לָקֳבֵיל דָּא אָמַר שְׁלֹמֹה, (שיר השירים א׳:י׳) נָאווּ לְחָיַיִךְ בַּתּוֹרִים צַוָּארֵךְ בַּחֲרוּזִים. לְחָיַיִךְ תְּרֵין. לְזִמְנָא הַהוּא, וּלְזִמְנָא דְאָתֵי. בַּתּוֹרִים תְּרֵין תּוֹרִים וַדַּאי. בְּגִין דִּבְיוֹמָא דִמְשִׁיחָא תִּתְחַדֵּשׁ דַּעְתָּא בְּעָלְמָא, וְתִתְנְהֵיר אוֹרַיְיתָא קַמֵּי כּוֹלָא. בְּגִין דִּכְתִיב, (ירמיהו ל״א:ל״ד) כִּי כוּלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם. וְעַל דָּא, מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ, דָּא סִיטְרָא דְצָפוֹן, דְּאִתְלְבִישַׁת בָּהּ לְמֶעְבַּד נוּקְמִין, בְּאִינוּן דְּאָעְקִין לִבְנָהָא. וְעַל דָּא קָרִינָן לֵיהּ מֶלֶךְ הַמָּשִׁיחַ, וְדָוִד וַדַּאי הוּא. וּכְדֵין אִיתְעַר בְּעָלְמָא.</p>"],[9514013323,"<p>מַה כְּתִיב לְעֵיל. (תהילים מ״ד:כ״ו) כִּי שָׁחָה לֶעָפָר נַפְשֵׁנוּ כו' קוּמָה עֶזְרָתָה לָנוּ. מַאי קוּמָה. בְּגִין דְּעַד הַשְׁתָּא אִיהִי נוֹפֶלֶת, הַשְׁתָּא קוּמָה עֶזְרָתָה לָנוּ, דְּאִתְדַּבַּק מַלְכָּא בְּמַטְרוֹנִיתָא. וּפְדֵנוּ לְמַעַן חַסְדֶּךָ. דָּא אַבְרָהָם, יָמִינָא, דְּלָא תֶּהֱוֵי לַאֲחוֹרָא. דְבְּגִין כָּךְ אָמַר, (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי. בְּגִין כָּךְ, מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ.</p>"],[9514013324,"<p>לִרְקָמוֹת: אִלֵּין לְבוּשִׁין דִּיקָר, דְּאִינוּן מְרוּקָמִין לְמַקְדְּשָׁא. וְכָל מָנוֹי דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִלְבַּשׁ, לְמֵיהַב נוּקְמְתָא בֶּאֱדוֹם. תּוּבַל לַמֶּלֶךְ, דָּא כַּלָּה אַלְבִּישַׁת לֵיהּ. מַאן גָּרַם כָּל דָּא. בְּגִין דְּיִשְׂרָאֵל לָא אִתְעָרְבוּ בְּסִטְרָא דְעֵשָׂו, כָּל אִינוּן זְמִינִין לְמֶחֱמֵי בִּיקְרָא דְצִיּוֹן.</p>"],[9514013325,"<p>לָקֳבֵיל דָּא תּוֹרֵי זָהָב נַעֲשֶׂה לָךְ. תּוֹרֵי, תְּרֵין. רֶמֶז לְאוֹרַיְיתָא דְּאִתְיְיהֵיב בִּימֵי פַּרְעֹה. וְרֶמֶז לְדַעְתָּא דְּתִתְחַדֵּשׁ בְּיוֹמוֹי דִמְשִׁיחָא. עִם נְקוּדוֹת הַכָּסֶף. הָתָם, (הושע ג׳:ב׳) בַּחֲמִשָּׁה עָשָׂר כָּסֶף. וְהָכָא, (שה\"ש ח) אִם חוֹמָה הִיא נִבְנֶה עָלֶיהָ טִירַת כָּסֶף, וַדַּאי מִסִּטְרָא דְּאַבְרָהָם אַתְיָא לוֹן הַאי. הֲדָא הוּא דִכְתִיב, (ויקרא כ״ו:מ״ב) וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכֹּר וְהָאָרֶץ אֶזְכֹּר.</p>"],[9514013326,"<p>(תהילים מ״ה:ט״ז) תּוּבַלְנָה בִּשְׂמָחוֹת וָגִיל, תְּרֵין חֶדְוָון, לְעֵילָא וּלְתַתָּא. לְעֵילָא, דִּשְׁמָא קַדִּישָׁא וְכוּרְסְיָיא אִשְׁתְּלֵים, כַּד אִתְאֲבֵיד יוֹדֵעַ צַיִד מֵעָלְמָא, וְדוּכְרָנֵיהּ לְעָלְמִין לָא אִידְכַּר. לְתַתָּא, יִשְׂרָאֵל בְּנוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּרַחֲמִין עִילָאִין אָרֵים דִּגְלֵיהוֹן עַל כּוֹלָא. וְעַל דָּא מוּבָאוֹת לָךְ. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה'. וְעַל דָּא כְּתִיב תְּבֹאֶינָה בְּהֵיכַל מֶלֶךְ.</p>"],[9514013327,"<p>(תהילים מ״ה:י״ז) תַּחַת אֲבוֹתֶיךָ יִהְיוּ בָנֶיךָ. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא לִכְנֶסֶת יִשְׂרָאֵל, תַּחַת אֲבוֹתֶיךָ, אִינוּן אֲבָהָן עִילָאִין, דְּאוֹדִיעוּ לָךְ בְּעָלְמָא, וְאַתְקִינוּ לָךְ, עַל כּוֹלָא יִהְיוּ בָנֶיךָ. תְּשִׁיתֵמוֹ לְשָׂרִים, דְּאִינוּן אֲבָהָן עִילָאִין, דִּכְתִיב בְּהוּ (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים, דְּאַתְקִינוּ לָהּ בְּכוֹלָא וְכוֹלָא לְהַאי בְּאֵר. כְּנֶסֶת יִשְׂרָאֵל אִתְקְרֵי.</p>"],[9514013328,"<p>דָּבָר אַחֵר, תַּחַת אֲבוֹתֶיךָ יִהְיוּ בָנֶיךָ. דְּכָלְהוֹ בִּרְחִימוּ, כְּאִינוּן דָּרָא דְּמַדְבְּרָא, כְּאִינוּן דְּאִיקְרוּן דּוֹר דֵּעָה. יִהְיוּ בָנֶיךָ, דְּכָלְהוֹ בִּרְחִימוּ יִתְגַּבְּרוּן עַל אוֹרַיְיתָא. לָקֳבֵל דָּא כְּתִיב, (שיר השירים א׳:י״ב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. דְּאַקְדִימוּ עֲשִׂיָּה לִשְׁמִיעָה. אוּף הָכָא בָּנֶיךָ יִשְׁתַּלְּמוּן כְּוָותְהוֹן.</p>"],[9514013329,"<p>(תהילים מ״ה:י״ח) אַזְכִּירָה שִׁמְךָ בְּכָל דּוֹר וָדוֹר. מִדָּרָא עִילָאָה, דְּתַלְיָיא בֵּיהּ דְּרוֹר וְחֵירוּ לְכֹלָּא. בְּזִמְנָא דְּהַהוּא שׁוֹפָר גָּדוֹל, יַפֵּיק כּוֹלָא לְחֵירוּ, כְּדֵין עַמִּים יְהוֹדוּךָ לְעוֹלָם וָעֶד, דְּלָא יִתְפְּרַשׁ עוֹלָם מִוָּעֶד, וּוָעֶד מֵעוֹלָם. לָקֳבֵיל דָּא, צְרוֹר הַמֹּר דּוֹדִי לִי בֵּין שָׁדַי יָלִין.</p>"],[9514013330,"<p>עַד הָכָא אִתְיְיהֵב לֵיהּ רְשׁוּ לְגַלָּאָה. אָתָא שְׁלֹמֹה, וְאִשְׁתְּלֵים בְּכֹלָּא, וְאַשְׁלֵים כֹּלָא, וְאַכְלֵיל בְּהַנְהוּ תּוּשְׁבְּחָן חָכְמָתָא עִילָאָה, קִיּוּמָא דְכָל עָלְמִין, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְגַלָּאָה לָהּ לִבְנוֹי, בְּזִמְנָא דְּיִתְעַר דַּעְתָּא בְּעָלְמָא. דְּכָל חַד וְחַד מִיִּשְׂרָאֵל יַדְבֵּיק אַדְבְּקוּתָא בְּחָכְמְתָא עִילָאָה, רָזָא דִשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְדָא אִיהוּ טִיבוּ, דְּלֵית לֵיהּ פְּסִיקוּ כְּלַל, לְעָלַם וּלְעָלְמֵי עָלְמִין</p>"],[9514013331,"<p>אֱמוּנָה אוֹמֶן, תְּרֵי דְּאִינוּן חַד. חַד גַּן, וְחַד נָהָר. דָּא נָפֵיק מֵעֵדֶן, וְדָא אִיתְשַׁקֵּי מִנֵּיהּ. הָא הָכָא כָּל רָזָא סְתִימָא דִמְהֵימְנוּתָא.</p>"],[9514013332,"<p>וְאוֹלִיפְנָא, הַאי מַאן דְּאִיתְעַר בְּלֵילְיָא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא, לְאִשְׁתַּעְשְׁעָא בְּצַדִּיקַיָיא, בָּעֵי לְמֵימַר פְּסוּקָא דָא, בִּרְעוּתָא דְלִבָּא, וּלְכַוְּונָא רְעוּתָא בֵּיהּ. (ישעיהו כ״ה:א׳) ה' אֱלֹהַי אַתָּה אֲרוֹמִמְךָ אוֹדֶה שִׁמְךָ כִּי עָשִׂיתָ פֶּלֶא עֵצוֹת מֵרָחֹק אֱמוּנָה אֹמֶן. וּבָתַר כֵּן יֹאמַר, (תהילים קל״ט:י״ד) אוֹדְךָ עַל כִּי נוֹרָאוֹת נִפְלֵיתִי נִפְלָאִים מַעֲשֶׂיךָ וְנַפְשִׁי יֹדַעַת מְאֹד. לְבָתַר, וְנָהָר יוֹצֵא מֵעֵדֶן וְגו'. וְהַיְינוּ שִׁבְחָא דַּחֲסִידֵי קַדְמָאי, כַּד מִתְעָרוֹ בְּפַלְגוּת לֵילְיָא. וּלְבָתַר מְסַדְּרֵי שִׁבְחַיְיהוּ, וְלָעָאן בְּאוֹרַיְיתָא.</p>"],[9514013333,"<p>שַׁעֲשׁוּעָא דְקוּדְשָׁא בְּרִיךְ הוּא מַאי הִיא. אֶלָּא, כָּל צַדִּיקַיָיא קָיְימִין בִּדְיוּקְנַיְיהוּ, וּמִתְלַבְּשִׁין בְּגִנְתָּא דְעֵדֶן, בְּכָל יוֹמָא וְיוֹמָא, וְאִתְסְחָן בְּטַלָּא, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָא מֵיתַיָיא. וְעָאלִין כָּלְהוֹ לְגַבֵּי מָשִׁיחַ, וְשָׁאֲלִין מַה דְּשָׁאֲלִין, וְהָא אִיתְעָרוֹ חַבְרַיָיא.</p>"],[9514013334,"<p>לְבָתַר מִתְכַּנְשִׁין, וּמִשְׁתַּדְּלִין כָּלְהוֹ בְּדַעְתָּא עִילָאָה, בְּכָלְהוֹ מְתִיבָתֵי דְּתַמָּן. וַעֲלַיְיהוּ כַּמָּה מְמַנָּן. וּמִתְחַדְּשִׁין תַּמָּן כַּמָּה חִידּוּשִׁין בְּאוֹרַיְיתָא. לְבָתַר נָפְקֵי כָּלְהוֹ, וְחָמָאן, כַּד אָתֵי אֵלִיָּהוּ לְגַבֵּי אֲבָהָן. אִיהוּ נָפַק, וְאִינְהוּ עָאלִין וְקָיְימִין קַמֵּי אֲבָהָן, וְחָדוֹ בְּהוּ, בְּכַמָּה בְּנִין קַדִּישִׁין דִּי בְּסַחֲרָנַיְיהוּ, וְחָדָאן כָּלְהוֹ.</p>"],[9514013335,"<p>כַד עָיֵיל קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגוּ לֵילְיָא, כָּלְהוֹ קָיְימִין מִתְתַּקְנִין כִּדְקָא יָאוֹת, וְכָל אִשְׁתַּדְּלוּתָא דְּאִשְׁתַּדְּלוּ כָּל הַהוּא יוֹמָא בְּחִידּוּשֵׁי אוֹרַיְיתָא. וְקוּדְשָׁא בְּרִיךְ הוּא תֵּיאוּבְתֵּיהּ בְּאִינוּן צַדִּיקַיָיא, דַּחֲדִישׁוּ בָּהּ מִלִּין. וְאִשְׁתַּעְשַׁע בְּהוּ, וְאִשְׁתַּעְשַׁע בְּאִלֵּין מִלִּין. וְכָל בְּכָל צַדִּיקָא וְצַדִּיקָא.</p>"],[9514013336,"<p>לְבָתַר, כָּלְהוֹ מִתְתַּקְּנִין דְּכַר וְנוּקְבָא. וְקוּדְשָׁא בְּרִיךְ הוּא בָּתַר דְּאָרַח וְאִשְׁתַּעְשַׁע בְּהוּ, וּבְכָל אִלֵּין רָזִין דְּחָכְמְתָא דִּילְהוֹן, אִתְגְּלֵי עֲלַיְיהוּ, וְאִינוּן חָמָאן בְּהַהוּא נוֹעַם ה'. כְּדֵין כָּלְהוֹ חָדָאן בְּחֶדְוָוה סַגְיָיא, עַד דְּמִתְפַּשְׁטֵי זִיוָא וּנְהוֹרָא דִּילְהוֹן. וּמֵהַהוּא מְשִׁיכוּ דְּזִיוָא וּנְהוֹרָא דְּחֶדְוָה דִילְהוֹן, עָבְדִין פֵּירִין וְאִיבִּין לְעָלְמָא דָא, וְהַהוּא אִיבָּא עָאל תְּחוֹת גַּדְפוֹי דִּשְׁכִינְתָּא, עַד זִימְנָא דְאִצְטְרִיךְ.</p>"],[9514013337,"<p>וְכָךָ מִשְׁתַּעְשַׁע בְּכָל צַדִּיק וְצַדִּיק, וְאָמַר, זַכָּאָה מַלְכָּא דִּבְנִין אִלֵּין אִתְבָּרְרוּ לְחוּלָקֵיהּ וְעַדְבֵיהּ. וְקָלָא אִיתְעַר, מֵאֶמְצָעוּת גִינְתָא דְרָקִיעַ, וְקוֹרֵא בְּקָל תַּקִּיף וַאֲמַר, (שם קלז) זְכֹר ה' לִבְנֵי אֱדוֹם אֵת יוֹם יְרוּשָׁלַ ם הָאוֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּהּ. כְּדֵין עַרְטִילוּ וְקַרְקוּרָא דִילֵיהּ. וְכָל צַדִּיקַיָיא דְתַמָּן אִתְעָרוּ בִּבְכִיָה.</p>"],[9514013338,"<p>וְקָלָא אִיתְעַר מֵאֶמְצָעוּת גִּנְתָא דִרְקִיעָא, דְּאִשְׁתְּמַע בִּתְלַת מְאָה וְתִשְׁעִין רְקִיעִין. בְּגִין דְּלֵית חֶדְוָה וְשַׁעֲשׁוּעָא לְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּשַׁעֲתָא דְּקָאִים בַּהֲדֵי צַדִּיקַיָיא דְתַמָּן. וּבְגִין דָּא אוֹמֵי וַאֲמַר, (שם) אִם אֶשְׁכָּחֵךְ יְרוּשָׁלַ ם תִּשְׁכַּח יְמִינִי תִּדְבַּק וְגו', אִם לֹא אַעֲלֶה אֶת יְרוּשָׁלַ ם עַל רֹאשׁ שִׂמְחָתִי. בְּכָל אֲתַר דְּאִית חֶדְוָה לְקוּדְשָׁא בְּרִיךְ הוּא, קָלָא דָא נָפֵיק וְקָארֵי.</p>"],[9514013339,"<p>כְדֵין נָפֵיק מִתַּמָּן, וְסָלֵיק וּבָטַשׁ בִּרְקִיעִין, וְשָׁאִיג שְׁאוֹגִין, עַד דְּכָל חֵילֵי שְׁמַיָיא כָּלְהוֹ בְּעִרְבּוּבְיָא. כְּדֵין נָשְׁבָא רוּחָא, וּבָטַשׁ בְּטַרְפִּין דְּהַהוּא אִילָנָא רַבְרְבָא, וְכָל עַנְפִין דִּילֵיהּ בָּטְשִׁין דָּא בְּדָא. וְקָלָא אִיתְעַר מִגּוֹ נוֹפָא דְאִילָנָא וְקָרֵי, (שם קה) זָכַר לְעוֹלָם בְּרִיתוֹ דָּבָר צִוָּה לְאֶלֶף דּוֹר אֲשֶׁר כָּרַת אֶת אַבְרָהָם וּשְׁבוּעָתוֹ לְיִצְחָק. כֵּיוָן דְּקָלָא דָא אִתְעַר, שָׁמַע אַבְרָהָם סָבָא וְאִיתְעַר, כְּדֵין אִיהוּ רַעֲוָוא דְמַלְכָּא, וְאִתְנַחֵם בַּהֲדֵיהּ.</p>"],[9514013340,"<p>בְּהַהִיא שַׁעֲתָא, אִיתְעַר רוּחָא חָדָא מִסִּטְרָא דְדָרוֹם, וְכָל רְעוּ וְחֶדְוָותָא וְאַסְוָותָא אִיתְעַר בְּעָלְמָא. וּכְדֵין סָלֵיק צַפְרָא, וְרַעֲוָוא אִשְׁתְּכַח, וְנַיְיחָא אִיהוּ לְכָל אֲסִירֵי מַלְכָּא דְּאִינוּן בְּבֵי מַרְעַיְיהוּ. זַכָּאָה עַמָּא, דְּיָכְלִין לְמִנְדַע מֵרָזִין טְמִירִין, סְתִימִין דְּמַלְכָּא קַדִּישָׁא.</p>"],[9514013341,"<p>אֲמַר רַבִּי אַבָּא, יוֹמָא חָדָא הֲוֵינָא אָזְלֵי בְּמַדְבְּרָא, אֲנָא וְרַבִּי יְהוּדָה דְּמִן עַכּוֹ בַּהֲדִי, וְאָעֵילְנָא בִּמְעַרְתָּא חָדָא, וְאַשְׁכַּחְנָא תַּמָּן סִפְרָא חָדָא עַתִּיקָא מִיּוֹמִין קַדְמָאִין. אַפְתַּחְנָא לֵיהּ, וְאַשְׁכַּחְנָא דְּהֲוָה כְּתִיב בְּרֵישׁ מִלּוֹי, (ישעיהו מ״ב:ט׳) הָרִאשׁוֹנוֹת הִנֵּה בָּאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד. וְאוֹקִים קְרָא בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָּא, מִן יוֹמָא דְּסָלֵיק בִּרְעוּתָא דְּמַחְשָׁבָה לְמִבְרֵי עָלְמָא.</p>"],[9514013342,"<p>דְּעַד לָא אִתְבְּרֵי עָלְמָא, כָּל רוּחִין דְּצַדִּיקַיָיא הֲווֹ גְנִיזִין בַּמַּחֲשָׁבָה קַמֵּיהּ, כָּל חַד וְחַד בִּדְיוּקְנֵיהּ. כֵּיוָן דְּצַיֵּיר עָלְמָא, אִתְגַּלְּיָין כָּלְהוֹ, וְקָיְימֵי בִּדְיוּקְנַיְיהוּ קַמֵּיהּ, תַּמָּן בְּרוּמֵי רְקִיעִין. לְבָתַר יָהֵיב לוֹן בְּאוֹצַר חַד, בְּגִנְתָא דְעֵדֶן לְעֵילָא. וְהַהוּא אוֹצָר לָא מַלְיָיא לְעָלְמִין, וְתָדִיר קָרֵי, הָרִאשׁוֹנוֹת הִנֵּה בָאוּ וַחֲדָשׁוֹת אֲנִי מַגִּיד. מַאי אֲנִי מַגִּיד. אֶלָּא כָּלְהוֹ בִּשְׁמָהָן וְלֵית תֵּאוּבְתָּא וְכִיסוּפָא לְהַהוּא אוֹצָר, אֶלָּא לַאֲרָקָא בֵּיהּ נִשְׁמָתִין.</p>"],[9514013343,"<p>כְמָה דְּגֵיהִנֹּם, לֵית לֵיהּ תֵּאוּבְתָּא, אֶלָּא לְקַבְּלָא נִשְׁמָתִין בֵּיהּ לְאִתְדַּכָּאָה, תַּמָּן, וְכָל יוֹמֵי קָרֵי, הַב הַב. מַאי הַב הַב, אֶלָּא אוֹקִיד אוֹקִיד.</p>"],[9514013344,"<p>וְהַהוּא אוֹצָר נָטֵיר כָּל אִינוּן נִשְׁמָתִין, עַד זִימְנָא דְּאַלְבֵּישׁ לוֹן, וְנָחֲתוֹ לְהַאי עָלְמָא. וּמִגּוֹ חוֹבָא דְּאָדָם קַדְמָאָה, דְּאַחְשִׁיךְ עַלְמָא, וְאַמְשִׁיךְ סִטְרָא אָחֳרָא בִּישָׁא לְעַלְמָא, אִצְטְרִיכוּ לְאִתְלַבְּשָׁא אִינוּן נִשְׁמָתִין. בִּלְבוּשָׁא דָא, דְּהָא לְבוּשָׁא אָחֳרָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבָּשָׁא לְאִינוּן נִשְׁמָתִין. וַהֲוָה אֲמַר בְּהַהוּא סִפְרָא, עַד הָכָא, שְׁתִיקוּ. וְחָמֵינָא מִכָּאן וָהָלְאָה, מִלִּין מְתִיקָן דְּלָא אִשְׁתְּמוֹדְעָאן.</p>"],[9514013345,"<p>וּלְבָתַר חָמֵינָא לוֹן בְּחֶלְמָא. וַאֲמָרוּ לִי שְׁתוֹק, וְלָא תְגַלֵּי אֶלָּא לְטִינָרָא תַּקִּיפָא, וְכָך עֲבִידְנָא. וְאַשְׁכַּחְנָא בֵּיה, וְאִיתֵימָא, לְבוּשָׁא אָחֳרָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַלְבָּשָׁא לְאִילֵין נִשְׁמָתִין לְעַלְמָא דְאָתֵי, אִם כֵּן מֵיתַיָא דְּאַחְיָא יְחֶזְקֵאל, מַאי טַעְמָא לָא עָבַד לוֹן הַהוּא לְבוּשָׁא.</p>"],[9514013346,"<p>אֶלָּא, בְּגִין דְּלָא מָטָא זִמְנָא, לְאַעֲבָרָא בְּעַלְמָא הַהוּא אֲוִירָא דַכְיָיא, דְּעָבִיד לְבוּשִׁין. וּבְגִין כָּךְ לָא אַלְבֵּישׁ לוֹן, אֶלָּא כְּמָה דַּהֲווֹ. וְכָךְ יְהֵא לִתְחִיַּת הַמֵּתִים, בַּר דְּזוּהֲמָא דְּקַדְמֵיתָא לָא אִשְׁתַּכְּחַת תַּמָּן.</p>"],[9514013347,"<p>וְכַד בַּר נָשׁ נָפֵיק מֵהַאי עָלְמָא, כָּלְהוֹ, בֵּין צַדִּיקִים, בֵּין חֲסִידִים וּתְמִימִין, וְחַיָּיבִין וּרְשָׁעִים, כָּלְהוּ עָבְרִין בְּאוֹרְחָא דָא לְמֵיחֱמֵי לֵיהּ לְאָדָם קַדְמָאָה, לְכָל בְּנֵי עָלְמָא. וְתַמָּן נָטְלֵי אוֹרְחָא, אוֹ לַגַּן עֵדֶן, אוֹ לַגֵּיהִנֹּם.</p>"],[9514013348,"<p>כָל אִינוּן דְּאוֹרְחַיְיהוּ לְגַּן עֵדֶן, מִתְקָרְבִין לְגַבֵּי חוֹמָה דִּלְבַר, מֵאִינוּן תְּלַת חוֹמוֹת דְּתַמָּן. כְּדֵין נָפַק חַד מְמַנָּא, וְאִתְעַר קַמַּיְיהוּ וְקָארֵי וַאֲמַר, זַכָּאִין אַתּוּן צַדִּיקַיָּיא בְּעָלְמִין כָּלְהוֹ. וְהַהוּא מְמַנָּא יעזריאָמַר לֵיהּ שְׁמֵיהּ. אוֹלִיף לוֹן אוֹרְחָא, וְאָזְלִין קַמֵּיהּ, עַד תַּרְעָא חָדָא דְּגֵיהִנֹּם, וְהַאי מְמַנָּא קָרֵי בְחֵילָא, צַנּוּן תְּנָנָא צַנּוּן יָקֵידְתָּא. בְּהַהוּא שַׁעֲתָא, בִּבְהִילוּ מְצַנְּנָן לֵיהּ, וְעָאלִין כָּלְהוֹ וְטָבְלִין וְעָבְרִין. וְכָלְהוֹ חַיָּיבַיָא, אִתְמַסְרָן בִּידָא דְּדוּמָה, וְאָעֳלִין בַּגֵּיהִנֹּם, וְכָל אִינוּן זַכָּאִין לָא אִתְמַסְרָן בִּידוֹי, אֶלָּא בִּידוֹי דְּהַהוּא מְמַנָּא.</p>"],[9514013349,"<p>כֵיוָן דְּטָבְלִין וְעָבְרִין, הַהוּא מְמַנָּא אָזִיל קַמַּיְיהוּ, עַד דְּמָטוֹן לְשׁוּר חוֹמָה דְּגִינְתָא דְעֵדֶן. וְהַהוּא מְמַנָּא קָארֵי לְפִתְחָא וַאֲמַר, (שם כו) פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק שׁוֹמֵר אֱמֻנִים. כְּדֵין פָּתְחִין פִּתְחָא, וְאָעֵיל לוֹן לְגַאו, וְכֵן לְכָל פִּתְחָא וּפִתְחָא.</p>"],[9514013350,"<p>כֵיוָן דְּעָאלוּ לְגַאו, לַאֲתַר דְּצַדִּיקַיָּיא אָחֳרָנִין קָיְימִין, כַּמָּה חֶדְוָה עַל חֶדְוָה, וְכַמָּה חֵידוּ עַל חֵידוּ עַל צַדִּיקַיָא, וְכָל בְּנֵי מְתִיבָתָא חָדָאן. לְסוֹף תְּלָתָא יוֹמִין, דְּאִתְטַמְּרָן בְּהֵכָלִין יְדִיעָאן, נָפְקִין, וַאֲוִירִין נָשְׁבִין, וּמִצְטַיְירִין כָּלְהוֹ בִּדְיוּקְנַיְיהוּ. וּמִכָּאן לְהָלְאָה, יַרְתֵי אַחְסָנַת יְרוּתָא, כִּדְקָא חָזֵי לְכָל חַד וְחַד.</p>"],[9514013351,"<p>חֵיזְוָוא דְּאִתְחַזְּיָא בְּגַּן עֵדֶן, מֵחֵיזוּ יְקָרָא דִּיוּקְנָא דְּכָל דְּיוֹקְנִין, וְגַוָּון דְּכָל גְּוָונִין, דְּמַלְכָּא קַדִּישָׁא, לָא אִתְגְּלֵי בְּהֵיכָלָא, וְלָא בַּאֲתַר חַד, אֶלָּא אִתְפַּתַּח רְקִיעָא מְרַקְמָא עַל גַּבֵּי גִּנְתָא, לְד' סִטְרִין, וְאִתְמַלְיָא מִזִּיוָא יַקִּירָא קַדִּישָׁא, וְאִתְחֲזוֹ תַּמָּן, וְאִתְנַהֲרוֹן כָּלְהוֹ צַדִּיקַיָיא. מַאן חָמָא חֶדְוָוא דָא, וְכִסוּפָא דָא, דְּהַהוּא נוֹעַם ה'.</p>"],[9514013352,"<p>עַד כָּאן הֲוָה לִי רְשׁוּ לְמֶחֱמֵי בְּהַהוּא סִפְרָא. אַדְּמַקִּיפְנָא לְמֵיחֱמֵי יַתִּיר, פָּרַח מִן יָדִי, וְלָא חָמֵינָא לֵיהּ, וְאִשְׁתָּאַרְנָא עָצִיב, וּבָכִינָא. דְּמִיכְנָא תַּמָּן בְּהַהוּא מְעַרְתָּא, וְחָמֵינָא לֵיהּ לְהַהוּא דְּלָבֵישׁ מַדָּא, אָמַר לֵיהּ, רַבִּי, מַה לָּךְ לְמִבְכֵּי, לָא תִתְעַצֵּיב. מִמַּאן דְּהֲוָה הַהוּא סִפְרָא, פְּרַח לְגַבֵּיהּ, וּנְטָלֵיהּ. וְעַד דְּלָא נְפַק מֵהַאי עָלְמָא, גָּנִיז לֵיהּ בְּהַהוּא מְעַרְתָּא דְמַדְבְּרָא דָא, וְהַשְׁתָּא דְּהֲוָה מִתְגַּלֵּי לְחַיָּיא, פְּרַח בַּאֲוִירָא וּנְטָלֵיהּ.</p>"],[9514013353,"<p>מִכָאן וּלְהָלְאָה, זִילִי לָךְ לְאוֹרְחָךְ. וּמֵהַהוּא יוֹמָא עַד הָכָא. לָא אִתְגְּלֵי לִי, וְלָא זָכֵינָא לְמִשְׁמַע מִמַּאן הוּא. וּבְכָל זִמְנָא דַּאֲנָא דָּכִירְנָא, אִשְׁתָּאַרְנָא עָצִיב. אָמַר רַבִּי אֶלְעָזָר דִּילְמָא קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהּ, דְּלָא יִתְגְּלֵי בְּעָלְמָא.</p>"],[9514013354,"<p>עַד דַּהֲווֹ יָתְבֵי וְלָעָאן בְּמִלִּין יַקִּירִין וְעִילָאִין אִלֵּין, נְהַר יְמָמָא. קָמוּ וַאֲזָלוּ, אֲמַר רַבִּי אֶלְעָזָר, הַשְׁתָּא עִידַן רַעֲוָוא הוּא קַמֵּי מַלְכָּא, נֵימָא מִילֵי דְאוֹרַיְיתָא, וְנִתְעַסֵּק בָּהּ, וְנִשְׁתַּתֵּף בִּשְׁכִינְתָּא.</p>"],[9514013355,"<p>(במדבר כ״ב:ה׳) לֵאמֹר הִנֵּה עַם יָצָא מִמִּצְרַיִם. אִי תֵימָא, דְּהָא צָרִיךְ לְנַטְלָא פִּיפּוֹסִין וְיוֹחֲסִין דִּילְהוֹן, לָא אִצְטְרִיךְ, אֶלָּא אוֹרַח כְּלַל. דִּכְתִיב הִנֵּה עַם יָצָא מִמִּצְרַיִם. מַאי טַעְמָא. מִשּׁוּם דְּהָכֵי קָארֵי לוֹן פַּטְרוֹנָא דִּילְהוֹן כַּמָּה זִימְנִין, וְעַל דָּא לָא תִטְעֶה, דִּכְתִיב (שמות ה׳:א׳) שַׁלַּח אֶת עַמִּי בְּכָל זִמְנָא.</p>"],[9514013356,"<p>וְעוֹד, כַּד אִתְנַטְלֵית עֵיטָא עֲלַיְיהוּ עִם פַּרְעֹה, בְּלִישְׁנָא דָּא יָכְלֵי לְהוֹ, דִּכְתִיב (שם א) הִנֵּה עַם בְּנֵי יִשְׂרָאֵל רַב וְעָצוּם מִמֶּנּוּ. אוּף הַשְׁתָּא דִּכְתִיב, הִנֵּה עַם יָצָ\"א מִמִּצְרַיִם, דְּלָא אַפֵּיק לוֹן אַחֲרָא, אֶלָּא אִיהוּ מִגַרְמֵיהּ נְפַק, וּבְגִין כָּךְ תֵּיכוֹל לְאַבְאָשָׁא לוֹן.</p>"],[9514013357,"<p>הִנֵּה כִסָּה אֶת עֵין הָאָרֶץ, אִית דְּאָמְרֵי, סִיחוֹן וְעוֹג, דְּקַטְלֵי לוֹן יִשְׂרָאֵל, דַּהֲווֹ עֵינָא דְאַרְעָא. אֶלָּא כַּד אַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא אַרְבֶּה עַל אַרְעָא דְמִצְרַיִם, מַה כְּתִיב, (שם י) וַיְכַס אֶת עֵין כָּל הָאָרֶץ וַתֶּחְשַׁךְ הָאָרֶץ. אַמַּאי, בְּגִין דְּכָל חָרָשִׁין וְקוֹסְמִין דְּעָלְמָא, לָא יָכְלִין לְמֶעְבַּד חָרָשִׁין, אֶלָּא מִלָּה חָדָא, בְּדַרְגָא חָדָא, בְּזִמְנָא חָדָא. וּלְעַמָּא דָא אַיְיתֵי אַרְבֶּה, מְבוּלְבָּל בְּכַמָּה זִינֵי מְבוּלְבָּלִים אִלֵּין בְּאִלֵּין, עַד דְּלָא יָכִילוּ כָּל חָרָשִׁין וְכָל קוֹסְמִין, לְמֵיקַם קַמַּיְיהוּ. וְדָא הוּא וַיְכַס אֶת עֵין כָּל הָאָרֶץ. וְהָכָא כְּתִיב, הִנֵּה כִסָּה אֶת עֵין הָאָרֶץ.</p>"],[9514013358,"<p>אָמַר רִבִּי אַבָּא, בֹּא וּרְאֵה, בָּלָק וּבִלְעָם לָא הֲווֹ בְּעָלְמָא חָרָשִׁין וְקוֹסְמִין כַּוָּותַיְיהוּ. בִּלְעָם, חֵילֵיהּ וְתוֹקְפֵיהּ הֲוָה בְּפוּמָא וּבְעַיְינִין. בָּלָק, חֵילֵיהּ וְתוֹקְפֵיהּ בְּעוֹבָדָא דְיָדַיִן. וְדָא אִצְטְרִיךְ לְדָא. דְּהָא כָּל זִינֵי חָרָשִׁין דְּעָלְמָא בְּפוּמָא וְעוֹבָדָא הֲווֹ, וּבְהוֹ תַּלְיָין. בִּלְעָם הֲווֹ לֵיהּ לִישָׁן, וְלָא יָדַיִן. בָּלָק הֲוָה לֵיהּ יָדַיִן וְלָא לִישָׁן.</p>"],[9514013359,"<p>אֲזָלוּ חַבְרַיָיא, וְשִׁמְשָׁא הֲוָה תַּקִּיף לַחֲדָא, חָמוֹ הַהוּא בֵּי חֲקַל בְּשַׁפִּירוּ דַּעֲשָׂבִין, וּמַיִין נָפְקִין לְכָל סְטַר, וְאִילָנֵי חַקְלָא סַגִּיאִין, יַתְבֵי תַּמָּן. אֲמַר רַבִּי אֶלְעָזָר, כַּמָּה יָאוֹת אֲתַר דָּא לְנַיְיחָא בֵּיהּ.</p>"],[9514013360,"<p>אַהְהֲווֹ יָתְבֵי, הָא חִיוְיָא רַבְרְבָא אָתֵי, בְּתוֹקְפָא דְשִׁמְשָׁא, אַעֲבַר קַמַּיְיהוּ. אָמַר לֵיהּ ר' אֶלְעָזָר, חִיוְיָא חִיוְיָא, סְטֵי לָךְ מֵאוֹרְחָךְ, דְּהַא הַהוּא גַבְרָא תָּב, וְאִתְנֶחָם עַל מַה דַּעֲבַד, וְלָא יוֹסִיף לְמֶיעְבַּד הַהוּא מִלָּה. תְּוָוהוּ חַבְרַיָיא, אֲמַר רַבִּי אַבָּא, מַאי הַאי. אֲמַר לוֹן שְׁתִיקוּ.</p>"],[9514013361,"<p>אָמַר ר' אֶלְעָזָר, חִיוְיָא חִיוְיָא, לְבָתַר דִּלְחִישׁוּ לָךְ מִן שְׁמַיָא, אִתְנַחֵם הַהוּא גַבְרָא, וְשָׁוֵי בִּרְעוּתֵיהּ, דְּלָא יְתוּב לְהַאי חוֹבָא לְעָלְמִין, סְטֵי לָךְ מֵאוֹרְחָךְ. קָם חִיוְיָא בְּקִיּוּמֵיהּ, וְלָא נְטֵיל הָכָא וְהָכָא. תָּב כְּמִלְקַדְמִין, וְאָמַר לֵיהּ, חִיוְיָא חִיוְיָא, יְדַעְנָא מָה אַתְּ בָּעֵי, תּוּב מֵאוֹרְחָךְ, דְּהָא גוֹי חַיָּיבָא אָתֵי, דְּעָבִיד בִּישׁ לְחַד יוּדָאי, וְהָא הוּא נָאִים בִּמְעַרְתָּא דִילָךְ, זִיל וְקַטְלֵיהּ. מִיַּד אַהֲדַר הַהוּא חִיוְיָא, וְדִלֵּג דִּילוּגִין קַּמַּיְיהוּ.</p>"],[9514013362,"<p>אֲמַר ר' אֶלְעָזָר, חַבְרַיָיא, אִי לָא הֲוֵינָא הָכָא, כַּמָּה בִּישִׁין הֲוָה עָבִיד הַהוּא חִיוְיָא. דְּהָא בַּר נָשׁ חַד יוּדָאי, עָבַד עוֹבָדָא דְחוֹבָה, וְעַד דְּלָא תָּב בִּתְיוּבְתָּא, לְחִישׁוּ לֵיהּ לְהַאי חִיוְיָא, לְקַטְלָא לֵיהּ. וְאִמְלַךְ הַהוּא בַּר נָשׁ בֵּין כָּךְ וּב\"כ, וְאִתְנַחֵם מֵחוֹבֵיהּ, וַאֲמַר דְּלָא יְתוּב לְעָלְמִין לְהַאי חֶטְאָה, וְעַל דָּא אִשְׁתֵּיזִיב מִן דִּינָא.</p>"],[9514013363,"<p>אֲמָרוּ חַבְרַיָיא לְרַבִּי אֶלְעָזָר, בַּמֶּה יָדַעְתְּ. אֲמַר לוֹן, סִימָנָא יְהַב לִי אַבָּא וַאֲנָא אִשְׁתְּמוֹדַעְנָא בֵּיהּ. אָמַר לֵיהּ, תֵּינַח חִיוְיָא, דְּאִשְׁתְּמוֹדַעְתְּ בֵּיהּ. הַהוּא דְּאִתְנַחֵם וְתָב מֵחוֹבֵיהּ, בַּמֶּה יְדַעְתְּ. אֲמַר לוֹן, כַּד הֲוָה אָזֵיל הַהוּא חִיוְיָא, קַשְׂקַשׂוֹי הֲווֹ סָלְקִין, וּזְנָבֵיהּ זָקֵיף, וְאִיהוּ דְּאָזַל בִּבְהִילוּ. רוּחָא אַחֲרָא הֲוָה אָזֵיל לְקִבְלֵיהּ, וַהֲוָה קָארֵי קַמֵּיהּ, תּוּב מֵאוֹרְחָךְ, דְּהָא תָּב מֵחוֹבֵיהּ וְאִתְנַחֵם הַהוּא בַּר נָשׁ. וְהַהוּא חִיוְיָא בִּישָׁא לָא הֲוָה אָצֵית, עַד דְּיִתְּנוּן לֵיהּ כּוֹפֶר בְּאַתְרֵיהּ דְּהַהוּא בַּר נָשׁ דְּאִתְחַיָּיב קְטִילָא וְתָב מֵאוֹרְחֵיהּ וְאִתְנַחֵם. דְּכָךְ אוֹרְחוֹי דְּחֵיוָא עֵילָא וְתַתָּא, כֵּיוָן דְּאִתְיְהֵיב לֵיהּ רְשׁוּ, לָא תָּב, עַד דְּאַשְׁלֵים הַהוּא דִינָא בִּישָׁא דְּאִתְיְהֵיב לֵיהּ רְשׁוּ לְמֶעְבַּד, אוֹ דְּיִתְּנוּן לֵיהּ בְּאַתְרֵיהּ חַיָּיבָא אָחֳרָא בְּכוֹפְרָא, דְּהָא בְּרֵיקַנְיָיא לָא יִפּוֹק, כֵּיוָן דְּאִתְיְהֵיב לֵיהּ רְשׁוּ.</p>"],[9514013364,"<p>אָמַר לֵיהּ, תֵּינַח כָּל דָּא, הַהוּא גוֹי דַּאֲמַרְתְּ דְּאִתְיְיהֵיב לֵיהּ כּוּפְרָא בַּמֶּה יְדַעְתְּ. אֲמַר לוֹן, כֵּיוָן דְּמַלֵּילַת לְחִיוְיָא, הַהוּא רוּחָא דְּהֲוָה אָזֵיל לְקִבְלֵיהּ, וְלָחִישׁ לֵיהּ דִּיתִיב לְאוֹרְחֵיהּ דְּהָא אִתְנַחֵם הַהוּא בַּר נָשׁ, הוּא דָּלֵיג עַל אוּדְנִי, וַאֲמַר לִי.</p>"],[9514013365,"<p>תְּוָוהוּ חַבְרַיָיא, אֲמַר ר' אֶלְעָזָר, חַבְרַיָיא, נְהַךְ וְנֶחֱמֵי, דְּהָא חִיוְיָא כְּבָר עֲבַד מַה דַּעֲבַד. קָמוּ וּקְרִיבוּ לְגַבֵּי חַד טִינָרָא בְּהַהוּא בֵּי חֲקַל, אַשְׁכָּחוֹ לְהַהוּא גוֹי דְּמֵת, וְהַהוּא נָחָשׁ כָּרוּךְ עַל עִקְבֵיהּ, וְלָא הֲוָה אִבְדִּיל מִנֵּיהּ. לְבָתַר אִתְפְּרַשׁ מֵעִקְבֵיהּ, וְסָלֵיק עַל גְּרוֹנֵיהּ, וְאִכְרִיךְ תַּמָּן. וּמִתַּמָּן נָחִית עַל עִקְבֵיהּ, וְלָא הָיָה מִתְפָּרְשָׁא מִנִּיהּ.</p>"],[9514013366,"<p>אַשְׁכָחוֹ לֵיהּ אַרְנָקִי חַד מַלְיָיא דִינָרִין, דְּגָזַל לְחַד יוּדָאי בְּאוֹרְחָא, וּמְחָא לֵיהּ. נָטַל רַבִּי אֶלְעָזָר אֶת הָאַרְנָקִי, וַאֲמַר, בְּרִיךְ רַחֲמָנָא, דִּבְכוֹלָא עָבִיד שְׁלִיחוּתָא. תָּבוּ לְהַהוּא אֲתַר דַּהֲווֹ.</p>"],[9514013367,"<p>פְּתַח רַבִּי אֶלְעָזָר וַאֲמַר, (ישעיהו מ״ג:ד׳) מֵאֲשֶׁר יָקַרְתָּ בְעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךָ וְאֶתֵּן אָדָם תַּחְתֶּיךָ וּלְאֻמִּים תַּחַת נַפְשֶׁךָ. מֵאֲשֶׁר יָקַרְתָּ, יָקָר מִבָּעי לֵיהּ, וְהָכֵי אִצְטְרִיךְ, מֵאֲשֶׁר אַתָּה יָקָר בְּעֵינַי, מַהוּ יָקַרְתָּ, מִכְּלַל דְּאִיהוּ מִגַּרְמֵיהּ אִתְיַקַּר. הָכֵי הוּא וַדַּאי, דְּכָל בַּר נָשׁ דְּאִיהוּ בְּחִיּוּבָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא הוּא מְזַלְזְלָא. וְתוֹעֵבָה אִיהוּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּבָתַר דְּאִמְלַךְ וְתָב מֵחוֹבֵיהּ, הַשְׁתָּא אִתְיַקַּר אִיהוּ מִגַּרְמֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא קָארֵי עֲלֵיהּ וַאֲמַר, מֵאֲשֶׁר יָקַרְתָּ, אַתְּ מִגַּרְמֵךְ יָקַרְתָּ.</p>"],[9514013368,"<p>בְּעֵינַי נִכְבַּדְתָּ וַאֲנִי אֲהַבְתִּיךָ, דְּהָא לֵית רְחִימוּ לְקוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵי בַּר נָשׁ בְּעָלְמָא, אֶלָּא לְמַאן דְּתָב מֵחוֹבֵיהּ, וְעַל דָּא וַאֲנִי אֲהַבְתִּיךָ. אֲבָל מָה אַעֲבֵיד, דְּהָא יְהִיבַת רְשׁוּ לְחִוְיָא לְנַזְקָא. דָּא הוּא עֵיטָא, וְאֶתֵּן אָדָם תַּחְתֶּיךָ. מַאי אִיהוּ אָדָם דִּיהַב קוּדְשָׁא בְּרִיךְ הוּא כּוֹפֶר תְּחוֹתֵיהּ. הַהוּא אָדָם דְּאָתֵי מֵעַמָּא דְּסִטְרָא בִישָׁא, דְּהַהוּא חִיוְיָא מִדִּילֵיהּ יֵיכוֹל. דִּכְתִיב וְאֶתֵּן אָדָם, אַל תִּקְרֵי אָדָם, אֶלָּא אֱדוֹם. וּלְאֻמִּים, דָּא הוּא (בראשית כ״ה:כ״ג) וּלְאֹם מִלְּאֹם יֶאֱמָץ, וְדָא זַרְעָא דְעֵשָׂו, דִּיהֵיב תַּחַת נַפְשֵׁיהּ.</p>"],[9514013369,"<p>אַהְהֲווֹ יָתְבֵי, הָא הַהוּא יוּדָאי, דְּגָזַל לֵיהּ הַהוּא גוֹי, דְּקַטְלֵיהּ חִוְיָא, אָתֵי מֵאוֹרְחָא וְלָאֵי. וּמִגּוֹ תּוֹקְפָא דְשִׁמְשָׁא, עָאל בְּהַהוּא חֲקַל, וִיתֵיב תְּחוֹת אִילָנָא חַד, וְהוּא מִתְרָעֵם לְקוּדְשָׁא בְּרִיךְ הוּא, וּמַצְדִּיק עֲלֵיהּ דִּינָא, וַאֲמַר, מָארֵי דְעָלְמָא, גָּלוּי וְיָדוּעַ קַמָּךְ, דַּאֲנָא לָא חַיַּישְׁנָא עָלַי, וְעַל גּוּפָאי, וְעַל מָמוֹנִי כְּלוּם, דְּהָא בְּדִינָא אִתְעֲבֵיד כָּל מַה דְּאִתְעֲבֵיד. אֲבָל אַבָּא וְאִמָּא סָבִין אִית לִי, דְּלֵית לִי בַּמֶּה דַּאֲפַרְנֵס לוֹן, וְעַל דָּא חַיַּישְׁנָא.</p>"],[9514013370,"<p>וְתוּ, עַל כָּל דָּא, צְרוֹרָא חָדָא דְדִינָרִין דְּהֲוָה בְּהַהוּא אַרְנָקָא, דְּחַד מִסְכֵּינָא לְמֶעְבַּד חוּפָּה לִבְרַתֵּיהּ עֲנִיָּיא, מָה יַעֲבֵיד. מָארֵיהּ דְּעָלְמָא, עַל דָּא כָּאִיבְנָא בְּלִבָּאי יַתִּיר.</p>"],[9514013371,"<p>בָּכֵי וַאֲמַר, (תהילים י״ט:י׳) מִשְׁפְּטֵי ה' אֱמֶת צָדְקוּ יַחְדָּו. דִּינִין דְּמָארֵי עַלְמָא קְשׁוֹט אִינוּן. אַמַּאי אִינוּן קְשׁוֹט. בְּגִין דְּצָדְקוּ יַחְדָּו. דְּהָא בְּשַׁעֲתָא דְדִינָא, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְמֶעְבַּד דִּינָא, כַּמָּה מָארֵי תְּרֵיסִין קָיְימִין מֵהַאי סְטַר וּמֵהַאי סְטַר וּמַגִּיחִין אִלֵּין בְּאִלֵּין, וּמַצְדִיקִין אִלֵּין בְּאִלֵּין. כֵּיוָן דְּצָדְקוּ אִלֵּין בְּאִלֵּין וְאִסְתַּכְּמוּ כַּחֲדָא, כְּדֵין מִשְׁפְּטֵי ה' אֱמֶת. אֵימָתַי צָדְקוּ יַחְדָּו, כַּד מַצְדִיקִין כָּל בְּנֵי דִינָא דִלְעֵילָא. מָארֵי דְעָלְמָא, עַל דָּא אֲנָא בָּכִינָא, וְלָא עַל דִּידִי.</p>"],[9514013372,"<p>שָׁמַע רִבִּי אֶלְעָזָר וְחַבְרַיָיא, וְקָמוּ לְגַבֵּיהּ, חָמוּ יָתֵיהּ דְּהֲוָה יָתִיב תְּחוֹת הַהוּא אִילָנָא. וְאַתְקִיפוּ בֵּיהּ, וּנְטָלוּ יָתֵיהּ לְגַבֵּיהוֹן, אָמַר רִבִּי אֶלְעָזָר לָא תִדְחַל זַכָּאָה קְשׁוֹט, דְּאִי לָאו זַכָּאָה אַנְתְּ, לָא יַרְחִישׁ לָךְ קוּדְשָׁא בְּרִיךְ הוּא נִיסָא רַבְרְבָא כְּמָה דַּעֲבַד. וּבְקַדְמֵיתָא טוֹל אַרְנָקִי דְדִינָרִין דִּילָךְ, וְתֶחֱמֵי מַה דַּעֲבֵיד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינָךְ.</p>"],[9514013373,"<p>אָזַל בַּהֲדַיְיהוּ, וְחָמָא הַהוּא גוֹי מֵת, וְחִוְיָא הֲוָה עָבִיד בֵּיהּ נוּקְמִין. וַהֲוָה כָּרִיךְ עַל קָדְלוֹי כִּדְבְקַדְמֵיתָא. אִשְׁתַּטַח הַהוּא יוּדָאי בְּעַפְרָא, וְאוֹדֵי וְשַׁבַּח לְמָארֵיהּ דְּעָלְמָא. וְקָם וּנְשַׁק יְדוֹי דְּרִבִּי אֶלְעָזָר וְחַבְרַיָיא, אֲמַר לוֹן, הַשְׁתָּא יְדַעְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ נִיסָא דָא בְּגִינַיְיכוּ.</p>"],[9514013374,"<p>אֲבָל רַבָּנָן, עַל אַבָּא וְאִימָא סָבִין דְּאִית לִי בָּכִינָא, וְעַל חַד מִסְכֵּינָא דִּיהַב לִי צְרוֹרָא דָא. פְּתַח הָאַרְנָקִי, וְאַחְמֵי לוֹן הַצְּרוֹרָא, וְכֵן אַחְמֵי לוֹן מְחָאָה, דְּעָבַד לֵיהּ הַהוּא גוֹי. צַלֵּי עֲלֵיהּ רַבִּי אֶלְעָזָר, וְאִיתְּסֵי.</p>"],[9514013375,"<p>קְרִיבוּ לְגַבֵּי הַהוּא גוֹי כְּמִלְקַדְמִין, וְחָמוּ הַהוּא חִוְיָא דְּהוּא עָבִיד בֵּיהּ נוּקְמִין כִּדְבְקַדְמֵיתָא. אֲמַר רִבִּי אֶלְעָזָר, חִוְיָא חִוְיָא, כָּל מַה דַּעֲבַדְתְּ, יָאוֹת עָבַדְתְּ. וְתוּ דְּאַחְמֵית חֵילָךְ וּגְבוּרְתָּךְ בֵּיהּ. וְעָבַדְתְּ נוּקְמִין סַגִּיאִין. וְהָא חָמֵינִין תְּלַת זִמְנִין, וְאַחְמֵית כָּל מַה דַּעֲבַדְתְּ. מִכָּאן וּלְהָלְאָה, זִיל וְאִתְטַמַּר בִּמְעַרְתָּךְ, וְגוֹזְרַנָא עֲלָךְ, דְּלָא תַּנְזֵיק לִבְרִיָּיתָא בְּעָלְמָא. אִתְפְּרַשׁ הַהוּא חִוְיָא, וְכָפֵיף רֵישֵׁיהּ, וַאֲזַל לֵיהּ.</p>"],[9514013376,"<p>אֲמַר רִבִּי אֶלְעָזָר לְהַהוּא יוּדָאי, טוֹל עֲדָאָה דְּשַׂנְאָךְ, דְּהָא כִּיסָא דְּדִינָרִין דְּדַהֲבָא אִית לֵיהּ לְגַבֵּיהּ. וּשְׁבוֹק לֵיהּ מָאנוֹי, וְלָא תִטוֹל מִדִּילֵיהּ כְּלוּם. וְזִיל לְגַבֵּי גַבְרָא דְדוּךְ פְּלַן, וְתִשְׁכַּח דְּמִיתַת אִתְּתֵיהּ, זִיל לְגַבֵּיהּ, וְהַב לֵיהּ כִּיסָא דְדִינָרִין דָּא, בְּגִין דְּהַהוּא גַבְרָא אִית לֵיהּ בְּרָא חָדָא, וְשִׁמְעוֹן שְׁמֵיהּ, וַהֲוָה אָזִיל בִּסְחוֹרָתָא עַל יַמָּא, וְאִינוּן בְּאַרְבָא, וּבְרֵיהּ דְּהַאי גוֹי גָּנַב לֵיהּ לְהַהוּא כִּיסָא, וִיהַב לֵיהּ לְהַהוּא רָשָׁע. וְאֵימָא לְהַהוּא יוּדָאי, דִּיסַלֵּק כִּיסָא דָא לִבְרֵיהּ, דְּלַעֲגָל יֵיתֵי לְגַבֵּיהּ, וְיוֹדֵי לְקוּדְשָׁא בְּרִיךְ הוּא, דְּאַחְזַר אֲבֵידְתָּא לְמָארֵיהּ. וְכָךְ עָבִיד, נָטַל כִּיסָא, וְאַסְגֵיד לְקַמֵּיהּ דְּרַבִּי אֶלְעָזָר, וּנְשַׁק יְדוֹי, תְּוָוהוּ חַבְרַיָיא.</p>"],[9514013377,"<p>אֲמַר רַבִּי אַבָּא, בְּכָל אָרְחָא דָא, אִית תְּוָוהוֹ, בְּכָל מַה דַּחֲמִינָן בָּךְ, וְהַשְׁתָּא אִיהוּ תְּוָוהָא עַל תְּוָוהָא. מַהוּ דֵּין. אָמַר לֵיהּ, מִלָּה דָא לָאו בְּסִימָנָא אִיהוּ, וְלָא בְּחָכְמָתָא, אֶלָּא רוּחָא דִילִי אִסְתַּכַּל, וַאֲנָא חָמִינָא, כְּאִלּוּ בְּעֵינָא חָמִינָא. תְּוָוהוּ כָּלְהוֹ חַבְרַיָיא. וַאֲזָלוּ כָּלְהוֹ, וְהַהוּא יוּדָאי בַּהֲדַיְיהוּ. עַד דְּמָטוּ לְגַבֵּי חָמוֹי. כֵּיוָן דְּמָטוּ תַּמָּן, אַשְׁכְּחוּהוּ לְחָמוֹי דַּהֲוֵי יָתִיב עַל גַּבֵּי עַרְסוֹי וְלָעֵי בְּאוֹרַיְיתָא, בְּרִיךְ בִּרְכְתָא רַבִּי אֶלְעָזָר, וּבְרִיכוּ חַבְרַיָיא, וְאִיהוּ חָדֵי בַּהֲדַיְיהוּ.</p>"],[9514013378,"<p>פְּתַח וַאֲמַר, (ירמיהו י״ז:י״ד) רְפָאֵנִי ה' וְאֵרָפֵא כו', כֵּיוָן דַּאֲמַר רְפָאֵנִי, מַהוּ וְאֵרָפֵא. כֵּיוָן דַּאֲמַר הוֹשִׁיעֵנִי, מַהוּ וְאִוָּשֵׁעָה. כֵּיוָן דְּאַסְיָא מַסֵּי, מַאן הוּא דְּמָחֵי.</p>"],[9514013379,"<p>אֶלָּא כָּל אַסְוָותָא דְּעָלְמָא, בִּידָא דְקוּדְשָׁא בְּרִיךְ הוּא. אֲבָל אִית מִנְהוֹן, עַל יְדָא דִשְׁלִיחָא. וְאִית מִנְהוֹן, דְּלָא אִתְמַסְּרוּ בִּידָא דִשְׁלִיחָא. וְאִינוּן דְּאִתְמַסְּרוּ בִּידָא דִּשְׁלִיחָא, אַסְוָותָא אִינוּן, אֲבָל לְזִמְנָא מִתְהַדְּרִין. אֲבָל אִינוּן דְקוּדְשָׁא בְּרִיךְ הוּא מַסֵּי, הַהוּא מַרְעָא לָא אִתְהַדַּר לְעָלְמִין. וְעַל דָּא, אַסְוָותָא דִילֵיהּ, אִיהִי אַסְוָותָא, דְּלֵית בָּהּ מַרְעָא כְּלָל. וּבְגִין כָּךְ, רְפָאֵנִי ה' וְאֵרָפֵא, וַדַאי, בְּלָא קִטְרוּגָא כְּלָל. וְהַשְׁתָּא חַבְרַיָיא, קוּדְשָׁא בְּרִיךְ הוּא יְהֵיב לִי אַסְוָותָא, וְעָשַׁק לִי וְעָרַב לִי.</p>"],[9514013380,"<p>סָחוּ לֵיהּ כָּל הַהוּא עוּבְדָא, תְּוָוהּ, וּבְכָה וְחָדֵי. וַאֲמַר, חַבְרַיָיא, נָדַרְנָא, דְּאֵיהַךְ לְגַבֵּיהּ, וְאֶתְחַבַּר בַּהֲדֵיהּ, וְנוֹדֶה וּנְשַׁבֵּחַ לְמָארֵי עָלְמָא. חָדֵי בַּהֲדַיְיהוּ.</p>"],[9514013381,"<p>אֲמָרוּ לֵיהּ, בְּמַאי הֲוֵית מִתְעַסֵּק. אֲמַר לוֹן, הֲוֵינָא מִשְׁתַּדֵּל בְּפ' בָּלָק, וְחָמִינָא, דְּחָכְמְתָא דִילֵיהּ, הֲוָה תַּקִּיף וְיַתִּיר מֵחָכְמְתָא דְבִלְעָם. חָכְמְתָא דְבִלְעָם רִגְעָא חָדָא, חָכְמְתָא דְבָלָק בְּכָל זִמְנָא. אֲבָל מַפְתְּחָן דְּכָלְהוֹ, בִּידוֹי דְבִלְעָם הֲווֹ. בְּגִין דְּאִיהוּ הֲוָה אַשְׁלֵים בְּפוּמָא. בָּלָק הֲוָה יָדַע לְמֶעְבַּד חָרָשׁוֹי, וְלָא יָדַע לְאַשְׁלָמָא בְּפוּמָא.</p>"],[9514013382,"<p>פְּתַח וַאֲמַר, (שם ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב כו'. הַאי קְרָא אוֹקְמוּהָ. אֲבָל אַל תִּירָא עַבְדִּי יַעֲקֹב, מֵחָרָשֵׁי דְבִלְעָם. וְאַל תֵּחָת, מִקִּסְמוֹי דְבָלָק.</p>"],[9514013383,"<p>תָּא חֲזֵי, הֵיאַךְ הֲווֹ תַּרְוַויְיהוּ דָּא בְּדָא בְּעֵיטָא בִּישָׁא לָקֳבֵיל יִשְׂרָאֵל. אֲמַר בִּלְעָם, יַעֲקֹב בְּבֵיתָא דְלָבָן אֲבִי אַבָּא הֲוָה, וּנְחַשׁ נְחָשִׁין לְקִבְלֵיהּ, וְיָכֵיל לֵיהּ. אֲנָא אֲסַדֵּר נְחָשִׁין לְקִבְלֵיהּ. אֲמַר בָּלָק, וַאֲנָא אֲסַדֵּר קוֹסְמִין לִשְׁמָא דְאִיקְרֵי יִשְׂרָאֵל.</p>"],[9514013384,"<p>בְּהַהִיא שַׁעֲתָא, נְפַק רוּחָא חָדָא מִסִּטְרָא דְיוֹסֵף, מִגּוֹ עַנְפֵי אִילָנָא, וְנָשֵׁיב בְּאִינוּן נְחָשִׁין, וּבַטֵיל לוֹן. וְהַיְינוּ דַּאֲמַר יוֹסֵף, (בראשית מ״ד:ט״ו) כִּי נַחֵשׁ יְנַחֵשׁ אִישׁ אֲשֶׁר כָּמוֹנִי. מַאי אִישׁ אֲשֶׁר כָּמוֹנִי. בְּגִינִי אִית אִישׁ דִּנְחָשִׁים יְבַטֵל לִבְנַיְיכוּ. בְּגִינִי אִיהוּ לְעֵילָא, וְהַיְינוּ אִישׁ אֲשֶׁר כָּמוֹנִי. כָּמוֹנִי אִית אִישׁ לְעֵילָא, דְּאַפֵּיק רוּחָא אָחֳרָא, מִגּוֹ אִילָנָא דִלְתַתָּא, וְנָשֵׁיב בְּהַהוּא קֶסֶם, וּבַטֵיל לֵיהּ.</p>"],[9514013385,"<p>וְהַיְינוּ (משלי ט״ז:י׳) קֶסֶם עַל שִׂפְתֵי מֶלֶךְ. מַאן מֶלֶךְ, דָּא אִילָנָא דִלְתַתָּא. כְּדֵין אָתֵיב בִּלְעָם וַאֲמַר, (במדבר כ״ג:כ״ג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל. וְתַרְוַויְיהוּ הֲווֹ מִתְּרֵין סִטְרִין אִלֵּין.</p>"],[9514013386,"<p>כִי אִתְּךָ אָנִי. לָא הֲווֹ יוֹמִין מִן יוֹמָא דְאִתְבְּרֵי עָלְמָא, דְּאִצְטְרִיךְ הָכֵי לְמֶהֱוֵי קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדַיְיהוּ דְיִשְׂרָאֵל, כְּהַהוּא זִימְנָא, דְּבָעָא בִּלְעָם לְשֵׁיצָאָה לְשַׂנְאֵיהוֹן דְיִשְׂרָאֵל מֵעָלְמָא. וְעַל דָּא אֲמַר קוּדְשָׁא בְּרִיךְ הוּא, בִּלְעָם בָּעָא לְשֵׁיצָאָה לְכוֹ מֵעָלְמָא, אֲבָל אֲנָא לָא אַעֲבֵיד הָכֵי, אֶלָּא (ירמיהו מ״ו:כ״ח) כִּי אֶעֱשֶׂה כָלָה בְּכָל הַגּוֹיִם אֲשֶׁר הִדַּחְתִּיךָ שָׁמָּה וְאֹתְךָ לֹא אֶעֱשֶׂה כָלָה.</p>"],[9514013387,"<p>דְּאִלּוּ יֵיתוֹן כָּל עַמִּין דְּעָלְמָא, לָא יָכְלִין לְשֵׁיצָאָה לְכוֹן מֵעָלְמָא. אָתָא לָבָן בְּקַדְמִיתָא, וּבָעָא לְאַעַקְרָא לֵיהּ לְיַעֲקֹב בִּלְחוֹדוֹי מֵעָלְמָא, אָתָא קוּדְשָׁא בְּרִיךְ הוּא, וְאָגֵין עֲלֵיהּ. דִּכְתִיב, (בראשית ל״א:כ״ד) הִשָּׁמֶר לְךָ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטוֹב עַד רָע. אָתָא פַּרְעֹה, וּבָעָא לְשֵׁיצָאָה לוֹן מֵעָלְמָא, אָתָא קוּדְשָׁא בְּרִיךְ הוּא וְאָגֵין עֲלֵיהוֹן, דִּכְתִיב, (שמות א׳:י״ב) וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ וְגו'. אָתָא הָמָן וּבָעָא לְשֵׁיצָאָה לוֹן מֵעָלְמָא, אָתָא קוּדְשָׁא בְּרִיךְ הוּא וַאֲתֵיב כּוֹלָא עַל רֵישֵׁיהּ. וְכֵן בְּכָל דָּרָא וְדָרָא, קוּדְשָׁא בְּרִיךְ הוּא אָגֵין עֲלַיְיהוּ דְיִשְׂרָאֵל תָּדִיר.</p>"],[9514013388,"<p>וְיִשְׂרָאֵל אָמְרֵי, (איכה ג׳:כ״ב) חַסְדֵּי ה' כִּי לֹא תָמְנוּ. כִּי לֹא תָמוּ מִבָּעֵי לֵיהּ. אֶלָּא חַסְדֵּי ה', בְּכָל דָּרָא וְדָרָא הֲווֹ בְּסַעֲדָן. כִּי לֹא תָמְנוּ, דְּלָא אִשְׁתֵּיצִינָנָא. מַאי טַעְמָא, מִשּׁוּם דְּלָא אִתְמְנָעוּ רַחֲמוֹי מִינָן. דִּכְתִיב, (שם) כִּי לֹא כָלוּ רַחֲמָיו.</p>"],[9514013389,"<p>תָּא חֲזֵי, מַה כְּתִיב בְּקַדְמִיתָא, (במדבר כ״ב:ז׳) וַיִּשְׁלַח מַלְאָכִים אֶל בִּלְעָם. וּלְבָתַר וַיֵּלְכוּ זִקְנֵי מוֹאָב וְזִקְנֵי מִדְיָן, הֲוָה לֵיהּ לְמֵימַר וַיֵּלְכוּ הַמַּלְאָכִים, מַאי טַעְמָא קָא שָׁנֵי מִלָּה מִמַּאי דְּקָאֲמַר בְּקַדְמִיתָא.</p>"],[9514013390,"<p>אֶלָא הַהוּא רָשָׁע דְּבָלָק, חַכִּים הֲוָה בְּכָל דַּרְגִּין דִּלְעֵילָא, אִינוּן דְּקָשְׁרִין קִשְׁרִין, לְמֶעְבַּד בְּהוּ חָרָשִׁין וְקוֹסְמִין. וְכָל אִינוּן דַּרְגִּין עִילָאִין מִינַיְיהוּ, דִּבְהוֹ כַּפְיָין לְדַרְגִּין תַּתָּאִין.</p>"],[9514013391,"<p>אֲמַר לֵיהּ, בְּכָל זִמְנָא דַּאֲנַן חָרָשִׁין וְקָסְמִין וְנָחֲשִׁין, אִית לָן דַּרְגִּין וּמַלְאָכִים יְדִיעָן, וְאִשְׁתְּמוֹדְעָן לְגַבֵּי חָרָשִׁין וְקוֹסְמִין, אֲבָל מִכָּאן וּלְהָלְאָה, אִית לָךְ לְעַיְינָא בַּאֲתַר אָחֳרָא עִילָאָה.</p>"],[9514013392,"<p>כָתַב לֵיהּ שְׁמָהָן אָחֳרָנִין, בְּאִינוּן דַּרְגִּין קַדִּישִׁין. וְהָכֵי אוֹרְחַיְיהוּ דְּקוֹסְמִין וְחָרָשִׁין, דְּיָדְעֵי אִינוּן דַּרְגִּין דְּהַהוּא קֶסֶם שַׁרְיָיא בְּהוּ, וְעָבְדִין חָרָשַׁיְיהוּ, וְאוֹמֵי לְהוֹן בְּדַרְגִּין אָחֳרָנִין עִילָאִין מִינַיְיהוּ, וְעָבְדֵי מַה דְּעָבְדֵי.</p>"],[9514013393,"<p>שַׁלַּח לֵיהּ הָכֵי. עַמָּא דָא, לָאו קִשְּׁרָא דִילְהוֹן כִּשְׁאָר עַמִּין דְּעָלְמָא, אֲבָל קִשְּׁרָא דִּילְהוֹן בַּאֲתַר אָחֳרָא עִילָאָה, מִתְקַשְּׁרָא. לְעֵילָא מִכָּל דַּרְגִּין.</p>"],[9514013394,"<p>כְתַב וְשַׁלַּח לֵיהּ, פִּיפוּסָא וּפַטְרוֹנָא דִּתְרֵיסַר נִצוֹצִין, דְּסָחֲרָן גַּלְגְּלֵי רְתִיכָא דְּכוּרְסְיָיא קַדִּישָׁא, וְאָמַר לֵיהּ, אִי תִּסְתַּכֵּל בְּהַנֵּי, בְּהַנֵּי תִּסְתַּכֵּל, בְּגִין דְּהַנֵּי תְּרֵיסַר מִתְקַשְּׁרָן בְּי\"ב שְׁבָטִים. וְאִי בְּהַנֵּי תַּעֲבֵיד חָרָשִׁין, בְּדִיוֹקְנָא דִּילְהוֹן לְתַתָּא, דְּאִינוּן י\"ב שְׁבָטִים, וְי\"ב דִּגְלִין פְּרִישָׂן, נֵיכוֹל לוֹן, וְנִיגַח בְּהוֹן קְרָבָא, וּנְעַקֵּר לוֹן מֵעָלְמָא.</p>"],[9514013395,"<p>וְהַיְינוּ וַיִּשְׁלַח מַלְאָכִים, מַלְאָכִים וַדַּאי. וּקְסָמִים בְּיָדָם, פִּיפּוּסִים דְּמַלְאָכִין קַדִּישִׁין, הֲווֹ אַתְיָין בִּידַיְיהוּ. וְאִיהוּ לָא יָדַע, דְּכָל דַּרְגִּין עִילָאִין, בִּידָא דְקוּדְשָׁא בְּרִיךְ הוּא אִינוּן. מַה חָשִׁיב בָּלָק. חָשִׁיב, דְּעַמָּא דְּיִשְׂרָאֵל אִתְמַסְרוּ לְמַלְאָכִין, כִּשְׁאָר עַמִּין דְּעָלְמָא. וְעַל דָּא כָּתַב שְׁמָהָן דְּאִלֵּין מַלְאָכִים תְּרֵיסַר, וּשְׁלַח לֵיהּ, וְהַיְינוּ וַיִּשְׁלַח מַלְאָכִים.</p>"],[9514013396,"<p>אָמַר לֵיהּ תָּא חֲזֵי, כָּל דַּרְגִּין דְּאִינוּן מְקַשְּׁרָן קְשָׁרִין, לְתַבְרָא עַמָּא דָא, מִסִּטְרָא דְצָפוֹן אִינוּן. וּמִסִּטְרָא דְצָפוֹן זְמִינִין לְמִנְפַּל. שׁוּלְטָנוֹ דְּחָרָשִׁין דִּילָן, מִסִּטְרָא דְצָפוֹן אִינוּן. הַשְׁתָּא נֵיכוֹל לַאֲגָחָא בְּהוֹן קְרָבָא, דְּהָא י\"ב אִלֵּין דְּאִינוּן מִתְקַשְׁרָאן בְּהוּ, מִסִּטְרָא דְצָפוֹן שַׁרְיָין לְמִימְנֵי.</p>"],[9514013397,"<p>וְהוֹאִיל וּמִשְׂמָאלָא שַׁרְיָין תּוּקְפָא דִילְהוֹן, אִתְחַלָּשׁ וְאִתְבַּר, בְּגִין דְּכָל תּוּקְפָא דִילְהוֹן לְהַהוּא סִטְרָא אִיהוּ. מַהוּ, דִּכְתִיב, (מלכים א ז׳:כ״ה) עוֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלשָׁה פּוֹנִים צָפוֹנָה. מִצָּפוֹן שָׁארֵי לְמִמְנֵי. אֲמַר, הָא תּוּקְפָא דִילָן מִצָּפוֹן אִיהוּ, וְאִינוּן מ' חָסֵר חַד דַּרְגִּין, תַּקִּיפִין מִפַּרְזְלָא וּנְחָשָׁא. וּתְחוֹתַיְיהוּ לֵית לוֹן חוּשְׁבְּנָא. וְעַל דָּא נֵיכוֹל לַאֲגָחָא בְּהוֹן קְרָבָא, וּלְאִיתְגָרֵי בְּהוּ.</p>"],[9514013398,"<p>וְקוּדְשָׁא בְּרִיךְ הוּא לָא עָבִיד הָכֵי, דְּלָא שָׁבֵיק לוֹן לַמַּלְאָכִין, וְלָא לְחֵילֵי שְׁמַיָיא, אֶלָּא לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וְכָל אִילָנִין רַבְרְבִין וְשׁוּלְטָנִין, פָּלַג עַל כָּל שְׁאָר עַמִּין. וְכַד אָתוֹ יִשְׂרָאֵל, נָטֵיל לוֹן אִיהוּ בִּלְחוֹדוֹי, וְאַחְסֵין לוֹן בְּתוֹקְפָא דְּנוֹפָא דְאִילָנָא, וְלָא שָׁבֵיק לוֹן בִּידָא דְמַלְאָכִין, וְלֹא בִידָא דִּמְמַנָּא וְרַבְרְבִין דְּעָלְמָא. דִּכְתִיב, (דברים ל״ב:ח׳) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם וְגו'. וְאִלֵּין י\"ב תְּחוּמִין, מִתְתַּחֲמָן בְּד' סִטְרֵי עָלְמָא, לְבָתַר דְּבַדַּר עֲנָפִין וְטַרְפִּין, נָטַל לְיִשְׂרָאֵל וְאַחְסֵין לוֹן בְּתוּקְפָא דְּנוֹפָא דְאִילָנָא. דִּכְתִיב, (שם) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9514013399,"<p>אָמַר רִבִּי אֶלְעָזָר, כַּמָּה יָאוֹת וְשַׁפִּיר הַאי דַּאֲמַרְתְּ, זַכָּאָה אוֹרְחָא דִילָן, דְּכַמָּה מִלִּין עִילָאִין קַדִּישִׁין רַוַוחְנָא לוֹן וְחָמֵינָא. וְהַהוּא יוּדָאי הֲוָה תַּמָּן לְקַמַּיְיהוּ. אֲמַר לוֹן, רַבָּנָן, כָּל מִלִּין אִלֵּין, כַּמָּה טָבָאן, וּמִלִּין עִילָּאִין קַדִּישִׁין נִינְהוּ. מַהוּ דִכְתִיב בַּתְרֵיהּ, (שם) יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וכו'.</p>"],[9514013400,"<p>אֲמַר לֵיהּ, אִי יְדַעְתְּ בֵּיהּ מִלָּה, אֵימָא. דְּהָא מִלָּה דָא אוֹקְמוּהָ בְּאַבְרָהָם, דְּאַשְׁכַּח לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא דְּפָלְחֵי עֲבוֹדָה זָרָה, וְלָא יָדְעֵי בִּמְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא כָּלְהוֹ הֲווֹ טָעָאן בָּתַר עֲבוֹדָה זָרָה, וְקָם אַבְרָהָם, וּפָרַח בֵּינַיְיהוּ עַנְפָא חָדָא שְׁלִים, קָדָם מָארֵי דְעָלְמָא, וְאַשְׁכַּח לֵיהּ תַּמָּן.</p>"],[9514013401,"<p>מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, נְטַל לֵיהּ לְהַהוּא עֲנָפָא, וּנְטַע לֵיהּ, וְאַשְׁקֵי לֵיהּ, וְאִשְׁתַּדֵּל עֲלֵיהּ, וְאַעֲקַר לֵיהּ מִתַּמָּן, וְאַשְׁתִּיל לֵיהּ בְּאַרְעָא אָחֳרָא. דִּכְתִיב, (בראשית יב) לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ. וְעָבַד מִנֵּיהּ עַמָּא קַדִּישָׁא, וְדָא הִיא מְצִיאָה דְּאַשְׁכַּח קוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא, דְּלָא מְהֵימְנָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא יָדְעֵי מַאן אִיהוּ.</p>"],[9514013402,"<p>אֲמַר הַהוּא יוּדָאי, וַדַּאי שַׁפִּיר הוּא, וְיָאוֹת כֹּלָּא. אֲבָל אִית לְשָׁאֲלָה, אִי אַבְרָהָם הֲוָה דְיוֹקְנָא דְּאִצְטְרִיךְ. וְתוּ דְּהָא קְרָא לָא אוֹכַח עַל אַבְרָהָם כְּלַל, וְלָא אִדְכַּר לְאַבְרָהָם, וְלָא לְיִצְחָק, אֶלָּא לְיַעֲקֹב בִּלְחוֹדוֹי. דִּכְתִיב, (דברים ל) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, וּכְתִיב בַּתְרֵיהּ יִמְצָאֵהוּ.</p>"],[9514013403,"<p>אָמַר רִבִּי אֶלְעָזָר, עִם כָּל זֶה לָא קַשְׁיָא הָכָא, דְּהָא אַבְרָהָם אַשְׁכָּחָן דְּנָפַק מִגּוֹ פַּלְחֵי עֲבוֹדָה זָרָה. וְהָכָא אַף עַל גַּב דְּיַעֲקֹב אִדְכַּר, הוּא קָאי עַל אַבְרָהָם, וְלֵית פֵּירוּכָא כְּלַל בַּמִּלָּה. אֲבָל אִי יְדַעְתְּ מִילָה אוֹ חִידוּשָׁא, אֵימָא.</p>"],[9514013404,"<p>פְּתַח הַהוּא יוּדָאי וַאֲמַר, (בראשית א) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, מַאן אֶרֶץ. הַהִיא דְּאִשְׁתְּמוֹדְעָא עֵילָא וְתַתָּא. הָיְתָה תֹהוּ, מַאי תֹהוּ, דָּא קַו יָרוֹק, דְּאַקֵּיף כָּל עָלְמָא. וְאִיקְרֵי קַו תֹּהוּ, דִּכְתִיב, (ישעיה לד) וְנָטָה עָלֶיהָ קַו תֹהוּ וְאַבְנֵי בֹהוּ. כְּמָה דְתָנִינָן, אַבְנִין מְפוּלְמוֹת דְּמִשְׁתַּקְעִין גּוֹ תְּהוֹמֵי, וּמִנְהוֹן נָפְקִין מַיִין.</p>"],[9514013405,"<p>הַשְׁתָּא אִית לְמִנְדַע, תֹּהוּ דְּאִיהוּ קַו יָרוֹק, מַאי הוּא קַו יָרוֹק, אֶלָּא אַשְׁכְּחָן בְּסִפְרָא דְאַסְיָיא קִירְטִינָא, וְיוּדָן דְּקֵסָרִי שְׁמֵיהּ, וְקָרָאן שְׁמֵיהּ קִירְטִינָא אַסְיָיא, בְּגִין דְּאִיהוּ רַב עַל כָּל אַסְיָין, וְיַקִּירָא בְּחָכְמְתָא. וְהָכֵי בְּלָשׁוֹן פַּרְסִי, לְבַּר נָשׁ יַקִּירָא, קָרָאן לֵיהּ קִירְטִינָא. רַב וְיַקִּירָא בְּחָכְמְתָא. וַהֲוָה אֲמַר, וְהָאָרֶץ הָיְתָה תֹהוּ, מַאי תֹהוּ. אִיהוּ קַו יָרוֹק, דְּאַסְחַר כָּל עָלְמָא. וּמַאן אִיהוּ, קְלִיפָּה דֶּאֱגוֹזָא. וְדָא אִיהוּ קְלִיפָּה דִּלְבַר, דְּאִיהוּ יָרוֹק.</p>"],[9514013406,"<p>לְגוֹ מִנֵּיהּ, בֹּהוּ. אִינוּן אֲבָנִין מְפוּלָמוֹת דְּמִנְהוֹן נָפְקֵי מַיָיא. מִן תֹּהוּ אִתְמְשֵׁיךְ עוֹר וּבָשָׂר. מִן בֹּהוּ אִתְמַשְּׁכוּ גַּרְמֵי.</p>"],[9514013407,"<p>לְגוֹ מִנֵּיהּ וְחשֶׁךְ. דָּא חֲשִׁיכוּ דְּאִתְמְשַׁךְ מִנֵּיהּ עַמָּא דְעֵשָׂו. וְאִיתֵימָא מִן תֹּהוּ. הָכֵי הוּא וַדַּאי, דְּהָא חשֶׁךְ מִנֵּיהּ תַּלְיָיא תֹהוּ. אֶלָּא אִינוּן אַבְנִין מְפוּלָמוֹת, עָאלוּ בְּאֶמְצָעִיתָא, דְּמִנֵּיהּ אִתְמַשְּׁכָן גַּרְמִין, כְּמָא דְאִיתְּמָר. וְחשֶׁךְ מְשִׁיכוּ דַּקִּיק, דְּמִנֵּיהּ אִתְמְשַׁךְ עֵשָׂו.</p>"],[9514013408,"<p>וְרוּחַ אֱלֹהִּים, דָּא מוֹחָא דֶּאֱגוֹזָא, דְּמִתַּמָּן אִיתְמְשַׁךְ יַעֲקֹב שְׁלֵימָא, כְּגַוְונָא דֶּאֱגוֹזָא דָא, דִּכְתִיב, (יחזקאל א) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, לְקִבְלֵיהּ דְּתֹהוּ. לְגוֹ מִנֵּיהּ עָנָן גָּדוֹל, לְקִבְלֵיהּ דְּבֹהוּ. לְגוֹ מִנֵּיהּ וְאֵשׁ מִתְלַקַּחַת, לְקִבְלֵיהּ דְּחשֶׁךְ. לְגוֹ מִנֵּיהּ וְנֹגַהּ לוֹ סָבִיב, לְקִבְלֵיהּ דִּוְרוּחַ אֱלֹהִים.</p>"],[9514013409,"<p>וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל, לְגוֹ מִכֹּלָּא. דִּלְקִבְלֵיהּ, מְרַחֶפֶת עַל פְּנֵי הַמָּיִם. דָּא רוּחַ דְּאִימָא עִילָאָה, דְּקָא מְרַחֲפָא עַל כֹּלָּא. וְיַעֲקֹב שְׁלֵימָא, אִיהוּ וַדַּאי מוֹחָא דֶאֱגוֹזָא. וְהַקָדוֹשׁ בָּרוּךְ הוּא יִמְצָאֵהוּ בְּאֶרֶץ מִדְבָּר וַדַּאי. לְבָתַר עָבַד הַקָדוֹשׁ בָּרוּךְ הוּא לְכָל אִינוּן קְלִיפִּין דִּלְּהוֹן, דִּיהוֹן כָּלְהוֹן מִשְׁתַּעְבְּדִין לֵיהּ.</p>"],[9514013410,"<p>(במדבר כ״ד:י״ז) אֶרְאֶנּוּ וְלֹא עַתָּה אֲשׁוּרֶנּוּ וְלֹא קָרוֹב דָּרַךְ כּוֹכָב מִיַּעֲקֹב וְקָם שֵׁבֶט מִיִּשְׂרָאֵל וְגו'. אֶרְאֶנּוּ, לְמִלָּה דְּפוּרְקָנָא דָּא, דְּאִיהוּ רְבִיעָאָה. וְלֹא עַתָּה, אֶלָּא לְסוֹף יוֹמַיָיא.</p>"],[9514013411,"<p>שִׁית יוֹמִין הֲווֹ בְּעָלְמָא, בְּיוֹמָא רְבִיעָאָה חָמֵינָא, דִּנְהוֹרִין דַּהֲווֹ בֵּיהּ, מִסְתַּלְּקֵי וּמִתְדַעֲכֵי. שִׁמְשָׁא וְסִיהֲרָא וְכוֹכָבַיָיא וּמַזָּלֵי אִתְגְּנִיזוּ בֵּיהּ. הַנִּי אִתְהֲווֹ בְּעוֹבָּדָא דִבְרֵאשִׁית, וּבֵיהּ אִסְתַּלָּקוּ בְּיוֹמָא דְאֶלֶף רְבִיעָאָה.</p>"],[9514013412,"<p>בְּכָה רַבִּי שִׁמְעוֹן וַאֲמַר, וַוי דְגָלוּתָא אִתְמְשַׁךְ, וּמַאן יָכִיל לְמִסְבֵּל לֵיהּ. אֲמַר לֵיהּ, אִי רַבִּי אִי רַבִּי, אִלּוּ הֲוֵית יָדַע כַּמָּה עִרְטוּלָא וּבִלְבּוּלָא, עָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּכָלְהוֹ רְקִיעִין, בְּשַׁעֲתָא דְּגָזַר וּמְסָר לוֹן לְיִשְׂרָאֵל בִּידָא דְּהַהִיא שִׁפְחָה, וּלְאִשְׁתַּעְבָּדָא תְּחוֹת יְדָא דֶאֱדוֹם.</p>"],[9514013413,"<p>בְּשַׁעֲתָא דַּהֲווֹ כָּתְבֵי פִּתְקִין בִּרְקִיעָא, עַד דְּלָא אַחְתִּימוּ, בְּגוּשְׁפַּנְקָא דְּחוֹתְמָא דְמַלְכָּא, קְרָא קוּדְשָׁא בְּרִיךְ הוּא לְכָל חֵילֵי שְׁמַיָיא, וּקְרָא לְגַבְרִיאֵל דְּקֶסֶת הַסּוֹפֵר בְּחַרְצוֹי, וַאֲמַר לֵיהּ, אִיעַכַּב פִּתְקִין עַד דְּלָא אַחְתִּימוּ, וְאֶבְכֶּה עַל בָּנַי, וְאַעֲבֵיד לְהוֹן מִסְפְּדָא וְאֶבְלָא. בְּאוֹמָאָה עֲלַיְיכוּ, כָּל חֵילָא דִשְׁמַיָא, דְּתִשְׁבְּקוּן לִי, וְלָא תִתְקְפוּן לְנַחֲמָא לִי. כְּמָה דְאַתְּ אָמֵר, (ישעיה כב) עַל כֵּן אָמַרְתִּי שְׁעוּ מִנִּי אֲמָרֵר בַּבֶּכִי אַל תָּאִיצוּ לְנַחֲמֵנִי עַל שֹׁד בַּת עַמִּי.</p>"],[9514013414,"<p>בְּעַט בְּעִיטִין בִּרְקִיעָא דַעֲרָבוֹת, וַעֲבַד בֵּיהּ בְּקוּעִין וְחַלּוֹנִין פְּתִיחִין. פְּתַח וַאֲמַר, בָּנַי, בָּנַי רְחִימוּ דְּמֵעַיי, רִבִּיתִי לְכוֹן, וּנְטָלִית לְכוֹן, כְּאַבָּא דִּנְטֵיל לִבְרֵיהּ, אוֹלִיפְנָא לְכוֹ דַּחַלְתִּי, אַשְׁלֵטִית לְכוֹ עַל כָּל אוּמִּין דְּעָלְמָא. חַבְתּוּן קַמָּאי בְּכַמָּה חוֹבִין, עָבַרְנָא עֲלַיְיכוּ, בְּגִין דִּבְנִין יַקִּירִין רְחִימִין הֲוֵויתָן קַמָּאי.</p>"],[9514013415,"<p>בָּנַי בָּנַי, אֶקְרָא לְאַרְבַּע סִטְרִין דְּעָלְמָא, וְאוֹמֵינָא לְהוֹ עֲלַיְיכוּ. מִזְרָח מִזְרָח, בְּאוֹמָאָה עֲלָךְ, אִי בָּנַי יִתְבַּדְּרוּן בֵּינָךְ, דְּתִסְתַּכֵּל בְּתוֹאֲרָא וּדְיוֹקְנָא דִילְהוֹן, הֵיךְ אִשְׁתַּנֵּי וְאִשְׁתַּחַר בְּעִנּוּיִין דְּעָבְדוּן לוֹן בְּגַוָּוךְ, וְתִבְכֶּה וְתִסְפַּד עֲלֵיהוֹן וְתִנְטַר לוֹן.</p>"],[9514013416,"<p>בָּנַי בָּנַי, כַּד הֲוֵיתוּן בְבֵיתָאי, בְּתוּקְפָא דְּאִמְכוֹן, בְּעִידּוּנִין בְּעִינּוּגִין, לָא אַשְׁגַּחְתּוּן עָלַי. בָּנַי בָּנַי, מָה אַעֲבֵיד לְכוֹן, גְּזֵירָא גָּזַרְנָא בְּאוֹמָאָה, אֶלָּא אֲנָא וְאַתּוּן נִגְלֵי.</p>"],[9514013417,"<p>משֶׁה רַעֲיָיא מְהֵימְנָא, אֵיךְ לָא תַשְׁגַּח עַל בָּנַי, עָנָא קַדִּישָׁא דִּמְסָרִית בִּידָךְ. מִזְרָח מִזְרָח, אִתְעָרֵי לְגַבֵּי משֶׁה, וְתִבְכּוּן וְתִסְפְּדוּן עַל בָּנַי, אֶבְלָא וּמִסְפְּדָא אַשְׁמָעוּ כַּחֲדָא, עַד דַּאֲנָא אֶשְׁמַע וְאֶתְרַוֵּי עִמְּכוֹן.</p>"],[9514013418,"<p>בָּנַי בָּנַי, רְחִימִין דְנַפְשָׁאי, הֵיךְ תֶּהֱכוּן בְּשַׁלְשְׁלָאִין תַּקִּיפִין, יֶדְכוֹן מְהַדְּקָן לַאֲחוֹרָא. בְּנִין דְּאִתְרַבִּיאוּ בְּעִידּוּנִין, בְּנִין דַּהֲווֹ יַקִּירִין מִפָּז וְסַפִּירִין. בָּנַי בָּנַי, חֲסִידִין קַדִּישִׁין, הֵיךְ תִּפְּלוּן בִּידֵי נוּכְרָאִין, דְּלָא רַחֲמִין כְּלָל. בִּשְׂרָא קַדִּישָׁא דְּגוּפֵיכוֹן, אִיתְרַמֵּי וְאִתְחַלֵּל בַּשְׁוָוקִים וּבָרְחוֹבוֹת. בָּנַי בָּנַי, וַוי עֲלֵיכוֹן וְעָלַי. כְּדֵין בָּזַע פּוּרְפִּירָא דִילֵיהּ. וְהַיְינוּ דִכְתִיב, בִּצַּע אֶמְרָתוֹ.</p>"],[9514013419,"<p>דָּרוֹם דָּרוֹם, בְּאוֹמָאָה עֲלָךְ, כַּד יִתְבַּדְּרוּן בָּנַי בְּגַוָּוךְ, דְּתִסְתַּכֵּל בְּהוּ הֵיךְ מְשַׁחֲרָא דְּיוֹקְנֵיהוֹן, וִימִינְהוֹן תְּבִירִין בֵּינֵי עַמְּמַיָא. דָּרוֹם דָּרוֹם, בְּאוֹמָאָה עֲלָךְ, אִתְעַר לְגַבֵּי אַבְרָהָם רְחִימָאי, וְאֵימָא לֵיהּ אֵיךְ נָפְלוּ בְּנוֹי, וְאִתְבַּדְּרוּ בֵּין שַׂנְאֵיהוֹן, וְתִבְכּוּן וְתִסְפְּדוּן עֲלֵיהוֹן. דָּרוֹם דָּרוֹם, בְּאוֹמָאָה עֲלָךְ, דְּתִנְטַר בָּנַי רְחִימוּ דְּנַפְשָׁאי, כַּד יִתְבַּדְּרוּן בְּגַוָּוךְ.</p>"],[9514013420,"<p>צָפוֹן צָפוֹן, אִתְעַר בְּקוֹל בְּכִיָה וּמִסְפֵּד וְאֶבְלָא וִיגוֹנָא לְגַבֵּי בָּנַי. וְאֵימָא לֵיהּ לַעֲקֵידָא דְמִדְבְּחִי, הֵיךְ אָזְלִין בְּנוֹי, וְהֵיךְ נָפְלוּן בְּחַרְבָּא. לָא תֵימְרוּן דָּא, וְלָא תְהוֹדְעוּן דָּא לְיַעֲקֹב אֲבוּהוֹן. דְּלָא יֵהָפֵךְ עַלְמָא בְּרִיגְעָא.</p>"]]});
